static bool push_enum_member(VcSemanticStruct *structure, const char *name, int64_t value)
{
    if (structure->enum_member_count == structure->enum_member_capacity)
    {
        const size_t capacity = structure->enum_member_capacity == 0 ? 8 : structure->enum_member_capacity * 2;
        const char **names = realloc(structure->enum_member_names, capacity * sizeof(*names));
        if (names == NULL)
            return false;
        int64_t *values = realloc(structure->enum_member_values, capacity * sizeof(*values));
        if (values == NULL)
        {
            structure->enum_member_names = names;
            return false;
        }
        structure->enum_member_names = names;
        structure->enum_member_values = values;
        structure->enum_member_capacity = capacity;
    }

    structure->enum_member_names[structure->enum_member_count] = name;
    structure->enum_member_values[structure->enum_member_count] = value;
    structure->enum_member_count++;
    return true;
}

static bool parse_enum_integer_literal(const char *text, int64_t *value)
{
    if (text == NULL || value == NULL)
        return false;

    size_t length = strlen(text);
    while (length > 0 && strchr("uUlL", text[length - 1]) != NULL)
        length--;
    if (length == 0)
        return false;

    unsigned base = 10;
    size_t position = 0;
    if (length >= 2 && text[0] == '0' && (text[1] == 'x' || text[1] == 'X'))
    {
        base = 16;
        position = 2;
    }
    else if (length >= 2 && text[0] == '0' && (text[1] == 'b' || text[1] == 'B'))
    {
        base = 2;
        position = 2;
    }

    uint64_t result = 0;
    bool saw_digit = false;
    for (; position < length; position++)
    {
        const char c = text[position];
        if (c == '_')
            continue;
        unsigned digit;
        if (c >= '0' && c <= '9') digit = (unsigned)(c - '0');
        else if (c >= 'a' && c <= 'f') digit = (unsigned)(c - 'a') + 10u;
        else if (c >= 'A' && c <= 'F') digit = (unsigned)(c - 'A') + 10u;
        else return false;
        if (digit >= base || result > (UINT64_MAX - digit) / base)
            return false;
        result = result * base + digit;
        saw_digit = true;
    }

    if (!saw_digit || result > INT64_MAX)
        return false;
    *value = (int64_t)result;
    return true;
}

static bool evaluate_enum_value(const VcAstNode *expression, int64_t *value)
{
    if (expression == NULL || value == NULL)
        return false;
    if (expression->kind == VC_AST_LITERAL_EXPRESSION &&
        expression->as.literal_expression.literal_kind == VC_AST_LITERAL_NUMBER)
        return parse_enum_integer_literal(expression->as.literal_expression.text, value);
    if (expression->kind == VC_AST_PARENTHESIZED_EXPRESSION)
        return evaluate_enum_value(expression->as.parenthesized_expression.expression, value);
    if (expression->kind == VC_AST_UNARY_EXPRESSION &&
        (expression->as.unary_expression.operator_kind == VC_TOKEN_PLUS ||
         expression->as.unary_expression.operator_kind == VC_TOKEN_MINUS))
    {
        int64_t operand = 0;
        if (!evaluate_enum_value(expression->as.unary_expression.operand, &operand))
            return false;
        if (expression->as.unary_expression.operator_kind == VC_TOKEN_MINUS)
        {
            if (operand == INT64_MIN)
                return false;
            operand = -operand;
        }
        *value = operand;
        return true;
    }
    return false;
}

static bool enum_value_fits(VcSemanticType underlying, int64_t value)
{
    switch (underlying)
    {
        case VC_SEM_TYPE_SBYTE: return value >= INT8_MIN && value <= INT8_MAX;
        case VC_SEM_TYPE_BYTE: return value >= 0 && value <= UINT8_MAX;
        case VC_SEM_TYPE_SHORT: return value >= INT16_MIN && value <= INT16_MAX;
        case VC_SEM_TYPE_USHORT: return value >= 0 && value <= UINT16_MAX;
        case VC_SEM_TYPE_INT: return value >= INT32_MIN && value <= INT32_MAX;
        case VC_SEM_TYPE_UINT: return value >= 0 && (uint64_t)value <= UINT32_MAX;
        case VC_SEM_TYPE_LONG: return true;
        case VC_SEM_TYPE_ULONG: return value >= 0;
        default: return false;
    }
}

static bool constant_field_type_supported(const VcSemanticModel *model, VcSemanticType type)
{
    if (semantic_type_is_enum(model, type))
        return true;

    switch (type)
    {
        case VC_SEM_TYPE_BOOL:
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
        case VC_SEM_TYPE_STRING:
            return true;
        default:
            return false;
    }
}

static bool push_interface(VcSemanticStruct *structure, size_t interface_index)
{
    for (size_t i = 0; i < structure->interface_count; i++)
    {
        if (structure->interfaces[i] == interface_index)
            return true;
    }

    if (structure->interface_count == structure->interface_capacity)
    {
        const size_t capacity = structure->interface_capacity == 0 ? 4 : structure->interface_capacity * 2;
        size_t *items = realloc(structure->interfaces, capacity * sizeof(*items));
        if (items == NULL)
            return false;
        structure->interfaces = items;
        structure->interface_capacity = capacity;
    }
    structure->interfaces[structure->interface_count++] = interface_index;
    return true;
}

