static bool push_binding(VcSemanticModel *model, VcSemanticBinding binding)
{
    for (size_t i = 0; i < model->binding_count; i++)
    {
        if (model->bindings[i].node == binding.node)
        {
            free(model->bindings[i].argument_parameters);
            model->bindings[i] = binding;
            return true;
        }
    }

    if (model->binding_count == model->binding_capacity)
    {
        const size_t capacity = model->binding_capacity == 0 ? 64 : model->binding_capacity * 2;
        VcSemanticBinding *bindings = realloc(model->bindings, capacity * sizeof(*bindings));
        if (bindings == NULL)
            return false;
        model->bindings = bindings;
        model->binding_capacity = capacity;
    }

    model->bindings[model->binding_count++] = binding;
    return true;
}


static bool push_lambda(VcSemanticModel *model, VcSemanticLambda value, size_t *index)
{
    if (model->lambda_count == model->lambda_capacity)
    {
        const size_t capacity = model->lambda_capacity == 0 ? 8 : model->lambda_capacity * 2;
        VcSemanticLambda *items = realloc(model->lambdas, capacity * sizeof(*items));
        if (items == NULL)
            return false;
        model->lambdas = items;
        model->lambda_capacity = capacity;
    }
    if (index != NULL)
        *index = model->lambda_count;
    model->lambdas[model->lambda_count++] = value;
    return true;
}

static bool lambda_push_capture(VcSemanticLambda *lambda, VcSemanticCapture capture)
{
    for (size_t i = 0; i < lambda->capture_count; i++)
    {
        VcSemanticCapture *existing = &lambda->captures[i];
        if (capture.kind == VC_SEM_CAPTURE_THIS && existing->kind == VC_SEM_CAPTURE_THIS)
            return true;
        if (capture.kind == VC_SEM_CAPTURE_LOCAL && existing->kind == VC_SEM_CAPTURE_LOCAL &&
            existing->scope_kind == capture.scope_kind &&
            existing->scope_index == capture.scope_index &&
            existing->scope_node == capture.scope_node &&
            existing->declaration_node == capture.declaration_node &&
            strcmp(existing->name, capture.name) == 0)
            return true;
    }
    if (lambda->capture_count == lambda->capture_capacity)
    {
        const size_t capacity = lambda->capture_capacity == 0 ? 4 : lambda->capture_capacity * 2;
        VcSemanticCapture *items = realloc(lambda->captures, capacity * sizeof(*items));
        if (items == NULL)
            return false;
        lambda->captures = items;
        lambda->capture_capacity = capacity;
    }
    lambda->captures[lambda->capture_count++] = capture;
    return true;
}

const VcSemanticBinding *vc_semantic_binding(const VcSemanticModel *model, const VcAstNode *node)
{
    for (size_t i = 0; i < model->binding_count; i++)
    {
        if (model->bindings[i].node == node)
            return &model->bindings[i];
    }
    return NULL;
}

static VcSemanticBinding *semantic_binding_mutable(VcSemanticModel *model, const VcAstNode *node)
{
    for (size_t i = 0; i < model->binding_count; i++)
    {
        if (model->bindings[i].node == node)
            return &model->bindings[i];
    }
    return NULL;
}

static bool same_namespace(const char *left, const char *right)
{
    if (left == NULL || right == NULL)
        return left == right;
    return strcmp(left, right) == 0;
}

static const VcSource *semantic_source_for_ast_pointer(
    const VcSemanticModel *model,
    const void *pointer)
{
    if (model == NULL || pointer == NULL)
        return NULL;
    for (size_t i = 0; i < model->unit_count; i++)
    {
        if (model->units[i].tree != NULL &&
            vc_ast_tree_contains(model->units[i].tree, pointer))
            return model->units[i].source;
    }
    return NULL;
}

static bool collect_using_alias_nodes(
    const VcAstNodeList *declarations,
    const VcSource *source,
    const char *namespace_name,
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    if (declarations == NULL)
        return true;
    for (size_t i = 0; i < declarations->count; i++)
    {
        const VcAstNode *node = declarations->items[i];
        if (node == NULL)
            continue;
        if (node->kind == VC_AST_NAMESPACE_DECLARATION)
        {
            if (!collect_using_alias_nodes(&node->as.namespace_declaration.declarations,
                    source, node->as.namespace_declaration.name, model, diagnostic))
                return false;
            continue;
        }
        if (node->kind != VC_AST_USING_DECLARATION ||
            node->as.using_declaration.alias == NULL)
            continue;
        VcSemanticUsingAlias alias = {0};
        alias.node = node;
        alias.source = source;
        alias.namespace_name = namespace_name;
        alias.name = node->as.using_declaration.alias;
        if (!push_using_alias(model, alias))
        {
            set_diagnostic(diagnostic, source, node->location,
                "out of memory while binding using alias '%s'", alias.name);
            return false;
        }
    }
    return true;
}

static bool using_alias_scopes_overlap(
    const VcSemanticUsingAlias *left,
    const VcSemanticUsingAlias *right)
{
    if (left == NULL || right == NULL || left->source != right->source)
        return false;
    if (same_namespace(left->namespace_name, right->namespace_name))
        return true;
    return left->namespace_name == NULL || right->namespace_name == NULL;
}

static bool validate_using_alias_duplicates(
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    for (size_t i = 0; i < model->using_alias_count; i++)
    {
        for (size_t j = i + 1; j < model->using_alias_count; j++)
        {
            const VcSemanticUsingAlias *left = &model->using_aliases[i];
            const VcSemanticUsingAlias *right = &model->using_aliases[j];
            if (strcmp(left->name, right->name) != 0 ||
                !using_alias_scopes_overlap(left, right))
                continue;
            set_diagnostic(diagnostic, right->source, right->node->location,
                "using alias '%s' is already declared in this source scope",
                right->name);
            vc_diagnostic_set_code(diagnostic, VC_DIAG_DUPLICATE);
            related_declaration(diagnostic, left->source, left->node,
                "Previous using alias declaration is here.");
            return false;
        }
    }
    return true;
}

static size_t find_visible_using_alias_index(
    const VcSemanticModel *model,
    const VcSource *source,
    const char *namespace_name,
    const char *name)
{
    size_t result = (size_t)-1;
    for (size_t i = 0; i < model->using_alias_count; i++)
    {
        const VcSemanticUsingAlias *alias = &model->using_aliases[i];
        if (alias->source != source || strcmp(alias->name, name) != 0)
            continue;
        if (alias->namespace_name != NULL &&
            !same_namespace(alias->namespace_name, namespace_name))
            continue;
        if (result != (size_t)-1)
            return (size_t)-2;
        result = i;
    }
    return result;
}

typedef struct VcAliasDeclaredTarget
{
    VcSemanticUsingAliasTargetKind kind;
    const VcAstNode *node;
    const VcSource *source;
    char canonical_name[768];
    bool ambiguous;
} VcAliasDeclaredTarget;

static void scan_alias_target_declarations(
    const VcAstNodeList *declarations,
    const VcSource *source,
    const char *namespace_name,
    const char *target_namespace,
    const char *target_name,
    size_t *type_count,
    const VcAstNode **type_node,
    const VcSource **type_source,
    bool *namespace_found,
    const VcAstNode **namespace_node,
    const VcSource **namespace_source)
{
    if (declarations == NULL)
        return;
    for (size_t i = 0; i < declarations->count; i++)
    {
        const VcAstNode *node = declarations->items[i];
        if (node == NULL)
            continue;
        if (node->kind == VC_AST_NAMESPACE_DECLARATION)
        {
            if (target_name == NULL && node->as.namespace_declaration.name != NULL &&
                strcmp(node->as.namespace_declaration.name, target_namespace) == 0)
            {
                if (!*namespace_found)
                {
                    *namespace_node = node;
                    *namespace_source = source;
                }
                *namespace_found = true;
            }
            scan_alias_target_declarations(
                &node->as.namespace_declaration.declarations,
                source, node->as.namespace_declaration.name,
                target_namespace, target_name,
                type_count, type_node, type_source,
                namespace_found, namespace_node, namespace_source);
            continue;
        }
        if (target_name == NULL || node->kind != VC_AST_TYPE_DECLARATION ||
            node->as.type_declaration.original_generic_name != NULL ||
            !same_namespace(namespace_name, target_namespace) ||
            strcmp(node->as.type_declaration.name, target_name) != 0)
            continue;
        if (*type_count == 0)
        {
            *type_node = node;
            *type_source = source;
        }
        (*type_count)++;
    }
}

static bool model_namespace_declared(
    const VcSemanticModel *model,
    const char *name,
    const VcAstNode **node,
    const VcSource **source)
{
    bool found = false;
    size_t ignored_count = 0;
    const VcAstNode *ignored_node = NULL;
    const VcSource *ignored_source = NULL;
    for (size_t i = 0; i < model->unit_count; i++)
    {
        const VcAstTree *tree = model->units[i].tree;
        if (tree == NULL || tree->root == NULL ||
            tree->root->kind != VC_AST_COMPILATION_UNIT)
            continue;
        scan_alias_target_declarations(
            &tree->root->as.compilation_unit.declarations,
            model->units[i].source, NULL,
            name, NULL,
            &ignored_count, &ignored_node, &ignored_source,
            &found, node, source);
    }
    return found;
}

static size_t model_type_declaration_matches(
    const VcSemanticModel *model,
    const char *namespace_name,
    const char *name,
    const VcAstNode **node,
    const VcSource **source)
{
    size_t count = 0;
    bool ignored_namespace = false;
    const VcAstNode *ignored_namespace_node = NULL;
    const VcSource *ignored_namespace_source = NULL;
    for (size_t i = 0; i < model->unit_count; i++)
    {
        const VcAstTree *tree = model->units[i].tree;
        if (tree == NULL || tree->root == NULL ||
            tree->root->kind != VC_AST_COMPILATION_UNIT)
            continue;
        scan_alias_target_declarations(
            &tree->root->as.compilation_unit.declarations,
            model->units[i].source, NULL,
            namespace_name, name,
            &count, node, source,
            &ignored_namespace, &ignored_namespace_node, &ignored_namespace_source);
    }
    return count;
}

static bool validate_using_alias_name_collisions(
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    for (size_t i = 0; i < model->using_alias_count; i++)
    {
        const VcSemanticUsingAlias *alias = &model->using_aliases[i];
        const VcAstNode *conflict_node = NULL;
        const VcSource *conflict_source = NULL;
        if (model_type_declaration_matches(
                model, alias->namespace_name, alias->name,
                &conflict_node, &conflict_source) != 0)
        {
            set_diagnostic(diagnostic, alias->source, alias->node->location,
                "using alias '%s' conflicts with a type declared in the same scope",
                alias->name);
            vc_diagnostic_set_code(diagnostic, VC_DIAG_DUPLICATE);
            related_declaration(diagnostic, conflict_source, conflict_node,
                "Conflicting type declaration is here.");
            return false;
        }

        char namespace_name[768];
        if (alias->namespace_name != NULL && alias->namespace_name[0] != '\0')
        {
            const int written = snprintf(namespace_name, sizeof(namespace_name),
                "%s.%s", alias->namespace_name, alias->name);
            if (written < 0 || (size_t)written >= sizeof(namespace_name))
                continue;
        }
        else
        {
            snprintf(namespace_name, sizeof(namespace_name), "%s", alias->name);
        }
        conflict_node = NULL;
        conflict_source = NULL;
        if (model_namespace_declared(
                model, namespace_name, &conflict_node, &conflict_source))
        {
            set_diagnostic(diagnostic, alias->source, alias->node->location,
                "using alias '%s' conflicts with a namespace declared in the same scope",
                alias->name);
            vc_diagnostic_set_code(diagnostic, VC_DIAG_DUPLICATE);
            related_declaration(diagnostic, conflict_source, conflict_node,
                "Conflicting namespace declaration is here.");
            return false;
        }
    }
    return true;
}

static void scan_unqualified_alias_type_declarations(
    const VcAstNodeList *declarations,
    const VcSource *source,
    const char *namespace_name,
    const char *simple_name,
    size_t *count,
    const VcAstNode **node,
    const VcSource **target_source,
    const char **target_namespace)
{
    if (declarations == NULL)
        return;
    for (size_t i = 0; i < declarations->count; i++)
    {
        const VcAstNode *declaration = declarations->items[i];
        if (declaration == NULL)
            continue;
        if (declaration->kind == VC_AST_NAMESPACE_DECLARATION)
        {
            scan_unqualified_alias_type_declarations(
                &declaration->as.namespace_declaration.declarations,
                source, declaration->as.namespace_declaration.name,
                simple_name, count, node, target_source, target_namespace);
            continue;
        }
        if (declaration->kind != VC_AST_TYPE_DECLARATION ||
            declaration->as.type_declaration.original_generic_name != NULL ||
            strcmp(declaration->as.type_declaration.name, simple_name) != 0)
            continue;
        if (*count == 0)
        {
            *node = declaration;
            *target_source = source;
            *target_namespace = namespace_name;
        }
        (*count)++;
    }
}

static size_t model_unqualified_type_declaration_matches(
    const VcSemanticModel *model,
    const char *simple_name,
    const VcAstNode **node,
    const VcSource **source,
    const char **namespace_name)
{
    size_t count = 0;
    for (size_t i = 0; i < model->unit_count; i++)
    {
        const VcAstTree *tree = model->units[i].tree;
        if (tree == NULL || tree->root == NULL ||
            tree->root->kind != VC_AST_COMPILATION_UNIT)
            continue;
        scan_unqualified_alias_type_declarations(
            &tree->root->as.compilation_unit.declarations,
            model->units[i].source, NULL, simple_name,
            &count, node, source, namespace_name);
    }
    return count;
}

static bool resolve_declared_alias_target(
    const VcSemanticModel *model,
    const char *scope_namespace,
    const char *name,
    VcAliasDeclaredTarget *target)
{
    memset(target, 0, sizeof(*target));
    if (name == NULL || name[0] == '\0')
        return false;

    const char *last_dot = strrchr(name, '.');
    char qualifier[512];
    const char *type_namespace = scope_namespace;
    const char *simple_name = name;
    bool qualified = last_dot != NULL;
    if (qualified)
    {
        const size_t length = (size_t)(last_dot - name);
        if (length == 0 || length >= sizeof(qualifier) || last_dot[1] == '\0')
            return false;
        memcpy(qualifier, name, length);
        qualifier[length] = '\0';
        type_namespace = qualifier;
        simple_name = last_dot + 1;
    }

    const VcAstNode *type_node = NULL;
    const VcSource *type_source = NULL;
    size_t type_count = model_type_declaration_matches(
        model, type_namespace, simple_name, &type_node, &type_source);
    if (!qualified && type_count == 0)
    {
        const char *fallback_namespace = NULL;
        type_count = model_unqualified_type_declaration_matches(
            model, simple_name, &type_node, &type_source, &fallback_namespace);
        type_namespace = fallback_namespace;
    }

    const VcAstNode *namespace_node = NULL;
    const VcSource *namespace_source = NULL;
    const bool namespace_found = model_namespace_declared(
        model, name, &namespace_node, &namespace_source);

    if (type_count > 1 || (type_count != 0 && namespace_found))
    {
        target->ambiguous = true;
        return false;
    }
    if (type_count == 1)
    {
        target->kind = VC_SEM_USING_ALIAS_TYPE;
        target->node = type_node;
        target->source = type_source;
        if (type_namespace != NULL && type_namespace[0] != '\0')
            snprintf(target->canonical_name, sizeof(target->canonical_name),
                "%s.%s", type_namespace, simple_name);
        else
            snprintf(target->canonical_name, sizeof(target->canonical_name),
                "%s", simple_name);
        return true;
    }
    if (namespace_found)
    {
        target->kind = VC_SEM_USING_ALIAS_NAMESPACE;
        target->node = namespace_node;
        target->source = namespace_source;
        snprintf(target->canonical_name, sizeof(target->canonical_name), "%s", name);
        return true;
    }
    return false;
}

static bool resolve_using_alias_entry(
    VcSemanticModel *model,
    size_t index,
    VcSemanticDiagnostic *diagnostic)
{
    if (index >= model->using_alias_count)
        return false;
    VcSemanticUsingAlias *alias = &model->using_aliases[index];
    if (alias->resolution_state == 2)
        return true;
    if (alias->resolution_state == 1)
    {
        set_diagnostic(diagnostic, alias->source, alias->node->location,
            "using alias '%s' participates in a cyclic alias declaration",
            alias->name);
        vc_diagnostic_set_code(diagnostic, VC_DIAG_NAME);
        return false;
    }
    alias->resolution_state = 1;

    const char *raw = alias->node->as.using_declaration.name;
    const char *dot = raw != NULL ? strchr(raw, '.') : NULL;
    const size_t root_length = dot != NULL ? (size_t)(dot - raw) : (raw != NULL ? strlen(raw) : 0);
    if (root_length == 0 || root_length >= 256)
    {
        set_diagnostic(diagnostic, alias->source, alias->node->location,
            "using alias '%s' has an invalid target", alias->name);
        return false;
    }
    char root[256];
    memcpy(root, raw, root_length);
    root[root_length] = '\0';

    const size_t chained = find_visible_using_alias_index(
        model, alias->source, alias->namespace_name, root);
    if (chained == (size_t)-2)
    {
        set_diagnostic(diagnostic, alias->source, alias->node->location,
            "using alias target '%s' is ambiguous", raw);
        vc_diagnostic_set_code(diagnostic, VC_DIAG_NAME);
        return false;
    }

    VcAliasDeclaredTarget target = {0};
    if (chained != (size_t)-1)
    {
        if (!resolve_using_alias_entry(model, chained, diagnostic))
            return false;
        const VcSemanticUsingAlias *base = &model->using_aliases[chained];
        if (dot == NULL)
        {
            alias->target_kind = base->target_kind;
            alias->target_node = base->target_node;
            alias->target_source = base->target_source;
            snprintf(alias->canonical_name, sizeof(alias->canonical_name), "%s",
                base->canonical_name);
            alias->resolution_state = 2;
            return true;
        }
        if (base->target_kind != VC_SEM_USING_ALIAS_NAMESPACE)
        {
            set_diagnostic(diagnostic, alias->source, alias->node->location,
                "using alias target '%s' cannot qualify through type alias '%s'",
                raw, root);
            vc_diagnostic_set_code(diagnostic, VC_DIAG_NAME);
            return false;
        }
        char expanded[768];
        const int written = snprintf(expanded, sizeof(expanded), "%s%s",
            base->canonical_name, dot);
        if (written < 0 || (size_t)written >= sizeof(expanded) ||
            !resolve_declared_alias_target(model, alias->namespace_name, expanded, &target))
        {
            if (target.ambiguous)
                set_diagnostic(diagnostic, alias->source, alias->node->location,
                    "using alias target '%s' is ambiguous", raw);
            else
                set_diagnostic(diagnostic, alias->source, alias->node->location,
                    "using alias '%s' target '%s' could not be resolved",
                    alias->name, raw);
            vc_diagnostic_set_code(diagnostic, VC_DIAG_NAME);
            return false;
        }
    }
    else if (!resolve_declared_alias_target(model, alias->namespace_name, raw, &target))
    {
        if (target.ambiguous)
            set_diagnostic(diagnostic, alias->source, alias->node->location,
                "using alias target '%s' is ambiguous", raw);
        else
            set_diagnostic(diagnostic, alias->source, alias->node->location,
                "using alias '%s' target '%s' could not be resolved",
                alias->name, raw != NULL ? raw : "<missing>");
        vc_diagnostic_set_code(diagnostic, VC_DIAG_NAME);
        return false;
    }

    alias->target_kind = target.kind;
    alias->target_node = target.node;
    alias->target_source = target.source;
    snprintf(alias->canonical_name, sizeof(alias->canonical_name), "%s",
        target.canonical_name);
    alias->resolution_state = 2;
    return true;
}

static bool collect_and_resolve_using_aliases(
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    for (size_t i = 0; i < model->unit_count; i++)
    {
        const VcAstTree *tree = model->units[i].tree;
        if (tree == NULL || tree->root == NULL ||
            tree->root->kind != VC_AST_COMPILATION_UNIT)
            continue;
        if (!collect_using_alias_nodes(&tree->root->as.compilation_unit.declarations,
                model->units[i].source, NULL, model, diagnostic))
            return false;
    }
    if (!validate_using_alias_duplicates(model, diagnostic))
        return false;
    if (!validate_using_alias_name_collisions(model, diagnostic))
        return false;
    for (size_t i = 0; i < model->using_alias_count; i++)
        if (!resolve_using_alias_entry(model, i, diagnostic))
            return false;
    return true;
}

static const VcSemanticUsingAlias *visible_using_alias(
    const VcSemanticModel *model,
    const VcSource *source,
    const char *namespace_name,
    const char *name)
{
    const size_t index = find_visible_using_alias_index(model, source, namespace_name, name);
    if (index == (size_t)-1 || index == (size_t)-2)
        return NULL;
    return &model->using_aliases[index];
}

static bool expand_semantic_alias_name(
    const VcSemanticModel *model,
    const VcSource *source,
    const char *namespace_name,
    const char *name,
    char *output,
    size_t output_size,
    const VcSemanticUsingAlias **resolved_alias)
{
    if (resolved_alias != NULL)
        *resolved_alias = NULL;
    if (model == NULL || source == NULL || name == NULL || output == NULL || output_size == 0)
        return false;
    const char *dot = strchr(name, '.');
    const size_t root_length = dot != NULL ? (size_t)(dot - name) : strlen(name);
    if (root_length == 0 || root_length >= 256)
        return false;
    char root[256];
    memcpy(root, name, root_length);
    root[root_length] = '\0';
    const VcSemanticUsingAlias *alias = visible_using_alias(
        model, source, namespace_name, root);
    if (alias == NULL || alias->resolution_state != 2)
        return false;
    if (dot != NULL && alias->target_kind != VC_SEM_USING_ALIAS_NAMESPACE)
        return false;
    const int written = snprintf(output, output_size, "%s%s",
        alias->canonical_name, dot != NULL ? dot : "");
    if (written < 0 || (size_t)written >= output_size)
        return false;
    if (resolved_alias != NULL)
        *resolved_alias = alias;
    return true;
}

static bool find_struct_by_name(
    const VcSemanticModel *model,
    const char *namespace_name,
    const char *name,
    size_t *index,
    bool *ambiguous)
{
    *ambiguous = false;
    size_t match = (size_t)-1;

    for (size_t i = 0; i < model->struct_count; i++)
    {
        if (strcmp(model->structs[i].name, name) != 0)
            continue;
        if (same_namespace(model->structs[i].namespace_name, namespace_name))
        {
            *ambiguous = false;
            *index = i;
            return true;
        }
        if (match != (size_t)-1)
            *ambiguous = true;
        else
            match = i;
    }

    if (*ambiguous || match == (size_t)-1)
        return false;
    *index = match;
    return true;
}

static bool resolve_from_end_index_contract(
    const VcSemanticModel *model,
    size_t *struct_index,
    size_t *constructor_index)
{
    size_t resolved_struct = 0;
    bool ambiguous = false;
    if (!find_struct_by_name(model, "Void", "Index", &resolved_struct, &ambiguous) || ambiguous)
        return false;

    for (size_t i = 0; i < model->constructor_count; i++)
    {
        const VcSemanticConstructor *candidate = &model->constructors[i];
        if (candidate->struct_index != resolved_struct || candidate->parameter_count != 2 ||
            candidate->parameter_types[0] != VC_SEM_TYPE_INT ||
            candidate->parameter_types[1] != VC_SEM_TYPE_BOOL ||
            candidate->parameter_modifiers[0] != VC_TOKEN_EOF ||
            candidate->parameter_modifiers[1] != VC_TOKEN_EOF)
            continue;
        if (struct_index != NULL)
            *struct_index = resolved_struct;
        if (constructor_index != NULL)
            *constructor_index = i;
        return true;
    }
    return false;
}

static bool resolve_range_contract(
    const VcSemanticModel *model,
    size_t *range_struct_index,
    size_t *range_constructor_index,
    VcSemanticType *index_type)
{
    size_t resolved_index_struct = 0;
    size_t resolved_index_constructor = 0;
    if (!resolve_from_end_index_contract(model,
            &resolved_index_struct, &resolved_index_constructor))
        return false;

    size_t resolved_range_struct = 0;
    bool ambiguous = false;
    if (!find_struct_by_name(model, "Void", "Range", &resolved_range_struct, &ambiguous) || ambiguous)
        return false;

    const VcSemanticType resolved_index_type = vc_semantic_struct_type(resolved_index_struct);
    for (size_t i = 0; i < model->constructor_count; i++)
    {
        const VcSemanticConstructor *candidate = &model->constructors[i];
        if (candidate->struct_index != resolved_range_struct || candidate->parameter_count != 2 ||
            candidate->parameter_types[0] != resolved_index_type ||
            candidate->parameter_types[1] != resolved_index_type ||
            candidate->parameter_modifiers[0] != VC_TOKEN_EOF ||
            candidate->parameter_modifiers[1] != VC_TOKEN_EOF)
            continue;
        if (range_struct_index != NULL)
            *range_struct_index = resolved_range_struct;
        if (range_constructor_index != NULL)
            *range_constructor_index = i;
        if (index_type != NULL)
            *index_type = resolved_index_type;
        return true;
    }
    return false;
}

static VcSemanticType intern_array_type_rank(
    VcSemanticModel *model,
    VcSemanticType element_type,
    size_t rank)
{
    if (rank == 0)
        return VC_SEM_TYPE_ERROR;
    for (size_t i = 0; i < model->array_count; i++)
    {
        if (model->arrays[i].element_type == element_type && model->arrays[i].rank == rank)
            return vc_semantic_array_type(i);
    }

    VcSemanticArray array = {0};
    array.element_type = element_type;
    array.rank = rank;
    const char *element_name = vc_semantic_type_name(model, element_type);
    int written = snprintf(array.name, sizeof(array.name), "%s[", element_name);
    if (written < 0 || (size_t)written >= sizeof(array.name))
        return VC_SEM_TYPE_ERROR;
    size_t used = (size_t)written;
    for (size_t i = 1; i < rank; i++)
    {
        if (used + 1 >= sizeof(array.name))
            return VC_SEM_TYPE_ERROR;
        array.name[used++] = ',';
    }
    if (used + 2 > sizeof(array.name))
        return VC_SEM_TYPE_ERROR;
    array.name[used++] = ']';
    array.name[used] = '\0';
    if (!push_array(model, array))
        return VC_SEM_TYPE_ERROR;
    return vc_semantic_array_type(model->array_count - 1);
}

static VcSemanticType intern_array_type(VcSemanticModel *model, VcSemanticType element_type)
{
    return intern_array_type_rank(model, element_type, 1);
}

static VcSemanticType intern_nullable_type(VcSemanticModel *model, VcSemanticType underlying_type)
{
    for (size_t i = 0; i < model->nullable_count; i++)
    {
        if (model->nullables[i].underlying_type == underlying_type)
            return vc_semantic_nullable_type(i);
    }

    VcSemanticNullable nullable = {0};
    nullable.underlying_type = underlying_type;
    const char *underlying_name = vc_semantic_type_name(model, underlying_type);
    const int written = snprintf(nullable.name, sizeof(nullable.name), "%s?", underlying_name);
    if (written < 0 || (size_t)written >= sizeof(nullable.name))
        return VC_SEM_TYPE_ERROR;
    snprintf(nullable.c_name, sizeof(nullable.c_name), "vc_n_%zu", model->nullable_count);
    if (!push_nullable(model, nullable))
        return VC_SEM_TYPE_ERROR;
    return vc_semantic_nullable_type(model->nullable_count - 1);
}

static VcSemanticType intern_pointer_type(VcSemanticModel *model, VcSemanticType element_type)
{
    for (size_t i = 0; i < model->pointer_count; i++)
    {
        if (model->pointers[i].element_type == element_type)
            return vc_semantic_pointer_type(i);
    }

    VcSemanticPointer pointer = {0};
    pointer.element_type = element_type;
    const char *element_name = vc_semantic_type_name(model, element_type);
    const int written = snprintf(pointer.name, sizeof(pointer.name), "%s*", element_name);
    if (written < 0 || (size_t)written >= sizeof(pointer.name))
        return VC_SEM_TYPE_ERROR;
    if (!push_pointer(model, pointer))
        return VC_SEM_TYPE_ERROR;
    return vc_semantic_pointer_type(model->pointer_count - 1);
}

static VcSemanticType intern_function_pointer_type(
    VcSemanticModel *model,
    const VcSemanticType *parameter_types,
    size_t parameter_count,
    VcSemanticType return_type)
{
    for (size_t i = 0; i < model->function_pointer_count; i++)
    {
        const VcSemanticFunctionPointer *existing = &model->function_pointers[i];
        if (existing->return_type != return_type || existing->parameter_count != parameter_count)
            continue;
        bool same = true;
        for (size_t p = 0; p < parameter_count; p++)
        {
            if (existing->parameter_types[p] != parameter_types[p])
            {
                same = false;
                break;
            }
        }
        if (same)
            return vc_semantic_function_pointer_type(i);
    }

    VcSemanticFunctionPointer function_pointer = {0};
    function_pointer.return_type = return_type;
    function_pointer.parameter_count = parameter_count;
    if (parameter_count != 0)
    {
        function_pointer.parameter_types = calloc(parameter_count, sizeof(*function_pointer.parameter_types));
        if (function_pointer.parameter_types == NULL)
            return VC_SEM_TYPE_ERROR;
        memcpy(function_pointer.parameter_types, parameter_types,
            parameter_count * sizeof(*function_pointer.parameter_types));
    }
    size_t used = 0;
    const int prefix = snprintf(function_pointer.name, sizeof(function_pointer.name), "delegate*<");
    if (prefix < 0 || (size_t)prefix >= sizeof(function_pointer.name))
    {
        free(function_pointer.parameter_types);
        return VC_SEM_TYPE_ERROR;
    }
    used = (size_t)prefix;
    for (size_t p = 0; p < parameter_count; p++)
    {
        const char *name = vc_semantic_type_name(model, parameter_types[p]);
        const int written = snprintf(function_pointer.name + used, sizeof(function_pointer.name) - used,
            "%s%s", p == 0 ? "" : ", ", name);
        if (written < 0 || (size_t)written >= sizeof(function_pointer.name) - used)
        {
            free(function_pointer.parameter_types);
            return VC_SEM_TYPE_ERROR;
        }
        used += (size_t)written;
    }
    const char *return_name = vc_semantic_type_name(model, return_type);
    const int suffix = snprintf(function_pointer.name + used, sizeof(function_pointer.name) - used,
        "%s%s>", parameter_count == 0 ? "" : ", ", return_name);
    if (suffix < 0 || (size_t)suffix >= sizeof(function_pointer.name) - used)
    {
        free(function_pointer.parameter_types);
        return VC_SEM_TYPE_ERROR;
    }
    snprintf(function_pointer.c_name, sizeof(function_pointer.c_name),
        "vc_fnptr_%zu", model->function_pointer_count);
    if (!push_function_pointer(model, function_pointer))
    {
        free(function_pointer.parameter_types);
        return VC_SEM_TYPE_ERROR;
    }
    return vc_semantic_function_pointer_type(model->function_pointer_count - 1);
}

static bool nullable_underlying_supported(const VcSemanticModel *model, VcSemanticType type)
{
    switch (type)
    {
        case VC_SEM_TYPE_BOOL:
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
            return true;
        default:
            break;
    }

    if (!vc_semantic_type_is_struct(type))
        return false;
    const size_t index = vc_semantic_struct_index(type);
    if (index >= model->struct_count)
        return false;
    const VcSemanticStruct *structure = &model->structs[index];
    if (structure->is_ref_struct)
        return false;
    return structure->is_enum ||
        (!structure->is_class && !structure->is_interface && !structure->is_delegate);
}

/* Shared named/constructed lookup for declarations and expression receivers. */
static bool find_type_declaration(
    const VcSemanticModel *model, const VcAstTypeRef *type, const char *namespace_name,
    size_t *index, bool *ambiguous)
{
    *ambiguous = false;
    if (type == NULL || type->name == NULL) return false;
    const char *last_dot = strrchr(type->name, '.');
    char qualifier[512];
    const char *ns = namespace_name;
    const char *name = type->name;
    if (last_dot != NULL)
    {
        const size_t length = (size_t)(last_dot - type->name);
        if (length == 0 || length >= sizeof(qualifier) || last_dot[1] == '\0') return false;
        memcpy(qualifier, type->name, length);
        qualifier[length] = '\0';
        ns = qualifier;
        name = last_dot + 1;
    }
    char mangled[256];
    if (type->generic_arguments.count != 0)
    {
        VcAstTypeRef canonical = *type;
        canonical.name = (char *)name;
        if (!vc_monomorph_mangle_type_ref(&canonical, mangled, sizeof(mangled))) return false;
        name = mangled;
    }
    if (last_dot != NULL)
    {
        for (size_t i = 0; i < model->struct_count; i++)
        {
            if (same_namespace(model->structs[i].namespace_name, ns) &&
                strcmp(model->structs[i].name, name) == 0)
            { *index = i; return true; }
        }
        return false;
    }
    return find_struct_by_name(model, ns, name, index, ambiguous);
}

static VcSemanticType resolve_type(
    VcSemanticModel *model,
    const VcAstTypeRef *type,
    const char *namespace_name,
    bool allow_void);

static bool constructed_type_arguments_match(
    VcSemanticModel *model,
    const VcSemanticStruct *candidate,
    const VcSemanticType *arguments,
    size_t argument_count)
{
    if (candidate == NULL || candidate->node == NULL ||
        candidate->node->kind != VC_AST_TYPE_DECLARATION ||
        candidate->node->as.type_declaration.original_generic_name == NULL ||
        candidate->node->as.type_declaration.generic_arguments.count != argument_count)
        return false;
    for (size_t i = 0; i < argument_count; i++)
    {
        const VcSemanticType candidate_argument = resolve_type(model,
            candidate->node->as.type_declaration.generic_arguments.items[i],
            candidate->namespace_name, false);
        if (candidate_argument == VC_SEM_TYPE_UNKNOWN ||
            candidate_argument == VC_SEM_TYPE_ERROR ||
            candidate_argument != arguments[i])
            return false;
    }
    return true;
}

static bool find_constructed_type_declaration(
    VcSemanticModel *model,
    const VcAstTypeRef *type,
    const char *namespace_name,
    const VcSemanticType *arguments,
    size_t argument_count,
    size_t *index,
    bool *ambiguous)
{
    *ambiguous = false;
    if (model == NULL || type == NULL || type->name == NULL || argument_count == 0)
        return false;

    const char *last_dot = strrchr(type->name, '.');
    char qualifier[512];
    const char *target_namespace = namespace_name;
    const char *simple_name = type->name;
    const bool qualified = last_dot != NULL;
    if (qualified)
    {
        const size_t length = (size_t)(last_dot - type->name);
        if (length == 0 || length >= sizeof(qualifier) || last_dot[1] == '\0')
            return false;
        memcpy(qualifier, type->name, length);
        qualifier[length] = '\0';
        target_namespace = qualifier;
        simple_name = last_dot + 1;
    }

    size_t fallback = (size_t)-1;
    for (size_t i = 0; i < model->struct_count; i++)
    {
        const VcSemanticStruct *candidate = &model->structs[i];
        if (candidate->node == NULL || candidate->node->kind != VC_AST_TYPE_DECLARATION ||
            candidate->node->as.type_declaration.original_generic_name == NULL ||
            strcmp(candidate->node->as.type_declaration.original_generic_name, simple_name) != 0 ||
            !constructed_type_arguments_match(model, candidate, arguments, argument_count))
            continue;

        if (qualified)
        {
            if (!same_namespace(candidate->namespace_name, target_namespace))
                continue;
            *index = i;
            return true;
        }
        if (same_namespace(candidate->namespace_name, target_namespace))
        {
            *ambiguous = false;
            *index = i;
            return true;
        }
        if (fallback != (size_t)-1)
            *ambiguous = true;
        else
            fallback = i;
    }

    if (*ambiguous || fallback == (size_t)-1)
        return false;
    *index = fallback;
    return true;
}

static VcSemanticType resolve_type_with_source(
    VcSemanticModel *model,
    const VcAstTypeRef *type,
    const char *namespace_name,
    bool allow_void,
    const VcSource *source)
{
    if (type != NULL && type->is_global_qualified)
    {
        namespace_name = NULL;
        source = NULL;
    }

    char alias_name[768];
    VcAstTypeRef aliased_type;
    if (type != NULL && type->name != NULL && source != NULL &&
        expand_semantic_alias_name(model, source, namespace_name, type->name,
            alias_name, sizeof(alias_name), NULL))
    {
        aliased_type = *type;
        aliased_type.name = alias_name;
        type = &aliased_type;
    }
    if (type != NULL && type->array_rank != 0)
    {
        VcAstTypeRef element = *type;
        element.array_rank--;
        const VcSemanticType element_type = resolve_type_with_source(model, &element, namespace_name, false, source);
        if (element_type == VC_SEM_TYPE_UNKNOWN || element_type == VC_SEM_TYPE_ERROR ||
            element_type == VC_SEM_TYPE_VOID || semantic_type_is_ref_struct(model, element_type))
            return VC_SEM_TYPE_UNKNOWN;
        return intern_array_type(model, element_type);
    }

    if (type != NULL && type->rectangular_rank > 1)
    {
        VcAstTypeRef element = *type;
        const size_t rank = element.rectangular_rank;
        element.rectangular_rank = 0;
        const VcSemanticType element_type = resolve_type_with_source(model, &element, namespace_name, false, source);
        if (element_type == VC_SEM_TYPE_UNKNOWN || element_type == VC_SEM_TYPE_ERROR ||
            element_type == VC_SEM_TYPE_VOID || semantic_type_is_ref_struct(model, element_type))
            return VC_SEM_TYPE_UNKNOWN;
        return intern_array_type_rank(model, element_type, rank);
    }

    if (type != NULL && type->is_function_pointer && type->pointer_depth != 0)
    {
        /* Explicit delegate*<...>* syntax is rejected by the parser.  A pointer depth can
           still appear after monomorphizing a source-level T* where T becomes a native
           function pointer.  That is a data pointer to function-pointer storage, not a
           conversion of the function pointer value to a data pointer. */
        if (type->generic_parameter_origin == NULL || type->nullable)
            return VC_SEM_TYPE_UNKNOWN;
        VcAstTypeRef element = *type;
        element.pointer_depth--;
        element.nullable = false;
        const VcSemanticType element_type = resolve_type_with_source(model, &element, namespace_name, true, source);
        if (element_type == VC_SEM_TYPE_UNKNOWN || element_type == VC_SEM_TYPE_ERROR)
            return VC_SEM_TYPE_UNKNOWN;
        return intern_pointer_type(model, element_type);
    }

    if (type != NULL && type->is_function_pointer)
    {
        if (type->nullable || type->generic_arguments.count == 0)
            return VC_SEM_TYPE_UNKNOWN;
        const size_t signature_count = type->generic_arguments.count;
        const size_t parameter_count = signature_count - 1u;
        VcSemanticType *parameter_types = parameter_count == 0 ? NULL :
            calloc(parameter_count, sizeof(*parameter_types));
        if (parameter_count != 0 && parameter_types == NULL)
            return VC_SEM_TYPE_ERROR;
        for (size_t i = 0; i < parameter_count; i++)
        {
            parameter_types[i] = resolve_type_with_source(model, type->generic_arguments.items[i],
                namespace_name, false, source);
            if (parameter_types[i] == VC_SEM_TYPE_UNKNOWN || parameter_types[i] == VC_SEM_TYPE_ERROR ||
                parameter_types[i] == VC_SEM_TYPE_VOID)
            {
                free(parameter_types);
                return VC_SEM_TYPE_UNKNOWN;
            }
        }
        const VcSemanticType return_type = resolve_type_with_source(model,
            type->generic_arguments.items[signature_count - 1u], namespace_name, true, source);
        if (return_type == VC_SEM_TYPE_UNKNOWN || return_type == VC_SEM_TYPE_ERROR)
        {
            free(parameter_types);
            return VC_SEM_TYPE_UNKNOWN;
        }
        const VcSemanticType result = intern_function_pointer_type(
            model, parameter_types, parameter_count, return_type);
        free(parameter_types);
        return result;
    }

    if (type != NULL && type->pointer_depth != 0)
    {
        if (type->nullable)
            return VC_SEM_TYPE_UNKNOWN;
        VcAstTypeRef element = *type;
        element.pointer_depth--;
        element.nullable = false;
        const VcSemanticType element_type = resolve_type_with_source(model, &element, namespace_name, true, source);
        if (element_type == VC_SEM_TYPE_UNKNOWN || element_type == VC_SEM_TYPE_ERROR)
            return VC_SEM_TYPE_UNKNOWN;
        return intern_pointer_type(model, element_type);
    }

    if (type != NULL && type->nullable)
    {
        VcAstTypeRef underlying = *type;
        underlying.nullable = false;
        const VcSemanticType underlying_type = resolve_type_with_source(model, &underlying, namespace_name, false, source);
        if (underlying_type == VC_SEM_TYPE_UNKNOWN || underlying_type == VC_SEM_TYPE_ERROR ||
            !nullable_underlying_supported(model, underlying_type))
            return VC_SEM_TYPE_UNKNOWN;
        return intern_nullable_type(model, underlying_type);
    }

    VcSemanticType builtin = vc_semantic_builtin_type_from_ast(type);
    if (builtin != VC_SEM_TYPE_UNKNOWN)
        return !allow_void && builtin == VC_SEM_TYPE_VOID ? VC_SEM_TYPE_UNKNOWN : builtin;

    if (type == NULL || type->name == NULL || type->nullable)
        return VC_SEM_TYPE_UNKNOWN;

    VcSemanticType *resolved_arguments = NULL;
    if (type->generic_arguments.count != 0)
    {
        resolved_arguments = calloc(type->generic_arguments.count, sizeof(*resolved_arguments));
        if (resolved_arguments == NULL)
            return VC_SEM_TYPE_ERROR;
    }
    for (size_t argument_index = 0; argument_index < type->generic_arguments.count; argument_index++)
    {
        const VcSemanticType argument_type = resolve_type_with_source(model,
            type->generic_arguments.items[argument_index], namespace_name, false, source);
        if (argument_type == VC_SEM_TYPE_UNKNOWN || argument_type == VC_SEM_TYPE_ERROR ||
            semantic_type_is_ref_struct(model, argument_type))
        {
            free(resolved_arguments);
            return VC_SEM_TYPE_UNKNOWN;
        }
        resolved_arguments[argument_index] = argument_type;
    }
    size_t index = 0;
    bool ambiguous = false;
    bool found = false;
    if (type->generic_arguments.count != 0)
        found = find_constructed_type_declaration(model, type, namespace_name,
            resolved_arguments, type->generic_arguments.count, &index, &ambiguous);
    else
        found = find_type_declaration(model, type, namespace_name, &index, &ambiguous);
    free(resolved_arguments);
    if (!found)
        return VC_SEM_TYPE_UNKNOWN;
    return vc_semantic_struct_type(index);
}

static VcSemanticType resolve_type(
    VcSemanticModel *model,
    const VcAstTypeRef *type,
    const char *namespace_name,
    bool allow_void)
{
    return resolve_type_with_source(model, type, namespace_name, allow_void,
        semantic_source_for_ast_pointer(model, type));
}

static bool semantic_async_completion_type_info(
    VcSemanticModel *model,
    VcSemanticType type,
    const char *completion_name,
    VcSemanticType *result_type,
    bool *has_result)
{
    if (!vc_semantic_type_is_struct(type))
        return false;
    const size_t index = vc_semantic_struct_index(type);
    if (index >= model->struct_count)
        return false;

    const VcSemanticStruct *structure = &model->structs[index];
    if (structure->namespace_name == NULL ||
        strcmp(structure->namespace_name, "Void.Threading.Tasks") != 0 ||
        structure->node == NULL)
        return false;

    const VcAstNode *declaration = structure->node;
    if (declaration->as.type_declaration.original_generic_name == NULL)
    {
        if (strcmp(structure->name, completion_name) != 0)
            return false;
        if (result_type != NULL)
            *result_type = VC_SEM_TYPE_VOID;
        if (has_result != NULL)
            *has_result = false;
        return true;
    }

    if (strcmp(declaration->as.type_declaration.original_generic_name, completion_name) != 0 ||
        declaration->as.type_declaration.generic_arguments.count != 1)
        return false;

    const VcSemanticType result = resolve_type(model,
        declaration->as.type_declaration.generic_arguments.items[0],
        structure->namespace_name, false);
    if (result == VC_SEM_TYPE_UNKNOWN || result == VC_SEM_TYPE_ERROR || result == VC_SEM_TYPE_VOID)
        return false;
    if (result_type != NULL)
        *result_type = result;
    if (has_result != NULL)
        *has_result = true;
    return true;
}

static bool semantic_task_type_info(
    VcSemanticModel *model,
    VcSemanticType type,
    VcSemanticType *result_type,
    bool *has_result)
{
    return semantic_async_completion_type_info(
        model, type, "Task", result_type, has_result);
}

static bool semantic_value_task_type_info(
    VcSemanticModel *model,
    VcSemanticType type,
    VcSemanticType *result_type,
    bool *has_result)
{
    return semantic_async_completion_type_info(
        model, type, "ValueTask", result_type, has_result);
}

static bool semantic_is_cancellation_token_type(
    const VcSemanticModel *model,
    VcSemanticType type)
{
    if (!vc_semantic_type_is_struct(type))
        return false;
    const size_t index = vc_semantic_struct_index(type);
    if (index >= model->struct_count)
        return false;
    const VcSemanticStruct *structure = &model->structs[index];
    return structure->namespace_name != NULL &&
        strcmp(structure->namespace_name, "Void.Threading") == 0 &&
        structure->name != NULL && strcmp(structure->name, "CancellationToken") == 0;
}

static bool semantic_ast_type_name_matches(const VcAstTypeRef *type, const char *name)
{
    if (type == NULL || type->name == NULL || name == NULL)
        return false;
    if (strcmp(type->name, name) == 0)
        return true;
    const char *last_dot = strrchr(type->name, '.');
    return last_dot != NULL && strcmp(last_dot + 1, name) == 0;
}

static bool semantic_async_enumerable_type_info(
    VcSemanticModel *model,
    VcSemanticType type,
    VcSemanticType *item_type)
{
    if (!vc_semantic_type_is_struct(type))
        return false;
    const size_t index = vc_semantic_struct_index(type);
    if (index >= model->struct_count)
        return false;

    const VcSemanticStruct *structure = &model->structs[index];
    if (structure->namespace_name == NULL ||
        strcmp(structure->namespace_name, "Void.Collections") != 0 ||
        structure->node == NULL)
        return false;

    const VcAstNode *declaration = structure->node;
    if (declaration->as.type_declaration.original_generic_name == NULL ||
        strcmp(declaration->as.type_declaration.original_generic_name, "IAsyncEnumerable") != 0 ||
        declaration->as.type_declaration.generic_arguments.count != 1)
        return false;

    const VcSemanticType item = resolve_type(model,
        declaration->as.type_declaration.generic_arguments.items[0],
        structure->namespace_name, true);
    if (item == VC_SEM_TYPE_UNKNOWN || item == VC_SEM_TYPE_ERROR)
        return false;
    if (item_type != NULL)
        *item_type = item;
    return true;
}

static const VcAstNode *find_attribute(const VcAstNode *node, const char *name)
{
    if (node == NULL)
        return NULL;

    for (size_t i = 0; i < node->attributes.count; i++)
    {
        const VcAstNode *attribute = node->attributes.items[i];
        if (attribute != NULL && attribute->kind == VC_AST_ATTRIBUTE &&
            attribute->as.attribute.name != NULL &&
            strcmp(attribute->as.attribute.name, name) == 0)
            return attribute;
    }
    return NULL;
}

static bool validate_runtime_attributes(
    const VcAstNode *node,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic)
{
    if (node == NULL)
        return true;

    for (size_t i = 0; i < node->attributes.count; i++)
    {
        const VcAstNode *attribute = node->attributes.items[i];
        if (attribute == NULL || attribute->kind != VC_AST_ATTRIBUTE ||
            attribute->as.attribute.name == NULL)
            continue;

        for (size_t previous = 0; previous < i; previous++)
        {
            const VcAstNode *other = node->attributes.items[previous];
            if (other != NULL && other->kind == VC_AST_ATTRIBUTE &&
                other->as.attribute.name != NULL &&
                strcmp(other->as.attribute.name, attribute->as.attribute.name) == 0)
            {
                set_diagnostic(diagnostic, source, attribute->location,
                    "attribute '%s' may appear only once on a type",
                    attribute->as.attribute.name);
                return false;
            }
        }

        for (size_t argument_index = 0;
             argument_index < attribute->as.attribute.arguments.count;
             argument_index++)
        {
            const VcAstNode *argument = attribute->as.attribute.arguments.items[argument_index];
            if (argument == NULL)
                return false;

            if (argument->kind == VC_AST_LITERAL_EXPRESSION &&
                argument->as.literal_expression.literal_kind == VC_AST_LITERAL_STRING)
                continue;

            if (argument->kind == VC_AST_ASSIGNMENT_EXPRESSION &&
                argument->as.assignment_expression.operator_kind == VC_TOKEN_EQUAL)
            {
                const VcAstNode *left = argument->as.assignment_expression.left;
                const VcAstNode *right = argument->as.assignment_expression.right;
                if (left != NULL && left->kind == VC_AST_IDENTIFIER_EXPRESSION &&
                    right != NULL && right->kind == VC_AST_LITERAL_EXPRESSION &&
                    right->as.literal_expression.literal_kind == VC_AST_LITERAL_STRING)
                {
                    const char *name = left->as.identifier_expression.name;
                    for (size_t previous = 0; previous < argument_index; previous++)
                    {
                        const VcAstNode *other = attribute->as.attribute.arguments.items[previous];
                        if (other == NULL || other->kind != VC_AST_ASSIGNMENT_EXPRESSION ||
                            other->as.assignment_expression.operator_kind != VC_TOKEN_EQUAL)
                            continue;
                        const VcAstNode *other_left = other->as.assignment_expression.left;
                        if (other_left != NULL && other_left->kind == VC_AST_IDENTIFIER_EXPRESSION &&
                            strcmp(other_left->as.identifier_expression.name, name) == 0)
                        {
                            set_diagnostic(diagnostic, source, argument->location,
                                "attribute '%s' contains duplicate named argument '%s'",
                                attribute->as.attribute.name, name);
                            return false;
                        }
                    }
                    continue;
                }
            }

            set_diagnostic(diagnostic, source, argument->location,
                "runtime-discoverable attribute arguments must be string literals or named string literals");
            return false;
        }
    }

    return true;
}

static bool is_swizzle_component_type(VcSemanticType type)
{
    switch (type)
    {
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
            return true;
        default:
            return false;
    }
}

static bool find_field_index_by_name(const VcSemanticStruct *structure, const char *name, size_t *index)
{
    for (size_t i = 0; i < structure->field_count; i++)
    {
        const VcAstNode *field = structure->fields[i].node;
        if (field != NULL && field->kind == VC_AST_FIELD_DECLARATION &&
            strcmp(field->as.field_declaration.name, name) == 0)
        {
            *index = i;
            return true;
        }
    }
    return false;
}

static bool configure_swizzle_struct(VcSemanticStruct *structure, VcSemanticDiagnostic *diagnostic)
{
    const VcAstNode *attribute = find_attribute(structure->node, "Swizzle");
    if (attribute == NULL)
        return true;

    if (attribute->as.attribute.arguments.count != 1)
    {
        set_diagnostic(diagnostic, structure->source, attribute->location,
            "[Swizzle] requires exactly one string family name");
        return false;
    }

    const VcAstNode *family = attribute->as.attribute.arguments.items[0];
    if (family == NULL || family->kind != VC_AST_LITERAL_EXPRESSION ||
        family->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
    {
        set_diagnostic(diagnostic, structure->source, attribute->location,
            "[Swizzle] family name must be a string literal");
        return false;
    }

    const char *family_text = family->as.literal_expression.text;
    const size_t family_length = strlen(family_text);
    if (family_length < 2 || family_text[0] != '"' || family_text[family_length - 1] != '"' ||
        family_length - 2 >= sizeof(structure->swizzle_family))
    {
        set_diagnostic(diagnostic, structure->source, family->location,
            "[Swizzle] family name is invalid or too long");
        return false;
    }

    memcpy(structure->swizzle_family, family_text + 1, family_length - 2);
    structure->swizzle_family[family_length - 2] = '\0';

    static const char *xyzw[] = {"X", "Y", "Z", "W"};
    static const char *rgba[] = {"R", "G", "B", "A"};
    size_t component_fields[4] = {0};
    size_t component_count = 0;

    bool uses_xyzw = find_field_index_by_name(structure, "X", &component_fields[0]) &&
        find_field_index_by_name(structure, "Y", &component_fields[1]);
    bool uses_rgba = false;
    if (!uses_xyzw)
    {
        uses_rgba = find_field_index_by_name(structure, "R", &component_fields[0]) &&
            find_field_index_by_name(structure, "G", &component_fields[1]);
    }

    if (!uses_xyzw && !uses_rgba)
    {
        set_diagnostic(diagnostic, structure->source, structure->node->location,
            "[Swizzle] struct '%s' must expose X/Y or R/G component fields", structure->name);
        return false;
    }

    const char *const *names = uses_xyzw ? xyzw : rgba;
    component_count = 2;
    for (size_t i = 2; i < 4; i++)
    {
        size_t field_index = 0;
        if (!find_field_index_by_name(structure, names[i], &field_index))
            break;
        component_fields[i] = field_index;
        component_count++;
    }

    const VcSemanticType component_type = structure->fields[component_fields[0]].type;
    if (!is_swizzle_component_type(component_type))
    {
        set_diagnostic(diagnostic, structure->source, structure->node->location,
            "[Swizzle] struct '%s' components must use a numeric type", structure->name);
        return false;
    }

    for (size_t i = 1; i < component_count; i++)
    {
        if (structure->fields[component_fields[i]].type != component_type)
        {
            set_diagnostic(diagnostic, structure->source, structure->node->location,
                "[Swizzle] struct '%s' components must all have the same type", structure->name);
            return false;
        }
    }

    structure->swizzle_enabled = true;
    structure->swizzle_component_type = component_type;
    structure->swizzle_component_count = component_count;
    for (size_t i = 0; i < component_count; i++)
        structure->swizzle_component_fields[i] = component_fields[i];
    return true;
}

/* StandardLibrary built-in value declarations can request one semantic primitive
   constant category. The category is independent of the public member name;
   the field type plus category controls constant folding/backend emission. */
static bool primitive_constant_kind_from_attribute(
    const VcAstNode *field_node,
    const VcSemanticStruct *owner,
    VcSemanticType field_type,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    VcPrimitiveConstantKind *kind)
{
    *kind = VC_PRIMITIVE_CONSTANT_NONE;
    const VcAstNode *attribute = find_attribute(field_node, "PrimitiveConstant");
    if (attribute == NULL)
        return true;

    if (!source_is_standard_library(source) || owner == NULL ||
        !owner->is_builtin_associated_scope)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] is reserved for StandardLibrary built-in member scopes");
        return false;
    }
    if (field_node->kind != VC_AST_FIELD_DECLARATION ||
        (field_node->as.field_declaration.modifiers & VC_AST_MOD_CONST) == 0)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] requires a const field declaration");
        return false;
    }
    if (field_type != owner->associated_builtin_type)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] field type must match its associated built-in type");
        return false;
    }
    if (attribute->as.attribute.arguments.count != 1)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] requires exactly one primitive constant kind");
        return false;
    }

    const VcAstNode *argument = attribute->as.attribute.arguments.items[0];
    if (argument == NULL || argument->kind != VC_AST_LITERAL_EXPRESSION ||
        argument->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] kind must be a string literal");
        return false;
    }

    const char *text = argument->as.literal_expression.text;
    VcPrimitiveConstantKind parsed = VC_PRIMITIVE_CONSTANT_NONE;
    if (text != NULL && strcmp(text, "\"min\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_MIN;
    else if (text != NULL && strcmp(text, "\"max\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_MAX;
    else if (text != NULL && strcmp(text, "\"epsilon\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_EPSILON;
    else if (text != NULL && strcmp(text, "\"nan\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_NAN;
    else if (text != NULL && strcmp(text, "\"positive-infinity\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_POSITIVE_INFINITY;
    else if (text != NULL && strcmp(text, "\"negative-infinity\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_NEGATIVE_INFINITY;
    else if (text != NULL && strcmp(text, "\"zero\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_ZERO;
    else if (text != NULL && strcmp(text, "\"one\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_ONE;
    else if (text != NULL && strcmp(text, "\"minus-one\"") == 0) parsed = VC_PRIMITIVE_CONSTANT_MINUS_ONE;
    if (parsed == VC_PRIMITIVE_CONSTANT_NONE)
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[PrimitiveConstant] kind is not supported");
        return false;
    }

    bool supported = false;
    switch (field_type)
    {
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_CHAR:
            supported = parsed == VC_PRIMITIVE_CONSTANT_MIN || parsed == VC_PRIMITIVE_CONSTANT_MAX;
            break;
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
            supported = parsed == VC_PRIMITIVE_CONSTANT_MIN || parsed == VC_PRIMITIVE_CONSTANT_MAX ||
                parsed == VC_PRIMITIVE_CONSTANT_EPSILON || parsed == VC_PRIMITIVE_CONSTANT_NAN ||
                parsed == VC_PRIMITIVE_CONSTANT_POSITIVE_INFINITY ||
                parsed == VC_PRIMITIVE_CONSTANT_NEGATIVE_INFINITY;
            break;
        case VC_SEM_TYPE_DECIMAL:
            supported = parsed == VC_PRIMITIVE_CONSTANT_MIN || parsed == VC_PRIMITIVE_CONSTANT_MAX ||
                parsed == VC_PRIMITIVE_CONSTANT_ZERO || parsed == VC_PRIMITIVE_CONSTANT_ONE ||
                parsed == VC_PRIMITIVE_CONSTANT_MINUS_ONE;
            break;
        default:
            break;
    }
    if (!supported)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[PrimitiveConstant] kind is not valid for built-in type '%s'",
            vc_semantic_type_name(NULL, field_type));
        return false;
    }

    *kind = parsed;
    return true;
}

/* [BuiltInAssociated("int")] is a StandardLibrary-only bootstrap bridge from
   a canonical built-in semantic type to an ordinary declaration/member scope.
   The scope is never the runtime representation of the built-in value. */
static bool builtin_associated_type_from_declaration(
    const VcAstNode *declaration,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    VcSemanticType *associated_type)
{
    *associated_type = VC_SEM_TYPE_UNKNOWN;
    const VcAstNode *attribute = find_attribute(declaration, "BuiltInAssociated");
    if (attribute == NULL)
        return true;

    if (!source_is_standard_library(source))
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[BuiltInAssociated] is reserved for StandardLibrary built-in member scopes");
        return false;
    }
    if (declaration->kind != VC_AST_TYPE_DECLARATION ||
        declaration->as.type_declaration.type_kind != VC_AST_TYPE_CLASS ||
        (declaration->as.type_declaration.modifiers & VC_AST_MOD_STATIC) == 0)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[BuiltInAssociated] requires a static class declaration");
        return false;
    }
    if (attribute->as.attribute.arguments.count != 1)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[BuiltInAssociated] requires exactly one built-in type name");
        return false;
    }

    const VcAstNode *argument = attribute->as.attribute.arguments.items[0];
    if (argument == NULL || argument->kind != VC_AST_LITERAL_EXPRESSION ||
        argument->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[BuiltInAssociated] type name must be a string literal");
        return false;
    }

    const char *text = argument->as.literal_expression.text;
    const size_t length = text != NULL ? strlen(text) : 0;
    if (length < 3 || text[0] != '"' || text[length - 1] != '"' || length - 2 >= 32)
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[BuiltInAssociated] type name is invalid");
        return false;
    }

    char name[32];
    memcpy(name, text + 1, length - 2);
    name[length - 2] = '\0';
    VcAstTypeRef ref = {0};
    ref.name = name;
    const VcSemanticType type = vc_semantic_builtin_type_from_ast(&ref);
    if (type == VC_SEM_TYPE_UNKNOWN || type == VC_SEM_TYPE_VOID ||
        type == VC_SEM_TYPE_TYPE || type == VC_SEM_TYPE_NULL)
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[BuiltInAssociated] '%s' is not a supported built-in associated-member type",
            name);
        return false;
    }
    *associated_type = type;
    return true;
}

static bool collect_struct_names(
    const VcAstNodeList *declarations,
    const VcSource *source,
    const char *namespace_name,
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t i = 0; i < declarations->count; i++)
    {
        const VcAstNode *declaration = declarations->items[i];
        if (declaration->kind == VC_AST_NAMESPACE_DECLARATION)
        {
            if (!collect_struct_names(&declaration->as.namespace_declaration.declarations, source,
                    declaration->as.namespace_declaration.name, model, diagnostic))
                return false;
            continue;
        }

        if (declaration->kind != VC_AST_TYPE_DECLARATION ||
            (declaration->as.type_declaration.type_kind != VC_AST_TYPE_STRUCT &&
             declaration->as.type_declaration.type_kind != VC_AST_TYPE_CLASS &&
             declaration->as.type_declaration.type_kind != VC_AST_TYPE_INTERFACE &&
             declaration->as.type_declaration.type_kind != VC_AST_TYPE_DELEGATE &&
             declaration->as.type_declaration.type_kind != VC_AST_TYPE_ENUM))
            continue;

        if (declaration->as.type_declaration.generic_parameters.count != 0)
            continue;

        if (!validate_runtime_attributes(declaration, source, diagnostic))
            return false;

        for (size_t existing = 0; existing < model->struct_count; existing++)
        {
            if (same_namespace(model->structs[existing].namespace_name, namespace_name) &&
                strcmp(model->structs[existing].name, declaration->as.type_declaration.name) == 0)
            {
                set_diagnostic(diagnostic, source, declaration->location,
                    "type '%s' is already declared in namespace '%s'",
                    declaration->as.type_declaration.name, namespace_name != NULL ? namespace_name : "<global>");
                vc_diagnostic_set_code(diagnostic, VC_DIAG_DUPLICATE);
                related_declaration(diagnostic, model->structs[existing].source,
                    model->structs[existing].node, "Previous type declaration is here.");
                return false;
            }
        }

        VcSemanticType associated_builtin_type = VC_SEM_TYPE_UNKNOWN;
        if (!builtin_associated_type_from_declaration(declaration, source, diagnostic,
                &associated_builtin_type))
            return false;
        if (associated_builtin_type != VC_SEM_TYPE_UNKNOWN &&
            model->builtin_associated_owners[associated_builtin_type] != (size_t)-1)
        {
            set_diagnostic(diagnostic, source, declaration->location,
                "built-in type '%s' already has an associated member scope",
                context_type_display_name(&diagnostic_display_context, associated_builtin_type));
            return false;
        }

        VcSemanticStruct structure = {0};
        structure.node = declaration;
        structure.source = source;
        structure.namespace_name = namespace_name;
        structure.name = declaration->as.type_declaration.name;
        structure.is_delegate = declaration->as.type_declaration.type_kind == VC_AST_TYPE_DELEGATE;
        structure.is_enum = declaration->as.type_declaration.type_kind == VC_AST_TYPE_ENUM;
        structure.is_class = declaration->as.type_declaration.type_kind == VC_AST_TYPE_CLASS || structure.is_delegate;
        structure.is_interface = declaration->as.type_declaration.type_kind == VC_AST_TYPE_INTERFACE;
        structure.enum_underlying_type = VC_SEM_TYPE_INT;
        structure.delegate_invoke_method_index = (size_t)-1;
        structure.is_abstract = (declaration->as.type_declaration.modifiers & VC_AST_MOD_ABSTRACT) != 0;
        structure.is_sealed = (declaration->as.type_declaration.modifiers & VC_AST_MOD_SEALED) != 0;
        structure.is_readonly = (declaration->as.type_declaration.modifiers & VC_AST_MOD_READONLY) != 0;
        structure.is_ref_struct = (declaration->as.type_declaration.modifiers & VC_AST_MOD_REF) != 0;
        structure.is_builtin_associated_scope = associated_builtin_type != VC_SEM_TYPE_UNKNOWN;
        structure.associated_builtin_type = associated_builtin_type;
        snprintf(structure.c_name, sizeof(structure.c_name), structure.is_delegate ? "vc_d_%zu" :
            (structure.is_enum ? "vc_e_%zu" :
            (structure.is_class ? "vc_c_%zu" : (structure.is_interface ? "vc_i_%zu" : "vc_s_%zu"))),
            model->struct_count);
        const size_t structure_index = model->struct_count;
        if (!push_struct(model, structure))
        {
            set_diagnostic(diagnostic, source, declaration->location, "out of memory while collecting structs");
            return false;
        }
        if (associated_builtin_type != VC_SEM_TYPE_UNKNOWN)
            model->builtin_associated_owners[associated_builtin_type] = structure_index;
    }
    return true;
}

static bool class_is_same_or_derived(const VcSemanticModel *model, size_t type_index, size_t base_index)
{
    if (type_index >= model->struct_count || base_index >= model->struct_count)
        return false;

    size_t current = type_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        if (current == base_index)
            return true;
        const VcSemanticStruct *structure = &model->structs[current];
        if (!structure->has_base_class)
            return false;
        current = structure->base_class_index;
    }
    return false;
}

static bool find_exception_struct(const VcSemanticModel *model, size_t *index)
{
    for (size_t i = 0; i < model->struct_count; i++)
    {
        const VcSemanticStruct *structure = &model->structs[i];
        if (!structure->is_class || structure->name == NULL ||
            strcmp(structure->name, "Exception") != 0)
            continue;
        if (structure->namespace_name != NULL && structure->namespace_name[0] != '\0')
            continue;
        *index = i;
        return true;
    }
    return false;
}

static bool find_idisposable_struct(const VcSemanticModel *model, size_t *index)
{
    for (size_t i = 0; i < model->struct_count; i++)
    {
        const VcSemanticStruct *structure = &model->structs[i];
        if (!structure->is_interface || structure->name == NULL ||
            strcmp(structure->name, "IDisposable") != 0)
            continue;
        if (structure->namespace_name != NULL && structure->namespace_name[0] != '\0')
            continue;
        *index = i;
        return true;
    }
    return false;
}

static bool interface_is_same_or_derived_depth(
    const VcSemanticModel *model,
    size_t interface_index,
    size_t base_interface_index,
    size_t depth)
{
    if (interface_index >= model->struct_count || base_interface_index >= model->struct_count ||
        !model->structs[interface_index].is_interface ||
        !model->structs[base_interface_index].is_interface ||
        depth > model->struct_count)
        return false;

    if (interface_index == base_interface_index)
        return true;

    const VcSemanticStruct *structure = &model->structs[interface_index];
    for (size_t i = 0; i < structure->interface_count; i++)
    {
        if (interface_is_same_or_derived_depth(model, structure->interfaces[i],
                base_interface_index, depth + 1))
            return true;
    }
    return false;
}

static bool interface_is_same_or_derived(
    const VcSemanticModel *model,
    size_t interface_index,
    size_t base_interface_index)
{
    return interface_is_same_or_derived_depth(
        model, interface_index, base_interface_index, 0);
}

static bool type_implements_interface(
    const VcSemanticModel *model,
    size_t type_index,
    size_t interface_index)
{
    if (type_index >= model->struct_count || interface_index >= model->struct_count ||
        model->structs[type_index].is_interface || model->structs[type_index].is_enum ||
        model->structs[type_index].is_delegate || !model->structs[interface_index].is_interface)
        return false;

    size_t current = type_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->interface_count; i++)
        {
            if (interface_is_same_or_derived(model,
                    structure->interfaces[i], interface_index))
                return true;
        }
        if (!structure->is_class || !structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool resolve_base_classes(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    for (size_t i = 0; i < model->struct_count; i++)
    {
        VcSemanticStruct *structure = &model->structs[i];
        const VcAstNode *declaration = structure->node;
        const size_t base_count = declaration->as.type_declaration.base_types.count;

        if (structure->is_ref_struct &&
            declaration->as.type_declaration.type_kind != VC_AST_TYPE_STRUCT)
        {
            set_diagnostic(diagnostic, structure->source, declaration->location,
                "ref type modifier is supported on value structs only");
            return false;
        }

        if (structure->is_enum)
        {
            if (structure->is_abstract || structure->is_sealed || structure->is_readonly ||
                (declaration->as.type_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "enum '%s' cannot be abstract, sealed, readonly, or static", structure->name);
                return false;
            }
            if (base_count > 1)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "enum '%s' can declare at most one underlying type", structure->name);
                return false;
            }
            if (base_count == 1)
            {
                const VcAstTypeRef *underlying = declaration->as.type_declaration.base_types.items[0];
                const VcSemanticType type = vc_semantic_builtin_type_from_ast(underlying);
                switch (type)
                {
                    case VC_SEM_TYPE_BYTE:
                    case VC_SEM_TYPE_SBYTE:
                    case VC_SEM_TYPE_SHORT:
                    case VC_SEM_TYPE_USHORT:
                    case VC_SEM_TYPE_INT:
                    case VC_SEM_TYPE_UINT:
                    case VC_SEM_TYPE_LONG:
                    case VC_SEM_TYPE_ULONG:
                        structure->enum_underlying_type = type;
                        break;
                    default:
                        set_diagnostic(diagnostic, structure->source, underlying->location,
                            "enum '%s' underlying type must be an integral type", structure->name);
                        return false;
                }
            }
            continue;
        }

        if (structure->is_delegate)
        {
            if (base_count != 0)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "delegate '%s' cannot declare base types", structure->name);
                return false;
            }
            if (structure->is_abstract || structure->is_readonly ||
                (declaration->as.type_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "delegate '%s' cannot be abstract, readonly, or static", structure->name);
                return false;
            }
            continue;
        }

        if (structure->is_interface)
        {
            for (size_t base_pos = 0; base_pos < base_count; base_pos++)
            {
                const VcAstTypeRef *base_ref = declaration->as.type_declaration.base_types.items[base_pos];
                const VcSemanticType base_type = resolve_type(
                    model, base_ref, structure->namespace_name, false);
                if (!vc_semantic_type_is_struct(base_type))
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "base interface '%s' could not be resolved", base_ref->name);
                    return false;
                }

                const size_t base_index = vc_semantic_struct_index(base_type);
                if (base_index >= model->struct_count || !model->structs[base_index].is_interface)
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "interface '%s' can inherit only from interfaces", structure->name);
                    return false;
                }
                if (base_index == i)
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "interface '%s' cannot inherit from itself", structure->name);
                    return false;
                }
                if (!push_interface(structure, base_index))
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "out of memory while recording interface inheritance");
                    return false;
                }
            }
            if (structure->is_abstract || structure->is_sealed || structure->is_readonly)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "interfaces cannot be declared abstract, sealed, or readonly");
                return false;
            }
            continue;
        }

        if (!structure->is_class)
        {
            if (structure->is_ref_struct && base_count != 0)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "ref struct '%s' cannot implement interfaces", structure->name);
                return false;
            }
            for (size_t base_pos = 0; base_pos < base_count; base_pos++)
            {
                const VcAstTypeRef *base_ref = declaration->as.type_declaration.base_types.items[base_pos];
                const VcSemanticType base_type = resolve_type(
                    model, base_ref, structure->namespace_name, false);
                if (!vc_semantic_type_is_struct(base_type))
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "interface '%s' could not be resolved", base_ref->name);
                    return false;
                }
                const size_t base_index = vc_semantic_struct_index(base_type);
                if (base_index >= model->struct_count || !model->structs[base_index].is_interface)
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "struct '%s' can implement only interfaces", structure->name);
                    return false;
                }
                if (!push_interface(structure, base_index))
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "out of memory while recording struct interface implementation");
                    return false;
                }
            }
            if (structure->is_abstract || structure->is_sealed)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "abstract/sealed type modifiers are supported on classes only");
                return false;
            }
            if (structure->is_ref_struct &&
                (declaration->as.type_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
            {
                set_diagnostic(diagnostic, structure->source, declaration->location,
                    "ref struct '%s' cannot be static", structure->name);
                return false;
            }
            continue;
        }

        if (structure->is_readonly)
        {
            set_diagnostic(diagnostic, structure->source, declaration->location,
                "readonly type modifier is supported on value structs only");
            return false;
        }

        if (structure->is_abstract && structure->is_sealed)
        {
            set_diagnostic(diagnostic, structure->source, declaration->location,
                "class '%s' cannot be both abstract and sealed", structure->name);
            return false;
        }

        bool saw_interface = false;
        for (size_t base_pos = 0; base_pos < base_count; base_pos++)
        {
            const VcAstTypeRef *base_ref = declaration->as.type_declaration.base_types.items[base_pos];
            const VcSemanticType base_type = resolve_type(model, base_ref, structure->namespace_name, false);
            if (!vc_semantic_type_is_struct(base_type))
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "base type '%s' could not be resolved", base_ref->name);
                return false;
            }

            const size_t base_index = vc_semantic_struct_index(base_type);
            if (base_index >= model->struct_count)
                return false;
            const VcSemanticStruct *base = &model->structs[base_index];

            if (base->is_interface)
            {
                saw_interface = true;
                if (!push_interface(structure, base_index))
                {
                    set_diagnostic(diagnostic, structure->source, base_ref->location,
                        "out of memory while recording interface implementation");
                    return false;
                }
                continue;
            }

            if (!base->is_class)
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "class '%s' can inherit only from a class and interfaces", structure->name);
                return false;
            }
            if (saw_interface)
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "base class '%s' must appear before interfaces", base->name);
                return false;
            }
            if (structure->has_base_class)
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "class '%s' cannot inherit from multiple classes", structure->name);
                return false;
            }
            if (base_index == i)
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "class '%s' cannot inherit from itself", structure->name);
                return false;
            }
            if (base->is_sealed)
            {
                set_diagnostic(diagnostic, structure->source, base_ref->location,
                    "class '%s' cannot inherit from sealed class '%s'", structure->name, base->name);
                return false;
            }

            structure->has_base_class = true;
            structure->base_class_index = base_index;
        }
    }

    for (size_t i = 0; i < model->struct_count; i++)
    {
        const VcSemanticStruct *structure = &model->structs[i];
        if (!structure->is_interface)
            continue;
        for (size_t parent = 0; parent < structure->interface_count; parent++)
        {
            if (interface_is_same_or_derived(
                    model, structure->interfaces[parent], i))
            {
                set_diagnostic(diagnostic, structure->source, structure->node->location,
                    "interface inheritance cycle involving '%s'", structure->name);
                return false;
            }
        }
    }

    for (size_t i = 0; i < model->struct_count; i++)
    {
        if (!model->structs[i].is_class)
            continue;
        size_t slow = i;
        size_t fast = i;
        for (;;)
        {
            const VcSemanticStruct *s = &model->structs[slow];
            if (!s->has_base_class)
                break;
            slow = s->base_class_index;

            for (int step = 0; step < 2; step++)
            {
                const VcSemanticStruct *f = &model->structs[fast];
                if (!f->has_base_class)
                {
                    fast = (size_t)-1;
                    break;
                }
                fast = f->base_class_index;
            }
            if (fast == (size_t)-1)
                break;
            if (slow == fast)
            {
                set_diagnostic(diagnostic, model->structs[i].source, model->structs[i].node->location,
                    "inheritance cycle involving class '%s'", model->structs[i].name);
                return false;
            }
        }
    }
    return true;
}

static bool collect_struct_members(
    VcSemanticModel *model,
    bool allow_unsafe,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t struct_index = 0; struct_index < model->struct_count; struct_index++)
    {
        VcSemanticStruct *structure = &model->structs[struct_index];
        const VcAstNodeList *members = &structure->node->as.type_declaration.members;

        if (structure->is_enum)
        {
            int64_t next_value = 0;
            for (size_t i = 0; i < members->count; i++)
            {
                const VcAstNode *member = members->items[i];
                if (member == NULL || member->kind != VC_AST_ENUM_MEMBER)
                {
                    set_diagnostic(diagnostic, structure->source, structure->node->location,
                        "enum '%s' contains an invalid member", structure->name);
                    return false;
                }
                for (size_t existing = 0; existing < structure->enum_member_count; existing++)
                {
                    if (strcmp(structure->enum_member_names[existing], member->as.enum_member.name) == 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "enum member '%s.%s' is declared more than once",
                            structure->name, member->as.enum_member.name);
                        return false;
                    }
                }

                int64_t value = next_value;
                if (member->as.enum_member.value != NULL &&
                    !evaluate_enum_value(member->as.enum_member.value, &value))
                {
                    set_diagnostic(diagnostic, structure->source, member->as.enum_member.value->location,
                        "enum member '%s.%s' requires an integral constant value",
                        structure->name, member->as.enum_member.name);
                    return false;
                }
                if (!enum_value_fits(structure->enum_underlying_type, value))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "enum member '%s.%s' value is outside the range of '%s'",
                        structure->name, member->as.enum_member.name,
                        context_type_display_name(&diagnostic_display_context, structure->enum_underlying_type));
                    return false;
                }
                if (!push_enum_member(structure, member->as.enum_member.name, value))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "out of memory while collecting enum members");
                    return false;
                }

                if (value == INT64_MAX)
                {
                    if (i + 1 < members->count && members->items[i + 1]->as.enum_member.value == NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, members->items[i + 1]->location,
                            "enum member '%s.%s' implicit value overflows",
                            structure->name, members->items[i + 1]->as.enum_member.name);
                        return false;
                    }
                    next_value = value;
                }
                else
                    next_value = value + 1;
            }
            continue;
        }

        const bool type_unsafe =
            (structure->node->as.type_declaration.modifiers & VC_AST_MOD_UNSAFE) != 0;
        if (type_unsafe && !allow_unsafe && !source_is_standard_library(structure->source))
        {
            const char *unsafe_kind = structure->is_delegate ? "delegate" :
                structure->is_interface ? "interface" : structure->is_class ? "class" : "struct";
            set_diagnostic(diagnostic, structure->source, structure->node->location,
                "unsafe %s '%s' requires compiler unsafe to be enabled",
                unsafe_kind, structure->name);
            return false;
        }
        if (structure->is_delegate)
        {
            if (members->count != 1 || members->items[0]->kind != VC_AST_METHOD_DECLARATION ||
                strcmp(members->items[0]->as.method_declaration.name, "Invoke") != 0)
            {
                set_diagnostic(diagnostic, structure->source, structure->node->location,
                    "delegate '%s' has an invalid compiler signature", structure->name);
                return false;
            }
            continue;
        }
        for (size_t i = 0; i < members->count; i++)
        {
            const VcAstNode *member = members->items[i];
            if (structure->is_interface)
            {
                if (member->kind == VC_AST_METHOD_DECLARATION &&
                    !member->as.method_declaration.is_constructor)
                    continue;

                if (member->kind == VC_AST_PROPERTY_DECLARATION)
                {
                    const bool interface_property_static =
                        (member->as.property_declaration.modifiers & VC_AST_MOD_STATIC) != 0;
                    if (!member->as.property_declaration.has_getter ||
                        !member->as.property_declaration.getter_auto ||
                        member->as.property_declaration.getter_body != NULL ||
                        member->as.property_declaration.getter_expression ||
                        (member->as.property_declaration.has_setter &&
                         !member->as.property_declaration.setter_auto) ||
                        (!interface_property_static && member->as.property_declaration.has_setter))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            interface_property_static
                                ? "static interface property '%s' must be a property signature ending in ';'"
                                : "interface property '%s' must be a get-only signature ending in ';'",
                            member->as.property_declaration.name);
                        return false;
                    }
                    /* Continue into the normal property collector below. */
                }
                else if (member->kind == VC_AST_FIELD_DECLARATION &&
                    member->as.field_declaration.is_event)
                {
                    const uint32_t event_modifiers = member->as.field_declaration.modifiers;
                    const bool interface_event_static =
                        (event_modifiers & VC_AST_MOD_STATIC) != 0;
                    const bool interface_event_custom =
                        member->as.field_declaration.has_event_add_accessor ||
                        member->as.field_declaration.has_event_remove_accessor;
                    if (interface_event_custom)
                    {
                        if (!member->as.field_declaration.has_event_add_accessor ||
                            !member->as.field_declaration.has_event_remove_accessor ||
                            member->as.field_declaration.event_add_body != NULL ||
                            member->as.field_declaration.event_remove_body != NULL ||
                            member->as.field_declaration.initializer != NULL)
                        {
                            set_diagnostic(diagnostic, structure->source, member->location,
                                "interface event '%s' custom accessors must be add/remove declarations ending in ';'",
                                member->as.field_declaration.name);
                            return false;
                        }
                    }
                    if (interface_event_static)
                    {
                        const uint32_t allowed_event_modifiers =
                            VC_AST_MOD_PUBLIC | VC_AST_MOD_STATIC;
                        if ((event_modifiers & ~allowed_event_modifiers) != 0)
                        {
                            set_diagnostic(diagnostic, structure->source, member->location,
                                "static interface event '%s' may only use public and static modifiers",
                                member->as.field_declaration.name);
                            return false;
                        }
                        if (member->as.field_declaration.initializer != NULL)
                        {
                            set_diagnostic(diagnostic, structure->source, member->location,
                                "static interface event '%s' cannot have an initializer",
                                member->as.field_declaration.name);
                            return false;
                        }
                    }
                    else if ((event_modifiers & ~(uint32_t)VC_AST_MOD_PUBLIC) != 0 ||
                        member->as.field_declaration.initializer != NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "interface event '%s' must be an instance signature ending in ';'",
                            member->as.field_declaration.name);
                        return false;
                    }
                    /* Continue into the normal event collector below. */
                }
                else
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "interfaces support method, get-only property, and event declarations");
                    return false;
                }
            }

            if (member->kind == VC_AST_FIELD_DECLARATION)
            {
                if ((member->as.field_declaration.modifiers & VC_AST_MOD_ASYNC) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "'async' modifier is valid only on methods");
                    return false;
                }
                const bool field_const =
                    (member->as.field_declaration.modifiers & VC_AST_MOD_CONST) != 0;
                const bool field_readonly =
                    (member->as.field_declaration.modifiers & VC_AST_MOD_READONLY) != 0;
                const bool field_static = !field_const &&
                    (member->as.field_declaration.modifiers & VC_AST_MOD_STATIC) != 0;
                const bool field_ref = member->as.field_declaration.is_ref;
                const bool field_ref_readonly = member->as.field_declaration.ref_readonly;
                const bool event_custom = member->as.field_declaration.is_event &&
                    (member->as.field_declaration.has_event_add_accessor ||
                     member->as.field_declaration.has_event_remove_accessor);
                const bool event_virtual = member->as.field_declaration.is_event &&
                    (member->as.field_declaration.modifiers & VC_AST_MOD_VIRTUAL) != 0;
                const bool event_override = member->as.field_declaration.is_event &&
                    (member->as.field_declaration.modifiers & VC_AST_MOD_OVERRIDE) != 0;
                const bool event_abstract = member->as.field_declaration.is_event &&
                    (member->as.field_declaration.modifiers & VC_AST_MOD_ABSTRACT) != 0;
                const bool event_sealed = member->as.field_declaration.is_event &&
                    (member->as.field_declaration.modifiers & VC_AST_MOD_SEALED) != 0;
                const bool event_dispatch = event_virtual || event_override ||
                    event_abstract || event_sealed;

                if (member->as.field_declaration.is_event &&
                    !field_static && !structure->is_class && !structure->is_interface)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "instance events are supported on classes only");
                    return false;
                }
                if (member->as.field_declaration.is_event && (field_const || field_readonly))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "events cannot be const or readonly");
                    return false;
                }
                if (event_custom &&
                    (!member->as.field_declaration.has_event_add_accessor ||
                     !member->as.field_declaration.has_event_remove_accessor))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "custom event '%s' must declare both add and remove accessors",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_custom && member->as.field_declaration.initializer != NULL)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "custom event '%s' cannot have an initializer",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_custom && !structure->is_interface && !event_abstract &&
                    (member->as.field_declaration.event_add_body == NULL ||
                     member->as.field_declaration.event_remove_body == NULL))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "custom event '%s' add and remove accessors must have bodies",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_abstract && !event_custom)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract event '%s' must declare custom add/remove accessors",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_abstract &&
                    (member->as.field_declaration.event_add_body != NULL ||
                     member->as.field_declaration.event_remove_body != NULL))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract event '%s' accessors cannot have bodies",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_dispatch && (!structure->is_class || structure->is_interface))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "virtual/override/abstract/sealed events are supported on classes only");
                    return false;
                }
                if (event_dispatch && !event_custom)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "virtual/override/abstract/sealed event '%s' must declare custom add/remove accessors",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_dispatch && field_static)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "virtual/override/abstract/sealed events cannot be static");
                    return false;
                }
                if (event_virtual && (event_override || event_abstract))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "event '%s' cannot combine virtual with override or abstract",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_sealed && !event_override)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "sealed event '%s' must also be override",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_abstract && event_sealed)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract event '%s' cannot be sealed",
                        member->as.field_declaration.name);
                    return false;
                }
                if (event_abstract && !structure->is_abstract)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract event '%s' requires an abstract class",
                        member->as.field_declaration.name);
                    return false;
                }
                if (field_const && field_readonly)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "field '%s' cannot be both const and readonly",
                        member->as.field_declaration.name);
                    return false;
                }
                if (field_const && (member->as.field_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "const field '%s' is implicitly static and must not use 'static'",
                        member->as.field_declaration.name);
                    return false;
                }
                if (field_ref)
                {
                    if (!structure->is_ref_struct)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref field '%s' is supported only in a ref struct",
                            member->as.field_declaration.name);
                        return false;
                    }
                    if (field_static || field_const || member->as.field_declaration.is_event)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref field '%s' must be an instance non-const field",
                            member->as.field_declaration.name);
                        return false;
                    }
                    if (member->as.field_declaration.initializer != NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref field '%s' cannot have a field initializer",
                            member->as.field_declaration.name);
                        return false;
                    }
                    if (field_readonly)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref field '%s' uses 'ref readonly' rather than the readonly field modifier",
                            member->as.field_declaration.name);
                        return false;
                    }
                    if (structure->is_readonly && !field_ref_readonly)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref field '%s' in readonly ref struct '%s' must be ref readonly",
                            member->as.field_declaration.name, structure->name);
                        return false;
                    }
                }
                if (structure->is_readonly && !field_ref && !field_const && !field_static && !field_readonly)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "instance field '%s' in readonly struct '%s' must be readonly",
                        member->as.field_declaration.name, structure->name);
                    return false;
                }
                if (field_const && member->as.field_declaration.initializer == NULL)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "const field '%s' requires an initializer",
                        member->as.field_declaration.name);
                    return false;
                }
                if (member->as.field_declaration.is_event && structure->is_interface &&
                    member->as.field_declaration.initializer != NULL)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "interface event '%s' cannot have an initializer",
                        member->as.field_declaration.name);
                    return false;
                }

                const VcSemanticType field_type = resolve_type(model, member->as.field_declaration.type,
                    structure->namespace_name, false);
                if (field_type == VC_SEM_TYPE_UNKNOWN || field_type == VC_SEM_TYPE_VOID)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "field type '%s' is not supported",
                        member->as.field_declaration.type != NULL ? member->as.field_declaration.type->name : "<unknown>");
                    return false;
                }
                if (semantic_type_is_ref_struct(model, field_type))
                {
                    if (field_static || !structure->is_ref_struct)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "ref struct field '%s' is allowed only as instance storage inside another ref struct",
                            member->as.field_declaration.name);
                        return false;
                    }
                }
                if (field_const && !constant_field_type_supported(model, field_type))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "const field '%s' uses unsupported constant type '%s'",
                        member->as.field_declaration.name,
                        context_type_display_name(&diagnostic_display_context, field_type));
                    return false;
                }
                if (vc_semantic_type_is_pointer(field_type))
                {
                    if (structure->is_class || structure->is_interface || !type_unsafe)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "pointer field '%s' requires an unsafe value struct",
                            member->as.field_declaration.name);
                        return false;
                    }
                    const VcAstNodeList *owner_constraints =
                        structure->node != NULL && structure->node->kind == VC_AST_TYPE_DECLARATION
                            ? &structure->node->as.type_declaration.generic_constraints : NULL;
                    const char *missing_parameter = NULL;
                    if (!generic_type_ref_has_required_unmanaged_constraints(
                            member->as.field_declaration.type, owner_constraints, NULL,
                            &missing_parameter))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "generic pointer field '%s' using '%s' requires 'where %s : unmanaged'",
                            member->as.field_declaration.name,
                            missing_parameter != NULL ? missing_parameter : "<generic>",
                            missing_parameter != NULL ? missing_parameter : "T");
                        return false;
                    }
                    if (type_ref_has_generic_parameter_origin(member->as.field_declaration.type) &&
                        !vc_semantic_type_is_unmanaged(model,
                            vc_semantic_pointer_element_type(model, field_type)))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "generic pointer field '%s' requires an unmanaged element type",
                            member->as.field_declaration.name);
                        return false;
                    }
                }
                if (vc_semantic_type_is_function_pointer(field_type))
                {
                    const bool generic_function_pointer =
                        type_ref_has_generic_parameter_origin(member->as.field_declaration.type);
                    if (structure->is_class || structure->is_interface ||
                        (!type_unsafe && !generic_function_pointer))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "native function pointer field '%s' requires an unsafe value struct",
                            member->as.field_declaration.name);
                        return false;
                    }
                }
                if (member->as.field_declaration.is_event && !semantic_type_is_delegate(model, field_type))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "event '%s' must use a delegate type",
                        member->as.field_declaration.name);
                    return false;
                }
                for (size_t field_index = 0; field_index < structure->field_count; field_index++)
                {
                    if (strcmp(structure->fields[field_index].node->as.field_declaration.name,
                            member->as.field_declaration.name) == 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "field '%s' is already declared", member->as.field_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_DUPLICATE);
                        related_declaration(diagnostic, structure->source,
                            structure->fields[field_index].node, "Previous field declaration is here.");
                        return false;
                    }
                }
                for (size_t property_index = 0; property_index < structure->property_count; property_index++)
                {
                    if (strcmp(structure->properties[property_index].node->as.property_declaration.name,
                            member->as.field_declaration.name) == 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "member '%s' is already declared", member->as.field_declaration.name);
                        return false;
                    }
                }

                VcSemanticField field = {0};
                field.node = member;
                field.type = field_type;
                field.is_event = member->as.field_declaration.is_event;
                field.is_custom_event = event_custom;
                field.is_virtual = event_virtual;
                field.is_override = event_override;
                field.is_abstract = event_abstract;
                field.is_sealed = event_sealed;
                field.is_const = field_const;
                if (!primitive_constant_kind_from_attribute(member, structure, field_type,
                        structure->source, diagnostic, &field.primitive_constant_kind))
                    return false;
                field.is_readonly = field_readonly;
                field.is_ref = field_ref;
                field.ref_readonly = field_ref_readonly;
                field.is_static = field_static;
                if (field.is_static)
                    snprintf(field.c_name, sizeof(field.c_name), "vc_sf_%zu_%zu", struct_index, structure->field_count);
                else
                    snprintf(field.c_name, sizeof(field.c_name), "vc_f_%zu", structure->field_count);
                if (field.is_custom_event)
                {
                    snprintf(field.event_add_c_name, sizeof(field.event_add_c_name),
                        "vc_eadd_%zu_%zu", struct_index, structure->field_count);
                    snprintf(field.event_remove_c_name, sizeof(field.event_remove_c_name),
                        "vc_erem_%zu_%zu", struct_index, structure->field_count);
                }
                if (!push_field(structure, field))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "out of memory while collecting struct fields");
                    return false;
                }
                continue;
            }

            if (member->kind == VC_AST_PROPERTY_DECLARATION)
            {
                if ((member->as.property_declaration.modifiers & VC_AST_MOD_ASYNC) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "'async' modifier is valid only on methods");
                    return false;
                }
                const bool property_static =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_STATIC) != 0;
                const bool property_virtual =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_VIRTUAL) != 0;
                const bool property_override =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_OVERRIDE) != 0;
                const bool property_abstract =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_ABSTRACT) != 0;
                const bool property_sealed =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_SEALED) != 0;
                const bool property_readonly =
                    (member->as.property_declaration.modifiers & VC_AST_MOD_READONLY) != 0;
                const bool property_dispatch = property_virtual || property_override ||
                    property_abstract || property_sealed;
                if (property_dispatch && (!structure->is_class || structure->is_interface))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "virtual/override/abstract/sealed properties are supported on classes only");
                    return false;
                }
                if (property_readonly && (property_static || structure->is_class || structure->is_interface))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "readonly property '%s' requires an instance value struct",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_readonly && member->as.property_declaration.has_setter)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "readonly property '%s' cannot declare a setter; mark only its getter readonly instead",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_dispatch && property_static)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "virtual/override/abstract/sealed properties cannot be static");
                    return false;
                }
                if (property_virtual && (property_override || property_abstract))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property '%s' cannot combine virtual with override or abstract",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_sealed && !property_override)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "sealed property '%s' must also be override",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_abstract && property_sealed)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract property '%s' cannot be sealed",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_abstract && !structure->is_abstract)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract property '%s' requires an abstract class",
                        member->as.property_declaration.name);
                    return false;
                }
                if (!member->as.property_declaration.has_getter)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property '%s' must declare a getter",
                        member->as.property_declaration.name);
                    return false;
                }
                const uint32_t allowed_accessor_modifiers =
                    VC_AST_MOD_PUBLIC | VC_AST_MOD_PRIVATE | VC_AST_MOD_PROTECTED | VC_AST_MOD_INTERNAL |
                    VC_AST_MOD_READONLY;
                if ((member->as.property_declaration.getter_modifiers & ~allowed_accessor_modifiers) != 0 ||
                    (member->as.property_declaration.setter_modifiers & ~allowed_accessor_modifiers) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property accessors may only use access modifiers and readonly on getters");
                    return false;
                }
                if ((member->as.property_declaration.setter_modifiers & VC_AST_MOD_READONLY) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property setter '%s' cannot be readonly",
                        member->as.property_declaration.name);
                    return false;
                }
                const bool getter_readonly = (!property_static && structure->is_readonly) || property_readonly ||
                    (member->as.property_declaration.getter_modifiers & VC_AST_MOD_READONLY) != 0;
                if (getter_readonly && (property_static || structure->is_class || structure->is_interface))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "readonly getter '%s' requires an instance value struct",
                        member->as.property_declaration.name);
                    return false;
                }

                const bool getter_auto = member->as.property_declaration.getter_auto;
                const bool setter_auto = member->as.property_declaration.has_setter &&
                    member->as.property_declaration.setter_auto;
                const bool property_returns_ref = member->as.property_declaration.returns_ref;
                const bool property_returns_ref_readonly =
                    member->as.property_declaration.returns_ref_readonly;
                if (property_returns_ref && member->as.property_declaration.has_setter)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "ref-returning property '%s' cannot declare a setter",
                        member->as.property_declaration.name);
                    return false;
                }
                if (property_returns_ref && getter_auto && !structure->is_interface && !property_abstract)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "ref-returning property '%s' requires an explicit getter body",
                        member->as.property_declaration.name);
                    return false;
                }
                if (structure->is_interface && property_static)
                {
                    const uint32_t allowed_interface_property_modifiers =
                        VC_AST_MOD_PUBLIC | VC_AST_MOD_STATIC;
                    if ((member->as.property_declaration.modifiers &
                            ~allowed_interface_property_modifiers) != 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static interface property '%s' may only use public and static modifiers",
                            member->as.property_declaration.name);
                        return false;
                    }
                    if (!getter_auto ||
                        (member->as.property_declaration.has_setter && !setter_auto))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static interface property '%s' accessors must be declarations ending in ';'",
                            member->as.property_declaration.name);
                        return false;
                    }
                    if (member->as.property_declaration.getter_modifiers != 0 ||
                        member->as.property_declaration.setter_modifiers != 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static interface property '%s' accessors cannot declare modifiers",
                            member->as.property_declaration.name);
                        return false;
                    }
                }
                if (!property_static && structure->is_readonly && setter_auto)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "automatic property '%s' in readonly struct '%s' cannot declare a setter",
                        member->as.property_declaration.name, structure->name);
                    return false;
                }
                if (property_abstract &&
                    (!getter_auto || (member->as.property_declaration.has_setter && !setter_auto)))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "abstract property '%s' accessors cannot have bodies",
                        member->as.property_declaration.name);
                    return false;
                }
                if (!structure->is_interface && member->as.property_declaration.has_setter && getter_auto != setter_auto)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property '%s' cannot mix automatic and explicit accessors",
                        member->as.property_declaration.name);
                    return false;
                }
                if (member->as.property_declaration.initializer != NULL &&
                    (structure->is_interface || property_abstract || !getter_auto ||
                     (member->as.property_declaration.has_setter && !setter_auto)))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property initializer for '%s' requires an automatic property",
                        member->as.property_declaration.name);
                    return false;
                }

                const VcSemanticType property_type = resolve_type(model, member->as.property_declaration.type,
                    structure->namespace_name, false);
                if (property_type == VC_SEM_TYPE_UNKNOWN || property_type == VC_SEM_TYPE_VOID)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "property type '%s' is not supported",
                        member->as.property_declaration.type != NULL ? member->as.property_declaration.type->name : "<unknown>");
                    return false;
                }
                if (semantic_type_is_ref_struct(model, property_type) && getter_auto &&
                    !structure->is_interface && !property_abstract &&
                    (property_static || !structure->is_ref_struct))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "automatic ref struct property '%s' requires instance storage in a ref struct",
                        member->as.property_declaration.name);
                    return false;
                }
                if (vc_semantic_type_is_pointer(property_type))
                {
                    if (!type_unsafe)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "pointer property '%s' requires an unsafe containing type",
                            member->as.property_declaration.name);
                        return false;
                    }
                    const VcAstNodeList *owner_constraints =
                        structure->node != NULL && structure->node->kind == VC_AST_TYPE_DECLARATION
                            ? &structure->node->as.type_declaration.generic_constraints : NULL;
                    const char *missing_parameter = NULL;
                    if (!generic_type_ref_has_required_unmanaged_constraints(
                            member->as.property_declaration.type, owner_constraints, NULL,
                            &missing_parameter))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "generic pointer property '%s' using '%s' requires 'where %s : unmanaged'",
                            member->as.property_declaration.name,
                            missing_parameter != NULL ? missing_parameter : "<generic>",
                            missing_parameter != NULL ? missing_parameter : "T");
                        return false;
                    }
                    if (!pointer_type_ref_element_supported(model, property_type,
                            member->as.property_declaration.type))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "pointer property type is not supported");
                        return false;
                    }
                }

                if (vc_semantic_type_is_function_pointer(property_type))
                {
                    const bool generic_function_pointer =
                        type_ref_has_generic_parameter_origin(member->as.property_declaration.type);
                    if (!type_unsafe && !generic_function_pointer)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "native function pointer property '%s' requires an unsafe containing type",
                            member->as.property_declaration.name);
                        return false;
                    }
                }

                for (size_t field_index = 0; field_index < structure->field_count; field_index++)
                {
                    if (strcmp(structure->fields[field_index].node->as.field_declaration.name,
                            member->as.property_declaration.name) == 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "member '%s' is already declared", member->as.property_declaration.name);
                        return false;
                    }
                }
                for (size_t property_index = 0; property_index < structure->property_count; property_index++)
                {
                    if (strcmp(structure->properties[property_index].node->as.property_declaration.name,
                            member->as.property_declaration.name) == 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "property '%s' is already declared", member->as.property_declaration.name);
                        return false;
                    }
                }

                VcSemanticProperty property = {0};
                property.node = member;
                property.type = property_type;
                property.returns_ref = property_returns_ref;
                property.returns_ref_readonly = property_returns_ref_readonly;
                property.has_getter = true;
                property.has_setter = member->as.property_declaration.has_setter;
                property.getter_readonly = getter_readonly;
                property.is_auto = !structure->is_interface && !property_abstract && getter_auto;
                property.is_static = property_static;
                property.is_virtual = property_virtual;
                property.is_override = property_override;
                property.is_abstract = property_abstract;
                property.is_sealed = property_sealed;
                snprintf(property.getter_c_name, sizeof(property.getter_c_name),
                    "vc_pg_%zu_%zu", struct_index, structure->property_count);
                snprintf(property.setter_c_name, sizeof(property.setter_c_name),
                    "vc_ps_%zu_%zu", struct_index, structure->property_count);
                if (property.is_static)
                    snprintf(property.backing_c_name, sizeof(property.backing_c_name),
                        "vc_spb_%zu_%zu", struct_index, structure->property_count);
                else
                    snprintf(property.backing_c_name, sizeof(property.backing_c_name),
                        "vc_pb_%zu", structure->property_count);
                if (!push_property(structure, property))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "out of memory while collecting properties");
                    return false;
                }
                continue;
            }

            if (member->kind == VC_AST_METHOD_DECLARATION && member->as.method_declaration.is_constructor)
            {
                const uint32_t constructor_modifiers = member->as.method_declaration.modifiers;
                const bool constructor_unsafe = (constructor_modifiers & VC_AST_MOD_UNSAFE) != 0;
                if ((constructor_modifiers & VC_AST_MOD_ASYNC) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "constructor '%s' cannot be async", structure->name);
                    return false;
                }
                if ((constructor_modifiers & VC_AST_MOD_READONLY) != 0)
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "constructor '%s' cannot be readonly", structure->name);
                    return false;
                }
                if ((constructor_modifiers & VC_AST_MOD_STATIC) != 0)
                {
                    const uint32_t allowed_static_constructor_modifiers =
                        VC_AST_MOD_STATIC | VC_AST_MOD_UNSAFE;
                    if ((constructor_modifiers & ~allowed_static_constructor_modifiers) != 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static constructor '%s' may only use static or unsafe modifiers",
                            structure->name);
                        return false;
                    }
                    if ((constructor_modifiers & VC_AST_MOD_UNSAFE) != 0 && !allow_unsafe && !source_is_standard_library(structure->source))
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "unsafe static constructor '%s' requires compiler unsafe to be enabled",
                            structure->name);
                        return false;
                    }
                    if (member->as.method_declaration.parameters.count != 0)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static constructor '%s' cannot declare parameters", structure->name);
                        return false;
                    }
                    if (member->as.method_declaration.body == NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "static constructor '%s' requires a body", structure->name);
                        return false;
                    }
                    if (structure->static_constructor_node != NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "type '%s' already declares a static constructor", structure->name);
                        return false;
                    }
                    structure->static_constructor_node = member;
                    continue;
                }

                if (constructor_unsafe && !allow_unsafe && !source_is_standard_library(structure->source))
                {
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "unsafe constructor '%s' requires compiler unsafe to be enabled",
                        structure->name);
                    return false;
                }

                VcSemanticConstructor constructor = {0};
                constructor.node = member;
                constructor.source = structure->source;
                constructor.struct_index = struct_index;
                constructor.parameter_count = member->as.method_declaration.parameters.count;
                snprintf(constructor.c_name, sizeof(constructor.c_name), "vc_ctor_%zu", model->constructor_count);

                if (constructor.parameter_count > 0)
                {
                    constructor.parameter_types = calloc(constructor.parameter_count, sizeof(*constructor.parameter_types));
                    constructor.parameter_modifiers = calloc(constructor.parameter_count, sizeof(*constructor.parameter_modifiers));
                    if (constructor.parameter_types == NULL || constructor.parameter_modifiers == NULL)
                    {
                        set_diagnostic(diagnostic, structure->source, member->location,
                            "out of memory while collecting constructors");
                        return false;
                    }

                    for (size_t p = 0; p < constructor.parameter_count; p++)
                    {
                        const VcAstNode *parameter = member->as.method_declaration.parameters.items[p];
                        constructor.parameter_modifiers[p] = parameter->as.parameter.modifier;
                        constructor.parameter_types[p] = resolve_type(model, parameter->as.parameter.type,
                            structure->namespace_name, false);
                        if (constructor.parameter_types[p] == VC_SEM_TYPE_UNKNOWN ||
                            constructor.parameter_types[p] == VC_SEM_TYPE_VOID)
                        {
                            set_diagnostic(diagnostic, structure->source, parameter->location,
                                "constructor parameter type '%s' is not supported",
                                parameter->as.parameter.type->name);
                            free(constructor.parameter_types);
                            free(constructor.parameter_modifiers);
                            return false;
                        }
                        if (vc_semantic_type_is_function_pointer(constructor.parameter_types[p]))
                        {
                            const bool generic_function_pointer =
                                type_ref_has_generic_parameter_origin(parameter->as.parameter.type);
                            if ((!allow_unsafe && !source_is_standard_library(structure->source)) ||
                                (!constructor_unsafe && !type_unsafe && !generic_function_pointer))
                            {
                                set_diagnostic(diagnostic, structure->source, parameter->location,
                                    "native function pointer constructor parameter '%s' requires an unsafe constructor or unsafe type",
                                    parameter->as.parameter.name);
                                free(constructor.parameter_types);
                                free(constructor.parameter_modifiers);
                                return false;
                            }
                        }
                        if (vc_semantic_type_is_pointer(constructor.parameter_types[p]))
                        {
                            if ((!allow_unsafe && !source_is_standard_library(structure->source)) ||
                                (!constructor_unsafe && !type_unsafe))
                            {
                                set_diagnostic(diagnostic, structure->source, parameter->location,
                                    "pointer constructor parameter '%s' requires an unsafe constructor or unsafe type",
                                    parameter->as.parameter.name);
                                free(constructor.parameter_types);
                                free(constructor.parameter_modifiers);
                                return false;
                            }
                            const VcAstNodeList *owner_constraints =
                                structure->node != NULL && structure->node->kind == VC_AST_TYPE_DECLARATION
                                    ? &structure->node->as.type_declaration.generic_constraints : NULL;
                            const char *missing_parameter = NULL;
                            if (!generic_type_ref_has_required_unmanaged_constraints(
                                    parameter->as.parameter.type, owner_constraints, NULL,
                                    &missing_parameter))
                            {
                                set_diagnostic(diagnostic, structure->source, parameter->location,
                                    "generic pointer constructor parameter '%s' using '%s' requires 'where %s : unmanaged'",
                                    parameter->as.parameter.name,
                                    missing_parameter != NULL ? missing_parameter : "<generic>",
                                    missing_parameter != NULL ? missing_parameter : "T");
                                free(constructor.parameter_types);
                                free(constructor.parameter_modifiers);
                                return false;
                            }
                            if (!pointer_type_ref_element_supported(model,
                                    constructor.parameter_types[p], parameter->as.parameter.type))
                            {
                                set_diagnostic(diagnostic, structure->source, parameter->location,
                                    "pointer constructor parameter type is not supported");
                                free(constructor.parameter_types);
                                free(constructor.parameter_modifiers);
                                return false;
                            }
                        }
                    }
                }

                if (!push_constructor(model, constructor))
                {
                    free(constructor.parameter_types);
                    free(constructor.parameter_modifiers);
                    set_diagnostic(diagnostic, structure->source, member->location,
                        "out of memory while collecting constructors");
                    return false;
                }
            }
        }

        if (!structure->is_class && !configure_swizzle_struct(structure, diagnostic))
            return false;
    }
    return true;
}

static bool is_static_method(const VcAstNode *node)
{
    return node != NULL && node->kind == VC_AST_METHOD_DECLARATION &&
        !node->as.method_declaration.is_constructor &&
        (node->as.method_declaration.modifiers & VC_AST_MOD_STATIC) != 0;
}

static bool native_struct_abi_supported(const VcSemanticModel *model, size_t struct_index)
{
    if (model == NULL || struct_index >= model->struct_count)
        return false;

    const VcSemanticStruct *structure = &model->structs[struct_index];
    if (structure->is_class || structure->is_interface || structure->is_delegate ||
        structure->field_count == 0 || structure->property_count != 0)
        return false;

    for (size_t i = 0; i < structure->field_count; i++)
    {
        const VcSemanticType type = structure->fields[i].type;
        if (vc_semantic_type_is_pointer(type))
            continue;

        switch (type)
        {
            case VC_SEM_TYPE_BOOL:
            case VC_SEM_TYPE_BYTE:
            case VC_SEM_TYPE_SBYTE:
            case VC_SEM_TYPE_SHORT:
            case VC_SEM_TYPE_USHORT:
            case VC_SEM_TYPE_INT:
            case VC_SEM_TYPE_UINT:
            case VC_SEM_TYPE_LONG:
            case VC_SEM_TYPE_ULONG:
            case VC_SEM_TYPE_FLOAT:
            case VC_SEM_TYPE_DOUBLE:
            case VC_SEM_TYPE_DECIMAL:
            case VC_SEM_TYPE_CHAR:
            case VC_SEM_TYPE_STRING:
                break;
            default:
                return false;
        }
    }
    return true;
}

static bool extern_abi_type_supported(
    const VcSemanticModel *model,
    VcSemanticType type,
    bool allow_void)
{
    if (vc_semantic_type_is_pointer(type))
        return true;

    if (vc_semantic_type_is_struct(type))
        return native_struct_abi_supported(model, vc_semantic_struct_index(type));

    switch (type)
    {
        case VC_SEM_TYPE_VOID: return allow_void;
        case VC_SEM_TYPE_BOOL:
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
        case VC_SEM_TYPE_STRING:
            return true;
        default:
            return false;
    }
}

static bool native_function_pointer_abi_supported(
    const VcSemanticModel *model, VcSemanticType type)
{
    if (!vc_semantic_type_is_function_pointer(type))
        return false;
    const size_t index = vc_semantic_function_pointer_index(type);
    if (model == NULL || index >= model->function_pointer_count)
        return false;
    const VcSemanticFunctionPointer *function_pointer = &model->function_pointers[index];
    if (function_pointer->return_type == VC_SEM_TYPE_STRING ||
        !extern_abi_type_supported(model, function_pointer->return_type, true) ||
        vc_semantic_type_is_function_pointer(function_pointer->return_type))
        return false;
    for (size_t i = 0; i < function_pointer->parameter_count; i++)
    {
        if (function_pointer->parameter_types[i] == VC_SEM_TYPE_STRING ||
            !extern_abi_type_supported(model, function_pointer->parameter_types[i], false) ||
            vc_semantic_type_is_function_pointer(function_pointer->parameter_types[i]))
            return false;
    }
    return true;
}

static bool validate_function_pointer_member_types(
    const VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    for (size_t struct_index = 0; struct_index < model->struct_count; struct_index++)
    {
        const VcSemanticStruct *structure = &model->structs[struct_index];
        for (size_t field_index = 0; field_index < structure->field_count; field_index++)
        {
            const VcSemanticField *field = &structure->fields[field_index];
            if (!vc_semantic_type_is_function_pointer(field->type))
                continue;
            if (!native_function_pointer_abi_supported(model, field->type))
            {
                set_diagnostic(diagnostic, structure->source, field->node->location,
                    "native function pointer field '%s' has a signature that is not supported by the C ABI",
                    field->node->as.field_declaration.name);
                return false;
            }
        }
        for (size_t property_index = 0; property_index < structure->property_count; property_index++)
        {
            const VcSemanticProperty *property = &structure->properties[property_index];
            if (!vc_semantic_type_is_function_pointer(property->type))
                continue;
            if (!native_function_pointer_abi_supported(model, property->type))
            {
                set_diagnostic(diagnostic, structure->source, property->node->location,
                    "native function pointer property '%s' has a signature that is not supported by the C ABI",
                    property->node->as.property_declaration.name);
                return false;
            }
        }
    }
    for (size_t constructor_index = 0; constructor_index < model->constructor_count; constructor_index++)
    {
        const VcSemanticConstructor *constructor = &model->constructors[constructor_index];
        const VcSemanticStruct *structure = &model->structs[constructor->struct_index];
        for (size_t p = 0; p < constructor->parameter_count; p++)
        {
            if (!vc_semantic_type_is_function_pointer(constructor->parameter_types[p]))
                continue;
            const VcAstNode *parameter = constructor->node->as.method_declaration.parameters.items[p];
            if (!native_function_pointer_abi_supported(model, constructor->parameter_types[p]))
            {
                set_diagnostic(diagnostic, structure->source, parameter->location,
                    "native function pointer constructor parameter '%s' has a signature that is not supported by the C ABI",
                    parameter->as.parameter.name);
                return false;
            }
        }
    }
    return true;
}

static bool native_callback_abi_supported(
    const VcSemanticModel *model,
    VcSemanticType type)
{
    if (!semantic_type_is_delegate(model, type))
        return false;

    const size_t delegate_index = vc_semantic_struct_index(type);
    if (delegate_index >= model->struct_count)
        return false;
    const VcSemanticStruct *delegate_type = &model->structs[delegate_index];
    if (delegate_type->delegate_invoke_method_index >= model->method_count)
        return false;

    const VcSemanticMethod *invoke = &model->methods[delegate_type->delegate_invoke_method_index];
    if (invoke->return_type == VC_SEM_TYPE_STRING ||
        semantic_type_is_delegate(model, invoke->return_type) ||
        !extern_abi_type_supported(model, invoke->return_type, true))
        return false;

    for (size_t i = 0; i < invoke->parameter_count; i++)
    {
        const VcTokenKind modifier = invoke->parameter_modifiers[i];
        if (invoke->parameter_types[i] == VC_SEM_TYPE_STRING)
        {
            const VcNativeStringContract contract = invoke->native_string_parameter_contracts != NULL
                ? invoke->native_string_parameter_contracts[i]
                : VC_NATIVE_STRING_CONTRACT_NONE;
            if (modifier != VC_TOKEN_EOF ||
                (contract != VC_NATIVE_STRING_CONTRACT_BORROWED_NUL &&
                    contract != VC_NATIVE_STRING_CONTRACT_BORROWED_POINTER_LENGTH))
                return false;
            continue;
        }
        if ((modifier != VC_TOKEN_EOF && modifier != VC_TOKEN_KW_REF &&
                modifier != VC_TOKEN_KW_OUT && modifier != VC_TOKEN_KW_IN) ||
            semantic_type_is_delegate(model, invoke->parameter_types[i]) ||
            !extern_abi_type_supported(model, invoke->parameter_types[i], false))
            return false;
    }
    return true;
}

static bool pointer_element_type_supported(const VcSemanticModel *model, VcSemanticType type)
{
    if (vc_semantic_type_is_pointer(type))
        return pointer_element_type_supported(model, vc_semantic_pointer_element_type(model, type));

    if (vc_semantic_type_is_function_pointer(type))
        return native_function_pointer_abi_supported(model, type);

    if (vc_semantic_type_is_struct(type))
        return vc_semantic_type_is_unmanaged(model, type);

    switch (type)
    {
        case VC_SEM_TYPE_VOID:
        case VC_SEM_TYPE_BOOL:
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
            return true;
        default:
            return false;
    }
}

static bool pointer_type_ref_element_supported(
    const VcSemanticModel *model,
    VcSemanticType pointer_type,
    const VcAstTypeRef *type_ref)
{
    if (!vc_semantic_type_is_pointer(pointer_type))
        return false;
    const VcSemanticType element_type = vc_semantic_pointer_element_type(model, pointer_type);
    if (type_ref_has_generic_parameter_origin(type_ref))
        return vc_semantic_type_is_unmanaged(model, element_type);
    return pointer_element_type_supported(model, element_type);
}

static bool native_span_abi_type_supported(
    const VcSemanticModel *model,
    VcSemanticType type,
    bool *readonly_span,
    VcSemanticType *element_type)
{
    bool local_readonly = false;
    VcSemanticType local_element = VC_SEM_TYPE_ERROR;
    if (!vc_semantic_span_type_info(model, type, &local_readonly, &local_element))
        return false;
    if (!vc_semantic_type_is_unmanaged(model, local_element) ||
        !pointer_element_type_supported(model, local_element))
        return false;
    if (readonly_span != NULL)
        *readonly_span = local_readonly;
    if (element_type != NULL)
        *element_type = local_element;
    return true;
}

static bool sizeof_type_supported(const VcSemanticModel *model, VcSemanticType type)
{
    if (vc_semantic_type_is_pointer(type) || vc_semantic_type_is_function_pointer(type))
        return true;
    if (vc_semantic_type_is_struct(type))
        return native_struct_abi_supported(model, vc_semantic_struct_index(type));

    switch (type)
    {
        case VC_SEM_TYPE_BOOL:
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
            return true;
        default:
            return false;
    }
}

static bool native_symbol_name_valid(const char *name)
{
    if (name == NULL || name[0] == '\0')
        return false;

    const char first = name[0];
    if (!((first >= 'A' && first <= 'Z') ||
          (first >= 'a' && first <= 'z') || first == '_'))
        return false;

    for (size_t i = 1; name[i] != '\0'; i++)
    {
        const char ch = name[i];
        if (!((ch >= 'A' && ch <= 'Z') ||
              (ch >= 'a' && ch <= 'z') ||
              (ch >= '0' && ch <= '9') || ch == '_'))
            return false;
    }
    return true;
}

static const VcAstNode *find_named_attribute(const VcAstNodeList *attributes, const char *name)
{
    if (attributes == NULL || name == NULL)
        return NULL;
    for (size_t i = 0; i < attributes->count; i++)
    {
        const VcAstNode *attribute = attributes->items[i];
        if (attribute != NULL && attribute->kind == VC_AST_ATTRIBUTE &&
            attribute->as.attribute.name != NULL &&
            strcmp(attribute->as.attribute.name, name) == 0)
            return attribute;
    }
    return NULL;
}

static const VcAstNode *find_native_string_contract_attribute(const VcAstNode *method)
{
    if (method == NULL || method->kind != VC_AST_METHOD_DECLARATION)
        return NULL;
    const VcAstNode *attribute = find_named_attribute(&method->attributes, "NativeString");
    if (attribute != NULL)
        return attribute;
    for (size_t i = 0; i < method->as.method_declaration.parameters.count; i++)
    {
        const VcAstNode *parameter = method->as.method_declaration.parameters.items[i];
        attribute = find_named_attribute(&parameter->attributes, "NativeString");
        if (attribute != NULL)
            return attribute;
    }
    return NULL;
}

static bool native_string_kind_target(const VcAstNode *expression)
{
    if (expression == NULL)
        return false;
    if (expression->kind == VC_AST_IDENTIFIER_EXPRESSION)
        return expression->as.identifier_expression.name != NULL &&
            strcmp(expression->as.identifier_expression.name, "NativeStringKind") == 0;
    if (expression->kind != VC_AST_MEMBER_ACCESS_EXPRESSION ||
        expression->as.member_access_expression.member == NULL ||
        strcmp(expression->as.member_access_expression.member, "NativeStringKind") != 0)
        return false;
    const VcAstNode *target = expression->as.member_access_expression.target;
    return target != NULL && target->kind == VC_AST_IDENTIFIER_EXPRESSION &&
        target->as.identifier_expression.name != NULL &&
        strcmp(target->as.identifier_expression.name, "Void") == 0;
}

static bool parse_native_string_contract(
    const VcAstNode *attribute,
    bool return_contract,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    VcNativeStringContract *output,
    char *release_output,
    size_t release_output_size)
{
    if (attribute == NULL || output == NULL)
        return false;
    if (attribute->as.attribute.arguments.count > 2)
    {
        set_diagnostic(diagnostic, source, attribute->location,
            "[NativeString] accepts a NativeStringKind and optional native release symbol");
        return false;
    }

    VcNativeStringContract contract = VC_NATIVE_STRING_CONTRACT_BORROWED_NUL;
    const VcAstNode *argument = NULL;
    if (attribute->as.attribute.arguments.count >= 1)
    {
        argument = attribute->as.attribute.arguments.items[0];
        if (argument == NULL || argument->kind != VC_AST_MEMBER_ACCESS_EXPRESSION ||
            !native_string_kind_target(argument->as.member_access_expression.target) ||
            argument->as.member_access_expression.member == NULL)
        {
            set_diagnostic(diagnostic, source,
                argument != NULL ? argument->location : attribute->location,
                "[NativeString] contract must be a NativeStringKind value");
            return false;
        }

        const char *member = argument->as.member_access_expression.member;
        if (strcmp(member, "BorrowedNul") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_BORROWED_NUL;
        else if (strcmp(member, "BorrowedPointerLength") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_BORROWED_POINTER_LENGTH;
        else if (strcmp(member, "RetainedNul") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_RETAINED_NUL;
        else if (strcmp(member, "RetainedPointerLength") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_RETAINED_POINTER_LENGTH;
        else if (strcmp(member, "StaticNul") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_STATIC_NUL;
        else if (strcmp(member, "StaticPointerLength") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_STATIC_POINTER_LENGTH;
        else if (strcmp(member, "OwnedNul") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_OWNED_NUL;
        else if (strcmp(member, "OwnedPointerLength") == 0)
            contract = VC_NATIVE_STRING_CONTRACT_OWNED_POINTER_LENGTH;
        else
        {
            set_diagnostic(diagnostic, source, argument->location,
                "[NativeString] NativeStringKind member is not recognized");
            return false;
        }
    }

    const bool owned_contract = contract == VC_NATIVE_STRING_CONTRACT_OWNED_NUL ||
        contract == VC_NATIVE_STRING_CONTRACT_OWNED_POINTER_LENGTH;
    const VcAstNode *release_argument = attribute->as.attribute.arguments.count == 2
        ? attribute->as.attribute.arguments.items[1]
        : NULL;
    if (owned_contract && return_contract)
    {
        if (release_argument == NULL)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[NativeString] owned return contracts require a native release symbol");
            return false;
        }
        if (release_output == NULL || release_output_size == 0u ||
            release_argument->kind != VC_AST_LITERAL_EXPRESSION ||
            release_argument->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
        {
            set_diagnostic(diagnostic, source, release_argument->location,
                "[NativeString] native release symbol must be a string literal");
            return false;
        }
        const char *text = release_argument->as.literal_expression.text;
        const size_t length = text != NULL ? strlen(text) : 0u;
        if (length < 3u || text[0] != '"' || text[length - 1u] != '"' ||
            length - 2u >= release_output_size)
        {
            set_diagnostic(diagnostic, source, release_argument->location,
                "[NativeString] native release symbol is empty or too long");
            return false;
        }
        memcpy(release_output, text + 1u, length - 2u);
        release_output[length - 2u] = '\0';
        if (!native_symbol_name_valid(release_output))
        {
            set_diagnostic(diagnostic, source, release_argument->location,
                "[NativeString] native release symbol '%s' is not a valid C identifier",
                release_output);
            return false;
        }
    }
    else if (release_argument != NULL)
    {
        set_diagnostic(diagnostic, source, release_argument->location,
            "[NativeString] native release symbol is valid only for owned return contracts");
        return false;
    }

    const VcSourceLocation contract_location = argument != NULL ? argument->location : attribute->location;
    if (return_contract)
    {
        if (contract == VC_NATIVE_STRING_CONTRACT_RETAINED_NUL ||
            contract == VC_NATIVE_STRING_CONTRACT_RETAINED_POINTER_LENGTH)
        {
            set_diagnostic(diagnostic, source, contract_location,
                "[NativeString] retained contracts are valid only on parameters");
            return false;
        }
    }
    else if (contract == VC_NATIVE_STRING_CONTRACT_STATIC_NUL ||
        contract == VC_NATIVE_STRING_CONTRACT_STATIC_POINTER_LENGTH ||
        contract == VC_NATIVE_STRING_CONTRACT_OWNED_NUL ||
        contract == VC_NATIVE_STRING_CONTRACT_OWNED_POINTER_LENGTH)
    {
        set_diagnostic(diagnostic, source, contract_location,
            "[NativeString] static and owned contracts are valid only on returns");
        return false;
    }

    *output = contract;
    return true;
}

static bool resolve_native_string_contracts(
    const VcAstNode *method_node,
    bool is_extern,
    bool is_delegate_invoke,
    VcSemanticType return_type,
    const VcSemanticType *parameter_types,
    const VcTokenKind *parameter_modifiers,
    size_t parameter_count,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    VcNativeStringContract *return_contract,
    VcNativeStringContract *parameter_contracts,
    char *release_output,
    size_t release_output_size)
{
    if (method_node == NULL || return_contract == NULL)
        return false;

    const VcAstNode *method_attribute = find_named_attribute(&method_node->attributes, "NativeString");
    size_t method_attribute_count = 0;
    for (size_t i = 0; i < method_node->attributes.count; i++)
    {
        const VcAstNode *attribute = method_node->attributes.items[i];
        if (attribute != NULL && attribute->kind == VC_AST_ATTRIBUTE &&
            attribute->as.attribute.name != NULL &&
            strcmp(attribute->as.attribute.name, "NativeString") == 0)
            method_attribute_count++;
    }
    if (method_attribute_count > 1)
    {
        set_diagnostic(diagnostic, source,
            method_attribute != NULL ? method_attribute->location : method_node->location,
            "[NativeString] may appear only once on a method return");
        return false;
    }
    if (method_attribute != NULL)
    {
        if (!is_extern)
        {
            set_diagnostic(diagnostic, source, method_attribute->location,
                "[NativeString] return contracts may be used only on extern methods");
            return false;
        }
        if (return_type != VC_SEM_TYPE_STRING)
        {
            set_diagnostic(diagnostic, source, method_attribute->location,
                "[NativeString] method contract requires a string return type");
            return false;
        }
        if (!parse_native_string_contract(method_attribute, true, source, diagnostic, return_contract,
                release_output, release_output_size))
            return false;
    }

    for (size_t parameter_index = 0; parameter_index < parameter_count; parameter_index++)
    {
        const VcAstNode *parameter = method_node->as.method_declaration.parameters.items[parameter_index];
        const VcAstNode *attribute = find_named_attribute(&parameter->attributes, "NativeString");
        size_t count = 0;
        for (size_t i = 0; i < parameter->attributes.count; i++)
        {
            const VcAstNode *candidate = parameter->attributes.items[i];
            if (candidate != NULL && candidate->kind == VC_AST_ATTRIBUTE &&
                candidate->as.attribute.name != NULL &&
                strcmp(candidate->as.attribute.name, "NativeString") == 0)
                count++;
        }
        if (count > 1)
        {
            set_diagnostic(diagnostic, source,
                attribute != NULL ? attribute->location : parameter->location,
                "[NativeString] may appear only once on a parameter");
            return false;
        }
        if (attribute == NULL)
            continue;
        if (!is_extern && !is_delegate_invoke)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[NativeString] parameter contracts may be used only on extern methods");
            return false;
        }
        if (parameter_types == NULL || parameter_types[parameter_index] != VC_SEM_TYPE_STRING)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[NativeString] parameter contract requires a string parameter");
            return false;
        }
        if (parameter_modifiers != NULL && parameter_modifiers[parameter_index] != VC_TOKEN_EOF)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[NativeString] parameter contracts require a by-value string parameter");
            return false;
        }
        if (parameter_contracts == NULL ||
            !parse_native_string_contract(attribute, false, source, diagnostic,
                &parameter_contracts[parameter_index], NULL, 0u))
            return false;
        if (is_delegate_invoke &&
            parameter_contracts[parameter_index] != VC_NATIVE_STRING_CONTRACT_BORROWED_NUL &&
            parameter_contracts[parameter_index] != VC_NATIVE_STRING_CONTRACT_BORROWED_POINTER_LENGTH)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[NativeString] native callback string parameters support only BorrowedNul and BorrowedPointerLength");
            return false;
        }
    }

    return true;
}

static bool resolve_native_symbol_name(
    const VcAstNode *method,
    bool is_extern,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    char *output,
    size_t output_size)
{
    const VcAstNode *native_attribute = NULL;
    for (size_t i = 0; i < method->attributes.count; i++)
    {
        const VcAstNode *attribute = method->attributes.items[i];
        if (attribute == NULL || attribute->kind != VC_AST_ATTRIBUTE ||
            attribute->as.attribute.name == NULL ||
            strcmp(attribute->as.attribute.name, "Native") != 0)
            continue;

        if (native_attribute != NULL)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[Native] may appear only once on a method");
            return false;
        }
        native_attribute = attribute;
    }

    if (native_attribute == NULL)
        return true;

    if (!is_extern)
    {
        set_diagnostic(diagnostic, source, native_attribute->location,
            "[Native] may be used only on extern methods");
        return false;
    }

    if (native_attribute->as.attribute.arguments.count != 1)
    {
        set_diagnostic(diagnostic, source, native_attribute->location,
            "[Native] requires exactly one C symbol string");
        return false;
    }

    const VcAstNode *argument = native_attribute->as.attribute.arguments.items[0];
    if (argument == NULL || argument->kind != VC_AST_LITERAL_EXPRESSION ||
        argument->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
    {
        set_diagnostic(diagnostic, source, native_attribute->location,
            "[Native] symbol must be a string literal");
        return false;
    }

    const char *text = argument->as.literal_expression.text;
    const size_t length = text != NULL ? strlen(text) : 0;
    if (length < 3 || text[0] != '"' || text[length - 1] != '"' || length - 2 >= output_size)
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[Native] symbol is empty or too long");
        return false;
    }

    memcpy(output, text + 1, length - 2);
    output[length - 2] = '\0';
    if (!native_symbol_name_valid(output))
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[Native] symbol '%s' is not a valid C identifier", output);
        return false;
    }
    return true;
}

static const VcAstNode *find_method_attribute(const VcAstNode *method, const char *name)
{
    if (method == NULL || name == NULL)
        return NULL;
    for (size_t i = 0; i < method->attributes.count; i++)
    {
        const VcAstNode *attribute = method->attributes.items[i];
        if (attribute != NULL && attribute->kind == VC_AST_ATTRIBUTE &&
            attribute->as.attribute.name != NULL && strcmp(attribute->as.attribute.name, name) == 0)
            return attribute;
    }
    return NULL;
}

static bool resolve_export_symbol_name(
    const VcAstNode *method,
    bool library_output,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic,
    char *output,
    size_t output_size,
    bool *is_exported)
{
    *is_exported = false;
    const VcAstNode *export_attribute = NULL;
    for (size_t i = 0; i < method->attributes.count; i++)
    {
        const VcAstNode *attribute = method->attributes.items[i];
        if (attribute == NULL || attribute->kind != VC_AST_ATTRIBUTE ||
            attribute->as.attribute.name == NULL || strcmp(attribute->as.attribute.name, "Export") != 0)
            continue;
        if (export_attribute != NULL)
        {
            set_diagnostic(diagnostic, source, attribute->location,
                "[Export] may appear only once on a method");
            return false;
        }
        export_attribute = attribute;
    }

    if (export_attribute == NULL)
        return true;
    if (!library_output)
    {
        set_diagnostic(diagnostic, source, export_attribute->location,
            "[Export] may be used only in a library project");
        return false;
    }
    if (export_attribute->as.attribute.arguments.count != 1)
    {
        set_diagnostic(diagnostic, source, export_attribute->location,
            "[Export] requires exactly one C symbol string");
        return false;
    }

    const VcAstNode *argument = export_attribute->as.attribute.arguments.items[0];
    if (argument == NULL || argument->kind != VC_AST_LITERAL_EXPRESSION ||
        argument->as.literal_expression.literal_kind != VC_AST_LITERAL_STRING)
    {
        set_diagnostic(diagnostic, source, export_attribute->location,
            "[Export] symbol must be a string literal");
        return false;
    }

    const char *text = argument->as.literal_expression.text;
    const size_t length = text != NULL ? strlen(text) : 0;
    if (length < 3 || text[0] != '"' || text[length - 1] != '"' || length - 2 >= output_size)
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[Export] symbol is empty or too long");
        return false;
    }
    memcpy(output, text + 1, length - 2);
    output[length - 2] = '\0';
    if (!native_symbol_name_valid(output))
    {
        set_diagnostic(diagnostic, source, argument->location,
            "[Export] symbol '%s' is not a valid C identifier", output);
        return false;
    }
    *is_exported = true;
    return true;
}

static bool is_conversion_operator_kind(VcTokenKind kind);
static bool is_integral(VcSemanticType type);
static bool is_numeric(VcSemanticType type);

static bool is_unary_operator_kind(VcTokenKind kind)
{
    switch (kind)
    {
        case VC_TOKEN_PLUS:
        case VC_TOKEN_MINUS:
        case VC_TOKEN_BANG:
        case VC_TOKEN_TILDE:
        case VC_TOKEN_PLUS_PLUS:
        case VC_TOKEN_MINUS_MINUS:
            return true;
        default:
            return false;
    }
}
static bool is_standard_assignable(const VcSemanticModel *model, VcSemanticType target, VcSemanticType source);

static bool validate_extension_method_declaration(
    const VcAstNode *owner,
    const VcAstNode *method,
    const VcSource *source,
    VcSemanticDiagnostic *diagnostic)
{
    if (owner == NULL || method == NULL || method->kind != VC_AST_METHOD_DECLARATION ||
        method->as.method_declaration.parameters.count == 0 ||
        !method->as.method_declaration.parameters.items[0]->as.parameter.extension_receiver)
        return true;

    if (method->as.method_declaration.is_constructor)
    {
        set_diagnostic(diagnostic, source, method->location,
            "constructor parameters cannot use the extension receiver modifier 'this'");
        return false;
    }
    if (owner->as.type_declaration.generic_parameters.count != 0)
    {
        set_diagnostic(diagnostic, source, method->location,
            "extension methods cannot be declared in a generic containing type");
        return false;
    }
    if (owner->as.type_declaration.type_kind != VC_AST_TYPE_CLASS ||
        (owner->as.type_declaration.modifiers & VC_AST_MOD_STATIC) == 0)
    {
        set_diagnostic(diagnostic, source, method->location,
            "extension method '%s' must be declared in a static class",
            method->as.method_declaration.name);
        return false;
    }
    if ((method->as.method_declaration.modifiers & VC_AST_MOD_STATIC) == 0)
    {
        set_diagnostic(diagnostic, source, method->location,
            "extension method '%s' must be static",
            method->as.method_declaration.name);
        return false;
    }

    const VcAstNode *receiver = method->as.method_declaration.parameters.items[0];
    if (receiver->as.parameter.modifier == VC_TOKEN_KW_OUT ||
        receiver->as.parameter.modifier == VC_TOKEN_KW_PARAMS)
    {
        set_diagnostic(diagnostic, source, receiver->location,
            "extension receiver cannot use '%s'",
            vc_token_kind_name(receiver->as.parameter.modifier));
        return false;
    }
    if (receiver->as.parameter.default_value != NULL)
    {
        set_diagnostic(diagnostic, source, receiver->location,
            "extension receiver cannot have a default value");
        return false;
    }
    return true;
}

static bool collect_methods(
    const VcAstNodeList *declarations,
    const VcSource *source,
    const char *namespace_name,
    bool allow_unsafe,
    bool library_output,
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t i = 0; i < declarations->count; i++)
    {
        const VcAstNode *declaration = declarations->items[i];
        if (declaration->kind == VC_AST_NAMESPACE_DECLARATION)
        {
            if (!collect_methods(&declaration->as.namespace_declaration.declarations, source,
                    declaration->as.namespace_declaration.name, allow_unsafe, library_output, model, diagnostic))
                return false;
            continue;
        }
        if (declaration->kind != VC_AST_TYPE_DECLARATION)
            continue;
        if (declaration->as.type_declaration.generic_parameters.count != 0)
        {
            for (size_t member_index = 0; member_index < declaration->as.type_declaration.members.count; member_index++)
            {
                const VcAstNode *member = declaration->as.type_declaration.members.items[member_index];
                if (member->kind == VC_AST_METHOD_DECLARATION &&
                    !validate_extension_method_declaration(declaration, member, source, diagnostic))
                    return false;
            }
            continue;
        }

        size_t owner_struct_index = 0;
        bool has_owner_struct = false;
        if (declaration->as.type_declaration.type_kind == VC_AST_TYPE_STRUCT ||
            declaration->as.type_declaration.type_kind == VC_AST_TYPE_CLASS ||
            declaration->as.type_declaration.type_kind == VC_AST_TYPE_INTERFACE ||
            declaration->as.type_declaration.type_kind == VC_AST_TYPE_DELEGATE)
        {
            bool ambiguous = false;
            has_owner_struct = find_struct_by_name(model, namespace_name,
                declaration->as.type_declaration.name, &owner_struct_index, &ambiguous);
            if (!has_owner_struct || ambiguous)
            {
                set_diagnostic(diagnostic, source, declaration->location,
                    "could not resolve type '%s' while collecting methods",
                    declaration->as.type_declaration.name);
                return false;
            }
        }

        for (size_t member_index = 0; member_index < declaration->as.type_declaration.members.count; member_index++)
        {
            const VcAstNode *member = declaration->as.type_declaration.members.items[member_index];
            if (member->kind != VC_AST_METHOD_DECLARATION)
                continue;

            if (!validate_extension_method_declaration(declaration, member, source, diagnostic))
                return false;

            if (member->as.method_declaration.is_constructor)
            {
                const VcAstNode *native_string_attribute = find_native_string_contract_attribute(member);
                if (native_string_attribute != NULL)
                {
                    set_diagnostic(diagnostic, source, native_string_attribute->location,
                        "[NativeString] contracts may be used only on non-generic extern methods");
                    return false;
                }
                if (find_method_attribute(member, "Export") != NULL)
                {
                    set_diagnostic(diagnostic, source, member->location,
                        "constructors cannot be exported as native library symbols");
                    return false;
                }
                continue;
            }

            if (member->as.method_declaration.generic_parameters.count != 0)
            {
                const VcAstNode *native_string_attribute = find_native_string_contract_attribute(member);
                if (native_string_attribute != NULL)
                {
                    set_diagnostic(diagnostic, source, native_string_attribute->location,
                        "[NativeString] contracts may be used only on non-generic extern methods");
                    return false;
                }
                if (find_method_attribute(member, "Export") != NULL)
                {
                    set_diagnostic(diagnostic, source, member->location,
                        "generic method '%s' cannot be exported directly",
                        member->as.method_declaration.name);
                    return false;
                }
                continue;
            }

            VcSemanticMethod method = {0};
            method.node = member;
            method.source = source;
            method.namespace_name = namespace_name;
            method.type_name = declaration->as.type_declaration.name;
            method.owner_struct_index = owner_struct_index;
            method.has_owner_struct = has_owner_struct;
            method.is_static = (member->as.method_declaration.modifiers & VC_AST_MOD_STATIC) != 0;
            method.is_extern = (member->as.method_declaration.modifiers & VC_AST_MOD_EXTERN) != 0;
            method.is_unsafe = (member->as.method_declaration.modifiers & VC_AST_MOD_UNSAFE) != 0;
            method.is_operator = member->as.method_declaration.is_operator;
            method.is_virtual = (member->as.method_declaration.modifiers & VC_AST_MOD_VIRTUAL) != 0;
            method.is_override = (member->as.method_declaration.modifiers & VC_AST_MOD_OVERRIDE) != 0;
            method.is_abstract = (member->as.method_declaration.modifiers & VC_AST_MOD_ABSTRACT) != 0;
            method.is_sealed = (member->as.method_declaration.modifiers & VC_AST_MOD_SEALED) != 0;
            const bool explicit_readonly =
                (member->as.method_declaration.modifiers & VC_AST_MOD_READONLY) != 0;
            method.is_readonly = explicit_readonly ||
                (has_owner_struct && !method.is_static && model->structs[owner_struct_index].is_readonly);
            method.is_async = (member->as.method_declaration.modifiers & VC_AST_MOD_ASYNC) != 0;
            method.is_interface_method = has_owner_struct &&
                model->structs[owner_struct_index].is_interface;
            method.is_delegate_invoke = has_owner_struct &&
                model->structs[owner_struct_index].is_delegate &&
                strcmp(member->as.method_declaration.name, "Invoke") == 0;
            method.is_extension_method = member->as.method_declaration.parameters.count != 0 &&
                member->as.method_declaration.parameters.items[0]->as.parameter.extension_receiver;
            method.operator_kind = member->as.method_declaration.operator_kind;
            method.return_type = resolve_type(model, member->as.method_declaration.return_type, namespace_name, true);
            method.returns_ref = member->as.method_declaration.returns_ref;
            method.returns_ref_readonly = member->as.method_declaration.returns_ref_readonly;
            method.parameter_count = member->as.method_declaration.parameters.count;
            if (method.is_extern)
                snprintf(method.c_name, sizeof(method.c_name), "%s", member->as.method_declaration.name);
            else
                snprintf(method.c_name, sizeof(method.c_name), "vc_m_%zu", model->method_count);

            if (!resolve_native_symbol_name(member, method.is_extern, source, diagnostic,
                    method.c_name, sizeof(method.c_name)))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                return false;
            }

            if (!resolve_export_symbol_name(member, library_output, source, diagnostic,
                    method.export_c_name, sizeof(method.export_c_name), &method.is_exported))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                return false;
            }

            if (method.parameter_count > 0)
            {
                method.parameter_types = calloc(method.parameter_count, sizeof(*method.parameter_types));
                method.parameter_modifiers = calloc(method.parameter_count, sizeof(*method.parameter_modifiers));
                if (method.parameter_types == NULL || method.parameter_modifiers == NULL)
                {
                    set_diagnostic(diagnostic, source, member->location, "out of memory while collecting methods");
                    return false;
                }

                for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
                {
                    const VcAstNode *parameter = member->as.method_declaration.parameters.items[parameter_index];
                    method.parameter_modifiers[parameter_index] = parameter->as.parameter.modifier;
                    method.parameter_types[parameter_index] = resolve_type(model, parameter->as.parameter.type,
                        namespace_name, false);
                }
            }

            if (method.return_type == VC_SEM_TYPE_UNKNOWN || method.return_type == VC_SEM_TYPE_ERROR)
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                set_diagnostic(diagnostic, source, member->location,
                    "method return type is not supported");
                return false;
            }

            if (method.returns_ref)
            {
                if (method.return_type == VC_SEM_TYPE_VOID)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "ref-returning method '%s' cannot return void",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_async)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "ref-returning method '%s' cannot be async",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_extern || method.is_exported)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "ref-returning method '%s' cannot use the native extern/export ABI",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_operator)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overloads cannot return by ref");
                    return false;
                }
            }

            if (explicit_readonly)
            {
                if (!has_owner_struct || method.is_static || model->structs[owner_struct_index].is_class ||
                    model->structs[owner_struct_index].is_interface || model->structs[owner_struct_index].is_enum ||
                    model->structs[owner_struct_index].is_delegate)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "readonly method '%s' requires an instance value struct",
                        member->as.method_declaration.name);
                    return false;
                }
            }
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                if (method.parameter_types[parameter_index] == VC_SEM_TYPE_UNKNOWN ||
                    method.parameter_types[parameter_index] == VC_SEM_TYPE_VOID)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source,
                        member->as.method_declaration.parameters.items[parameter_index]->location,
                        "method parameter type is not supported");
                    return false;
                }
            }

            if (method.is_async)
            {
                if (method.is_extern)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "async method '%s' cannot be extern",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_operator)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overloads cannot be async");
                    return false;
                }
                if (method.is_exported)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "async method '%s' cannot be exported as a native library symbol",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_abstract)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "async method '%s' cannot be abstract",
                        member->as.method_declaration.name);
                    return false;
                }
                if (member->as.method_declaration.body == NULL)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "async method '%s' requires a body",
                        member->as.method_declaration.name);
                    return false;
                }

                const bool has_yield = semantic_node_contains_yield(
                    member->as.method_declaration.body);
                if (has_yield)
                {
                    VcSemanticType async_iterator_item = VC_SEM_TYPE_UNKNOWN;
                    if (!semantic_async_enumerable_type_info(model, method.return_type,
                            &async_iterator_item))
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "async iterator method '%s' must return IAsyncEnumerable<T>",
                            member->as.method_declaration.name);
                        return false;
                    }
                    method.async_result_type = async_iterator_item;
                }
                else
                {
                    bool has_async_result = false;
                    method.async_returns_value_task = false;
                    const bool returns_task = semantic_task_type_info(model, method.return_type,
                        &method.async_result_type, &has_async_result);
                    if (!returns_task && !semantic_value_task_type_info(model, method.return_type,
                            &method.async_result_type, &has_async_result))
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "async method '%s' must return Task or Task<T>, got '%s'",
                            member->as.method_declaration.name,
                            context_type_display_name(&diagnostic_display_context, method.return_type));
                        return false;
                    }
                    method.async_returns_value_task = !returns_task;
                    (void)has_async_result;
                }

                for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
                {
                    const VcTokenKind modifier = method.parameter_modifiers[parameter_index];
                    if (modifier == VC_TOKEN_KW_REF || modifier == VC_TOKEN_KW_OUT ||
                        modifier == VC_TOKEN_KW_IN)
                    {
                        const VcAstNode *parameter =
                            member->as.method_declaration.parameters.items[parameter_index];
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, parameter->location,
                            "async method '%s' cannot declare %s parameter '%s'",
                            member->as.method_declaration.name,
                            vc_token_kind_name(modifier), parameter->as.parameter.name);
                        return false;
                    }
                }
            }

            bool has_pointer_signature = vc_semantic_type_is_pointer(method.return_type);
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                if (vc_semantic_type_is_pointer(method.parameter_types[parameter_index]))
                {
                    has_pointer_signature = true;
                    break;
                }
            }
            if (has_pointer_signature &&
                ((!allow_unsafe && !source_is_standard_library(source)) || !method.is_unsafe))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                set_diagnostic(diagnostic, source, member->location,
                    "pointer signatures require an unsafe method in an unsafe-enabled project");
                return false;
            }

            const VcAstNodeList *owner_constraints = NULL;
            if (method.has_owner_struct && method.owner_struct_index < model->struct_count &&
                model->structs[method.owner_struct_index].node != NULL &&
                model->structs[method.owner_struct_index].node->kind == VC_AST_TYPE_DECLARATION)
                owner_constraints = &model->structs[method.owner_struct_index].node
                    ->as.type_declaration.generic_constraints;
            const VcAstNode *generic_template =
                find_original_generic_method_template(model, &method);
            const VcAstNodeList *method_constraints =
                &member->as.method_declaration.generic_constraints;
            if (method_constraints->count == 0 && generic_template != NULL)
                method_constraints = &generic_template->as.method_declaration.generic_constraints;

            bool has_function_pointer_signature =
                vc_semantic_type_is_function_pointer(method.return_type) &&
                !type_ref_has_generic_parameter_origin(member->as.method_declaration.return_type);
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                const VcAstNode *parameter =
                    member->as.method_declaration.parameters.items[parameter_index];
                if (vc_semantic_type_is_function_pointer(method.parameter_types[parameter_index]) &&
                    !type_ref_has_generic_parameter_origin(parameter->as.parameter.type))
                {
                    has_function_pointer_signature = true;
                    break;
                }
            }
            if (has_function_pointer_signature &&
                ((!allow_unsafe && !source_is_standard_library(source)) || !method.is_unsafe))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                set_diagnostic(diagnostic, source, member->location,
                    "native function pointer signatures require an unsafe method in an unsafe-enabled project");
                return false;
            }
            if (vc_semantic_type_is_function_pointer(method.return_type))
            {
                if (!native_function_pointer_abi_supported(model, method.return_type))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "native function pointer return signature is not supported by the C ABI");
                    return false;
                }
            }
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                if (!vc_semantic_type_is_function_pointer(method.parameter_types[parameter_index]))
                    continue;
                const VcAstNode *parameter =
                    member->as.method_declaration.parameters.items[parameter_index];
                if (!native_function_pointer_abi_supported(model, method.parameter_types[parameter_index]))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, parameter->location,
                        "native function pointer parameter signature is not supported by the C ABI");
                    return false;
                }
            }

            if (vc_semantic_type_is_pointer(method.return_type))
            {
                const char *missing_parameter = NULL;
                if (!generic_type_ref_has_required_unmanaged_constraints(
                        member->as.method_declaration.return_type,
                        method_constraints, owner_constraints, &missing_parameter))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "generic pointer return type using '%s' requires 'where %s : unmanaged'",
                        missing_parameter != NULL ? missing_parameter : "<generic>",
                        missing_parameter != NULL ? missing_parameter : "T");
                    return false;
                }
            }
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                if (!vc_semantic_type_is_pointer(method.parameter_types[parameter_index]))
                    continue;
                const VcAstNode *parameter =
                    member->as.method_declaration.parameters.items[parameter_index];
                const char *missing_parameter = NULL;
                if (!generic_type_ref_has_required_unmanaged_constraints(
                        parameter->as.parameter.type,
                        method_constraints, owner_constraints, &missing_parameter))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, parameter->location,
                        "generic pointer parameter '%s' using '%s' requires 'where %s : unmanaged'",
                        parameter->as.parameter.name,
                        missing_parameter != NULL ? missing_parameter : "<generic>",
                        missing_parameter != NULL ? missing_parameter : "T");
                    return false;
                }
            }

            if (vc_semantic_type_is_pointer(method.return_type) &&
                !pointer_type_ref_element_supported(model, method.return_type,
                    member->as.method_declaration.return_type))
            {
                const VcAstTypeRef *return_type_ref =
                    member->as.method_declaration.return_type;
                const bool constrained_generic_pointer =
                    type_ref_has_generic_parameter_origin(return_type_ref) &&
                    generic_type_ref_has_required_unmanaged_constraints(
                        return_type_ref, method_constraints, owner_constraints, NULL);
                if (!constrained_generic_pointer)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "pointer return type is not supported");
                    return false;
                }
            }
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                if (vc_semantic_type_is_pointer(method.parameter_types[parameter_index]) &&
                    !pointer_type_ref_element_supported(model,
                        method.parameter_types[parameter_index],
                        member->as.method_declaration.parameters.items[parameter_index]->as.parameter.type))
                {
                    const VcAstTypeRef *parameter_type_ref =
                        member->as.method_declaration.parameters.items[parameter_index]
                            ->as.parameter.type;
                    const bool constrained_generic_pointer =
                        type_ref_has_generic_parameter_origin(parameter_type_ref) &&
                        generic_type_ref_has_required_unmanaged_constraints(
                            parameter_type_ref, method_constraints, owner_constraints, NULL);
                    if (!constrained_generic_pointer)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "pointer parameter type is not supported");
                        return false;
                    }
                }
            }

            if (method.is_extern)
            {
                if (!allow_unsafe && !source_is_standard_library(source))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' requires compiler unsafe to be enabled",
                        member->as.method_declaration.name);
                    return false;
                }
                if (!method.is_unsafe)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' must be declared unsafe",
                        member->as.method_declaration.name);
                    return false;
                }
                if (!method.is_static)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' must be static",
                        member->as.method_declaration.name);
                    return false;
                }
                if (member->as.method_declaration.body != NULL)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' must end in ';'",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_operator || method.is_virtual || method.is_override || method.is_abstract || method.is_sealed)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' cannot be operator, virtual, override, abstract, or sealed",
                        member->as.method_declaration.name);
                    return false;
                }
                if (vc_semantic_type_is_function_pointer(method.return_type))
                {
                    if (!native_function_pointer_abi_supported(model, method.return_type))
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "extern method '%s' has a native function pointer return type with a signature that is not supported by the C ABI",
                            member->as.method_declaration.name);
                        return false;
                    }
                }
                else if (!extern_abi_type_supported(model, method.return_type, true))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "extern method '%s' has a return type that is not supported by the C ABI",
                        member->as.method_declaration.name);
                    return false;
                }
                for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
                {
                    const VcTokenKind modifier = method.parameter_modifiers[parameter_index];
                    bool native_buffer_readonly = false;
                    VcSemanticType native_buffer_element = VC_SEM_TYPE_ERROR;
                    const bool native_buffer_parameter = vc_semantic_span_type_info(
                        model, method.parameter_types[parameter_index],
                        &native_buffer_readonly, &native_buffer_element);
                    if (modifier != VC_TOKEN_EOF && modifier != VC_TOKEN_KW_REF &&
                        modifier != VC_TOKEN_KW_OUT && modifier != VC_TOKEN_KW_IN)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "extern method parameters support only ref, out, and in modifiers");
                        return false;
                    }
                    if (method.parameter_types[parameter_index] == VC_SEM_TYPE_STRING &&
                        modifier != VC_TOKEN_EOF &&
                        find_named_attribute(&member->as.method_declaration.parameters.items[parameter_index]->attributes,
                            "NativeString") == NULL)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "extern string parameters must be passed by value; use explicit pointer or native buffer storage for writable text");
                        return false;
                    }
                    if (vc_semantic_type_is_function_pointer(method.parameter_types[parameter_index]))
                    {
                        if (modifier != VC_TOKEN_EOF)
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native function pointer extern parameters must be passed by value");
                            return false;
                        }
                        if (!native_function_pointer_abi_supported(model,
                                method.parameter_types[parameter_index]))
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native function pointer extern parameter has a signature that is not supported by the C ABI");
                            return false;
                        }
                        continue;
                    }
                    if (native_buffer_parameter)
                    {
                        if (modifier != VC_TOKEN_EOF)
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native Span parameters must be passed by value");
                            return false;
                        }
                        if (!native_span_abi_type_supported(model,
                                method.parameter_types[parameter_index], NULL, NULL))
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native Span element type '%s' must be unmanaged and supported by the C ABI",
                                context_type_display_name(&diagnostic_display_context, native_buffer_element));
                            return false;
                        }
                        (void)native_buffer_readonly;
                        continue;
                    }
                    if (semantic_type_is_delegate(model, method.parameter_types[parameter_index]))
                    {
                        if (modifier != VC_TOKEN_EOF)
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native callback delegate parameters cannot themselves use ref, out, or in");
                            return false;
                        }
                        if (!native_callback_abi_supported(model, method.parameter_types[parameter_index]))
                        {
                            free(method.parameter_types);
                            free(method.parameter_modifiers);
                            set_diagnostic(diagnostic, source,
                                member->as.method_declaration.parameters.items[parameter_index]->location,
                                "native callback delegate has a signature that is not supported by the C ABI");
                            return false;
                        }
                    }
                    else if (!extern_abi_type_supported(model, method.parameter_types[parameter_index], false))
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "extern method parameter type is not supported by the C ABI");
                        return false;
                    }
                }
            }
            else if (method.is_unsafe && !allow_unsafe && !source_is_standard_library(source))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                set_diagnostic(diagnostic, source, member->location,
                    "unsafe method '%s' requires compiler unsafe to be enabled",
                    member->as.method_declaration.name);
                return false;
            }

            if (method.is_exported)
            {
                if (method.is_extern || !method.is_static ||
                    (member->as.method_declaration.modifiers & VC_AST_MOD_PUBLIC) == 0 ||
                    member->as.method_declaration.body == NULL || method.is_operator ||
                    method.is_interface_method || method.is_delegate_invoke)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "[Export] requires a public static implemented method");
                    return false;
                }
                if (semantic_type_is_delegate(model, method.return_type) ||
                    !extern_abi_type_supported(model, method.return_type, true))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "exported method '%s' has a return type that is not supported by the native library ABI",
                        member->as.method_declaration.name);
                    return false;
                }
                for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
                {
                    const VcTokenKind modifier = method.parameter_modifiers[parameter_index];
                    if (method.parameter_types[parameter_index] == VC_SEM_TYPE_STRING &&
                        modifier != VC_TOKEN_EOF)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "exported string parameters must be passed by value");
                        return false;
                    }
                    if ((modifier != VC_TOKEN_EOF && modifier != VC_TOKEN_KW_REF &&
                            modifier != VC_TOKEN_KW_OUT && modifier != VC_TOKEN_KW_IN) ||
                        semantic_type_is_delegate(model, method.parameter_types[parameter_index]) ||
                        !extern_abi_type_supported(model, method.parameter_types[parameter_index], false))
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source,
                            member->as.method_declaration.parameters.items[parameter_index]->location,
                            "exported method parameter type or modifier is not supported by the native library ABI");
                        return false;
                    }
                }
                for (size_t existing_index = 0; existing_index < model->method_count; existing_index++)
                {
                    const VcSemanticMethod *existing = &model->methods[existing_index];
                    if (!existing->is_exported || strcmp(existing->export_c_name, method.export_c_name) != 0)
                        continue;
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "export symbol '%s' is already declared", method.export_c_name);
                    return false;
                }
            }

            if (method.is_delegate_invoke)
            {
                if (method.is_static || method.is_operator || member->as.method_declaration.body != NULL)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "delegate invocation signature is invalid");
                    return false;
                }
                model->structs[owner_struct_index].delegate_invoke_method_index = model->method_count;
            }

            if (method.is_interface_method)
            {
                const uint32_t allowed_modifiers = VC_AST_MOD_PUBLIC | VC_AST_MOD_STATIC |
                    VC_AST_MOD_ASYNC;
                if ((member->as.method_declaration.modifiers & ~allowed_modifiers) != 0)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        method.is_static
                            ? "static interface method '%s' may only use public and static modifiers"
                            : "interface method '%s' may only use the public modifier",
                        member->as.method_declaration.name);
                    return false;
                }
                if (method.is_operator)
                {
                    if (!method.is_static)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "interface operator '%s' must be static",
                            vc_token_kind_name(method.operator_kind));
                        return false;
                    }
                    if (member->as.method_declaration.body != NULL)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "static interface operator '%s' must be a signature ending in ';'",
                            vc_token_kind_name(method.operator_kind));
                        return false;
                    }
                }
                else if (method.is_static && member->as.method_declaration.body != NULL)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "static interface method '%s' must be a method signature ending in ';'",
                        member->as.method_declaration.name);
                    return false;
                }
                if (!method.is_static && member->as.method_declaration.body == NULL)
                    method.is_abstract = true;
            }

            if (!method.is_extern && !method.is_interface_method && !method.is_delegate_invoke && method.has_owner_struct &&
                model->structs[method.owner_struct_index].is_class)
            {
                const VcSemanticStruct *owner = &model->structs[method.owner_struct_index];
                if ((method.is_virtual || method.is_override || method.is_abstract || method.is_sealed) && method.is_static)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "virtual/override/abstract/sealed methods cannot be static");
                    return false;
                }
                if (method.is_virtual && (method.is_override || method.is_abstract))
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "method cannot combine virtual with override or abstract");
                    return false;
                }
                if (method.is_sealed && !method.is_override)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "sealed method must also be override");
                    return false;
                }
                if (method.is_abstract)
                {
                    if (!owner->is_abstract)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "abstract method '%s' requires an abstract containing class",
                            member->as.method_declaration.name);
                        return false;
                    }
                    if (member->as.method_declaration.body != NULL)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "abstract method '%s' cannot declare a body",
                            member->as.method_declaration.name);
                        return false;
                    }
                }
                else if (member->as.method_declaration.body == NULL && !method.is_operator)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "non-abstract method '%s' must declare a body",
                        member->as.method_declaration.name);
                    return false;
                }
            }
            else if (!method.is_extern && !method.is_interface_method && !method.is_delegate_invoke &&
                (method.is_virtual || method.is_override || method.is_abstract || method.is_sealed))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                set_diagnostic(diagnostic, source, member->location,
                    "virtual/override/abstract/sealed methods are supported on classes only");
                return false;
            }

            if (method.is_operator)
            {
                const bool conversion_operator = is_conversion_operator_kind(method.operator_kind);
                const bool unary_operator = !conversion_operator && is_unary_operator_kind(method.operator_kind) &&
                    ((method.operator_kind != VC_TOKEN_PLUS && method.operator_kind != VC_TOKEN_MINUS) ||
                     method.parameter_count == 1);
                for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
                {
                    if (method.parameter_modifiers[parameter_index] != VC_TOKEN_EOF)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "operator overload parameters cannot use ref/out/in modifiers");
                        return false;
                    }
                    if (member->as.method_declaration.parameters.items[parameter_index]->as.parameter.default_value != NULL)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "operator overload parameters cannot have default values");
                        return false;
                    }
                }
                const bool interface_operator_contract = method.is_interface_method &&
                    method.has_owner_struct && method.is_static &&
                    model->structs[method.owner_struct_index].is_interface;
                if (!method.has_owner_struct ||
                    (!interface_operator_contract && model->structs[method.owner_struct_index].is_interface) ||
                    model->structs[method.owner_struct_index].is_delegate)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overloads are supported on classes and structs only");
                    return false;
                }
                if (!method.is_static)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overload '%s' must be static",
                        vc_token_kind_name(method.operator_kind));
                    return false;
                }
                if (conversion_operator && !interface_operator_contract &&
                    (member->as.method_declaration.modifiers & VC_AST_MOD_PUBLIC) == 0)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "conversion operator '%s' must be public",
                        vc_token_kind_name(method.operator_kind));
                    return false;
                }
                if (conversion_operator)
                {
                    if (method.parameter_count != 1)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion operator '%s' requires exactly one parameter",
                            vc_token_kind_name(method.operator_kind));
                        return false;
                    }
                    if (method.return_type == VC_SEM_TYPE_VOID || method.return_type == VC_SEM_TYPE_UNKNOWN ||
                        method.return_type == VC_SEM_TYPE_ERROR)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion operator '%s' requires a value return type",
                            vc_token_kind_name(method.operator_kind));
                        return false;
                    }

                    const VcSemanticType owner_type = vc_semantic_struct_type(method.owner_struct_index);
                    if (!interface_operator_contract &&
                        method.parameter_types[0] != owner_type && method.return_type != owner_type)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion operator must convert to or from its declaring type '%s'",
                            model->structs[method.owner_struct_index].name);
                        return false;
                    }
                    if (method.parameter_types[0] == method.return_type)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion operator source and target types must differ");
                        return false;
                    }
                    if (is_standard_assignable(model, method.return_type, method.parameter_types[0]) ||
                        is_standard_assignable(model, method.parameter_types[0], method.return_type))
                    {
                        const VcSemanticType source_type = method.parameter_types[0];
                        const VcSemanticType target_type = method.return_type;
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion from '%s' to '%s' conflicts with an existing standard conversion",
                            context_type_display_name(&diagnostic_display_context, source_type),
                            context_type_display_name(&diagnostic_display_context, target_type));
                        return false;
                    }

                    for (size_t existing_index = 0; existing_index < model->method_count; existing_index++)
                    {
                        const VcSemanticMethod *existing = &model->methods[existing_index];
                        if (!existing->is_operator || existing->is_interface_method ||
                            interface_operator_contract || !is_conversion_operator_kind(existing->operator_kind) ||
                            existing->parameter_count != 1 ||
                            existing->parameter_types[0] != method.parameter_types[0] ||
                            existing->return_type != method.return_type)
                            continue;
                        const VcSemanticType source_type = method.parameter_types[0];
                        const VcSemanticType target_type = method.return_type;
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        set_diagnostic(diagnostic, source, member->location,
                            "conversion from '%s' to '%s' is already declared",
                            context_type_display_name(&diagnostic_display_context, source_type),
                            context_type_display_name(&diagnostic_display_context, target_type));
                        return false;
                    }
                }
                else if (unary_operator && method.parameter_count != 1)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "unary operator overload '%s' requires exactly one parameter",
                        vc_token_kind_name(method.operator_kind));
                    return false;
                }
                else if (!unary_operator && method.parameter_count != 2)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "binary operator overload '%s' requires exactly two parameters",
                        vc_token_kind_name(method.operator_kind));
                    return false;
                }

                const VcSemanticType owner_type = vc_semantic_struct_type(method.owner_struct_index);
                if (!interface_operator_contract && unary_operator && method.parameter_types[0] != owner_type)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "unary operator overload '%s' must take '%s' as its operand",
                        vc_token_kind_name(method.operator_kind),
                        model->structs[method.owner_struct_index].name);
                    return false;
                }
                if (!interface_operator_contract && !conversion_operator && !unary_operator &&
                    method.parameter_types[0] != owner_type && method.parameter_types[1] != owner_type)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overload '%s' must include '%s' as an operand",
                        vc_token_kind_name(method.operator_kind),
                        model->structs[method.owner_struct_index].name);
                    return false;
                }
                if (!interface_operator_contract && unary_operator &&
                    (method.operator_kind == VC_TOKEN_PLUS_PLUS || method.operator_kind == VC_TOKEN_MINUS_MINUS) &&
                    method.return_type != owner_type)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "operator overload '%s' on '%s' must return '%s'",
                        vc_token_kind_name(method.operator_kind),
                        model->structs[method.owner_struct_index].name,
                        model->structs[method.owner_struct_index].name);
                    return false;
                }

                switch (method.operator_kind)
                {
                    case VC_TOKEN_EQUAL_EQUAL:
                    case VC_TOKEN_BANG_EQUAL:
                    case VC_TOKEN_LESS:
                    case VC_TOKEN_LESS_EQUAL:
                    case VC_TOKEN_GREATER:
                    case VC_TOKEN_GREATER_EQUAL:
                        if (method.return_type != VC_SEM_TYPE_BOOL)
                        {
                            free(method.parameter_types);
                            set_diagnostic(diagnostic, source, member->location,
                                "comparison operator overload '%s' must return bool",
                                vc_token_kind_name(method.operator_kind));
                            return false;
                        }
                        break;
                    default:
                        break;
                }
            }

            bool has_native_string_parameter_contract = false;
            for (size_t parameter_index = 0; parameter_index < method.parameter_count; parameter_index++)
            {
                const VcAstNode *parameter = member->as.method_declaration.parameters.items[parameter_index];
                if (find_named_attribute(&parameter->attributes, "NativeString") != NULL)
                {
                    has_native_string_parameter_contract = true;
                    break;
                }
            }
            if (has_native_string_parameter_contract)
            {
                method.native_string_parameter_contracts = calloc(method.parameter_count,
                    sizeof(*method.native_string_parameter_contracts));
                if (method.native_string_parameter_contracts == NULL)
                {
                    free(method.parameter_types);
                    free(method.parameter_modifiers);
                    set_diagnostic(diagnostic, source, member->location,
                        "out of memory while collecting native string contracts");
                    return false;
                }
            }
            if (!resolve_native_string_contracts(member, method.is_extern, method.is_delegate_invoke,
                    method.return_type, method.parameter_types, method.parameter_modifiers, method.parameter_count,
                    source, diagnostic, &method.native_string_return_contract,
                    method.native_string_parameter_contracts,
                    method.native_string_release_c_name,
                    sizeof(method.native_string_release_c_name)))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                free(method.native_string_parameter_contracts);
                return false;
            }

            if (method.is_extern)
            {
                for (size_t existing_index = 0; existing_index < model->method_count; existing_index++)
                {
                    const VcSemanticMethod *existing = &model->methods[existing_index];
                    if (existing->is_extern && strcmp(existing->c_name, method.c_name) == 0)
                    {
                        free(method.parameter_types);
                        free(method.parameter_modifiers);
                        free(method.native_string_parameter_contracts);
                        set_diagnostic(diagnostic, source, member->location,
                            "native symbol '%s' is already declared", method.c_name);
                        return false;
                    }
                }
            }

            if (!push_method(model, method))
            {
                free(method.parameter_types);
                free(method.parameter_modifiers);
                free(method.native_string_parameter_contracts);
                set_diagnostic(diagnostic, source, member->location, "out of memory while collecting methods");
                return false;
            }
        }
    }
    return true;
}

static bool method_parameters_equal(const VcSemanticMethod *left, const VcSemanticMethod *right)
{
    if (left->parameter_count != right->parameter_count)
        return false;
    for (size_t i = 0; i < left->parameter_count; i++)
    {
        if (left->parameter_types[i] != right->parameter_types[i] ||
            left->parameter_modifiers[i] != right->parameter_modifiers[i])
            return false;
    }
    return true;
}

static bool method_parameter_scopes_equal(const VcSemanticMethod *left, const VcSemanticMethod *right)
{
    if (left == NULL || right == NULL || left->parameter_count != right->parameter_count ||
        left->node == NULL || right->node == NULL)
        return false;
    const VcAstNodeList *left_parameters = &left->node->as.method_declaration.parameters;
    const VcAstNodeList *right_parameters = &right->node->as.method_declaration.parameters;
    if (left_parameters->count != left->parameter_count ||
        right_parameters->count != right->parameter_count)
        return false;
    for (size_t i = 0; i < left->parameter_count; i++)
    {
        const VcAstNode *left_parameter = left_parameters->items[i];
        const VcAstNode *right_parameter = right_parameters->items[i];
        const bool left_scoped = left_parameter != NULL && left_parameter->kind == VC_AST_PARAMETER &&
            left_parameter->as.parameter.scoped;
        const bool right_scoped = right_parameter != NULL && right_parameter->kind == VC_AST_PARAMETER &&
            right_parameter->as.parameter.scoped;
        if (left_scoped != right_scoped)
            return false;
    }
    return true;
}

static size_t find_declared_instance_method(
    const VcSemanticModel *model,
    size_t owner_index,
    const char *name,
    const VcSemanticMethod *signature)
{
    for (size_t i = 0; i < model->method_count; i++)
    {
        const VcSemanticMethod *candidate = &model->methods[i];
        if (!candidate->has_owner_struct || candidate->owner_struct_index != owner_index ||
            candidate->is_static || candidate->is_operator)
            continue;
        if (strcmp(candidate->node->as.method_declaration.name, name) != 0)
            continue;
        if (signature != NULL && !method_parameters_equal(candidate, signature))
            continue;
        return i;
    }
    return (size_t)-1;
}

static size_t find_base_method_for_override(const VcSemanticModel *model, const VcSemanticMethod *method)
{
    if (!method->has_owner_struct || method->owner_struct_index >= model->struct_count)
        return (size_t)-1;
    const VcSemanticStruct *owner = &model->structs[method->owner_struct_index];
    if (!owner->has_base_class)
        return (size_t)-1;

    size_t current = owner->base_class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const size_t candidate = find_declared_instance_method(model, current,
            method->node->as.method_declaration.name, method);
        if (candidate != (size_t)-1)
            return candidate;
        if (!model->structs[current].has_base_class)
            break;
        current = model->structs[current].base_class_index;
    }
    return (size_t)-1;
}

static size_t find_virtual_implementation_for_class(
    const VcSemanticModel *model,
    size_t class_index,
    size_t root_index)
{
    if (root_index >= model->method_count || class_index >= model->struct_count)
        return (size_t)-1;
    const VcSemanticMethod *root = &model->methods[root_index];

    size_t current = class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        for (size_t i = 0; i < model->method_count; i++)
        {
            const VcSemanticMethod *candidate = &model->methods[i];
            if (!candidate->has_owner_struct || candidate->owner_struct_index != current ||
                candidate->is_static || candidate->is_operator)
                continue;
            if (i == root_index || (candidate->has_virtual_root && candidate->virtual_root_index == root_index))
                return i;
        }
        if (!model->structs[current].has_base_class)
            break;
        current = model->structs[current].base_class_index;
    }
    return root->owner_struct_index == class_index ? root_index : (size_t)-1;
}

static bool validate_inheritance_methods(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t i = 0; i < model->method_count; i++)
    {
        VcSemanticMethod *method = &model->methods[i];
        if (!method->has_owner_struct || !model->structs[method->owner_struct_index].is_class ||
            method->is_static || method->is_operator)
            continue;

        if (method->is_override)
        {
            const size_t base_method_index = find_base_method_for_override(model, method);
            if (base_method_index == (size_t)-1)
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "method '%s' is marked override but no matching base method exists",
                    method->node->as.method_declaration.name);
                return false;
            }

            const VcSemanticMethod *base_method = &model->methods[base_method_index];
            if (!(base_method->is_virtual || base_method->is_abstract || base_method->is_override))
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "method '%s' cannot override non-virtual base method",
                    method->node->as.method_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_OVERRIDE);
                related_declaration(diagnostic, base_method->source, base_method->node,
                    "Base member contract is declared here.");
                return false;
            }
            if (base_method->is_sealed)
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "method '%s' cannot override a sealed base method",
                    method->node->as.method_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_OVERRIDE);
                related_declaration(diagnostic, base_method->source, base_method->node,
                    "Base member contract is declared here.");
                return false;
            }
            if (!method_parameter_scopes_equal(method, base_method))
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "override '%s' must preserve scoped parameter contract",
                    method->node->as.method_declaration.name);
                return false;
            }
            if (method->returns_ref != base_method->returns_ref)
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "override '%s' must %sreturn by ref",
                    method->node->as.method_declaration.name,
                    base_method->returns_ref ? "" : "not ");
                return false;
            }
            if (method->returns_ref_readonly != base_method->returns_ref_readonly)
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "override '%s' must preserve ref return shape",
                    method->node->as.method_declaration.name);
                return false;
            }
            if (method->return_type != base_method->return_type)
            {
                set_diagnostic(diagnostic, method->source, method->node->location,
                    "override '%s' must return '%s'",
                    method->node->as.method_declaration.name,
                    context_type_display_name(&diagnostic_display_context, base_method->return_type));
                vc_diagnostic_set_code(diagnostic, VC_DIAG_OVERRIDE);
                related_declaration(diagnostic, base_method->source, base_method->node,
                    "Base member contract is declared here.");
                return false;
            }

            method->has_virtual_root = true;
            method->virtual_root_index = base_method->has_virtual_root ?
                base_method->virtual_root_index : base_method_index;
        }
        else if (method->is_virtual || method->is_abstract)
        {
            method->has_virtual_root = true;
            method->virtual_root_index = i;
        }
    }

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract)
            continue;

        for (size_t root_index = 0; root_index < model->method_count; root_index++)
        {
            const VcSemanticMethod *root = &model->methods[root_index];
            if (!root->has_virtual_root || root->virtual_root_index != root_index || !root->is_abstract ||
                !root->has_owner_struct ||
                !class_is_same_or_derived(model, class_index, root->owner_struct_index))
                continue;

            const size_t implementation = find_virtual_implementation_for_class(model, class_index, root_index);
            if (implementation == (size_t)-1 || model->methods[implementation].is_abstract)
            {
                set_diagnostic(diagnostic, structure->source, structure->node->location,
                    "non-abstract class '%s' does not implement abstract method '%s'",
                    structure->name, root->node->as.method_declaration.name);
                return false;
            }
        }
    }

    return true;
}

static bool find_base_property_for_override(
    const VcSemanticModel *model,
    size_t class_index,
    const VcSemanticProperty *property,
    size_t *owner_index,
    size_t *property_index)
{
    if (class_index >= model->struct_count || property == NULL ||
        !model->structs[class_index].has_base_class)
        return false;

    size_t current = model->structs[class_index].base_class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->property_count; i++)
        {
            const VcSemanticProperty *candidate = &structure->properties[i];
            if (!candidate->is_static &&
                strcmp(candidate->node->as.property_declaration.name,
                    property->node->as.property_declaration.name) == 0)
            {
                *owner_index = current;
                *property_index = i;
                return true;
            }
        }
        if (!structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool property_matches_virtual_root(
    const VcSemanticProperty *property,
    size_t owner_index,
    size_t property_index,
    size_t root_owner,
    size_t root_property)
{
    return (owner_index == root_owner && property_index == root_property) ||
        (property->has_virtual_root &&
         property->virtual_root_struct_index == root_owner &&
         property->virtual_root_property_index == root_property);
}

static bool find_virtual_property_implementation_for_class(
    const VcSemanticModel *model,
    size_t class_index,
    size_t root_owner,
    size_t root_property,
    size_t *owner_index,
    size_t *property_index)
{
    if (class_index >= model->struct_count || root_owner >= model->struct_count ||
        root_property >= model->structs[root_owner].property_count)
        return false;

    size_t current = class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->property_count; i++)
        {
            const VcSemanticProperty *candidate = &structure->properties[i];
            if (candidate->is_static)
                continue;
            if (property_matches_virtual_root(candidate, current, i, root_owner, root_property))
            {
                *owner_index = current;
                *property_index = i;
                return true;
            }
        }
        if (!structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool validate_inheritance_properties(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class)
            continue;

        for (size_t property_index = 0; property_index < structure->property_count; property_index++)
        {
            VcSemanticProperty *property = &structure->properties[property_index];
            if (property->is_static)
                continue;

            if (property->is_override)
            {
                size_t base_owner = 0;
                size_t base_index = 0;
                if (!find_base_property_for_override(model, class_index, property,
                        &base_owner, &base_index))
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "property '%s' is marked override but no matching base property exists",
                        property->node->as.property_declaration.name);
                    return false;
                }

                const VcSemanticProperty *base = &model->structs[base_owner].properties[base_index];
                if (!(base->is_virtual || base->is_abstract || base->is_override))
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "property '%s' cannot override non-virtual base property",
                        property->node->as.property_declaration.name);
                    return false;
                }
                if (base->is_sealed)
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "property '%s' cannot override a sealed base property",
                        property->node->as.property_declaration.name);
                    return false;
                }
                if (property->returns_ref != base->returns_ref ||
                    property->returns_ref_readonly != base->returns_ref_readonly)
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "override property '%s' must preserve ref return shape",
                        property->node->as.property_declaration.name);
                    return false;
                }
                if (property->type != base->type)
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "override property '%s' must use type '%s'",
                        property->node->as.property_declaration.name,
                        context_type_display_name(&diagnostic_display_context, base->type));
                    return false;
                }
                if (property->has_getter != base->has_getter ||
                    property->has_setter != base->has_setter)
                {
                    set_diagnostic(diagnostic, structure->source, property->node->location,
                        "override property '%s' must preserve the base accessor shape",
                        property->node->as.property_declaration.name);
                    return false;
                }

                property->has_virtual_root = true;
                if (base->has_virtual_root)
                {
                    property->virtual_root_struct_index = base->virtual_root_struct_index;
                    property->virtual_root_property_index = base->virtual_root_property_index;
                }
                else
                {
                    property->virtual_root_struct_index = base_owner;
                    property->virtual_root_property_index = base_index;
                }
            }
            else if (property->is_virtual || property->is_abstract)
            {
                property->has_virtual_root = true;
                property->virtual_root_struct_index = class_index;
                property->virtual_root_property_index = property_index;
            }
        }
    }

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract)
            continue;

        for (size_t abstract_owner = 0; abstract_owner < model->struct_count; abstract_owner++)
        {
            const VcSemanticStruct *abstract_structure = &model->structs[abstract_owner];
            if (!abstract_structure->is_class ||
                !class_is_same_or_derived(model, class_index, abstract_owner))
                continue;
            for (size_t abstract_property = 0;
                 abstract_property < abstract_structure->property_count;
                 abstract_property++)
            {
                const VcSemanticProperty *required =
                    &abstract_structure->properties[abstract_property];
                if (!required->is_abstract || !required->has_virtual_root)
                    continue;
                const size_t root_owner = required->virtual_root_struct_index;
                const size_t root_property = required->virtual_root_property_index;

                size_t implementation_owner = 0;
                size_t implementation_property = 0;
                if (!find_virtual_property_implementation_for_class(model, class_index,
                        root_owner, root_property,
                        &implementation_owner, &implementation_property) ||
                    model->structs[implementation_owner].properties[implementation_property].is_abstract)
                {
                    set_diagnostic(diagnostic, structure->source, structure->node->location,
                        "non-abstract class '%s' does not implement abstract property '%s'",
                        structure->name,
                        required->node->as.property_declaration.name);
                    return false;
                }
            }
        }
    }

    return true;
}

static bool find_base_event_for_override(
    const VcSemanticModel *model,
    size_t class_index,
    const VcSemanticField *event,
    size_t *owner_index,
    size_t *field_index)
{
    if (class_index >= model->struct_count || event == NULL ||
        !model->structs[class_index].has_base_class)
        return false;

    size_t current = model->structs[class_index].base_class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->field_count; i++)
        {
            const VcSemanticField *candidate = &structure->fields[i];
            if (!candidate->is_event || candidate->is_static ||
                strcmp(candidate->node->as.field_declaration.name,
                    event->node->as.field_declaration.name) != 0)
                continue;
            *owner_index = current;
            *field_index = i;
            return true;
        }
        if (!structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool event_matches_virtual_root(
    const VcSemanticField *candidate,
    size_t owner_index,
    size_t field_index,
    size_t root_owner,
    size_t root_field)
{
    return (owner_index == root_owner && field_index == root_field) ||
        (candidate->has_virtual_root &&
         candidate->virtual_root_struct_index == root_owner &&
         candidate->virtual_root_field_index == root_field);
}

static bool find_virtual_event_implementation_for_class(
    const VcSemanticModel *model,
    size_t class_index,
    size_t root_owner,
    size_t root_field,
    size_t *owner_index,
    size_t *field_index)
{
    if (class_index >= model->struct_count || root_owner >= model->struct_count ||
        root_field >= model->structs[root_owner].field_count)
        return false;

    size_t current = class_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->field_count; i++)
        {
            const VcSemanticField *candidate = &structure->fields[i];
            if (candidate->is_event && !candidate->is_static &&
                event_matches_virtual_root(candidate, current, i, root_owner, root_field))
            {
                *owner_index = current;
                *field_index = i;
                return true;
            }
        }
        if (!structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool validate_inheritance_events(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class)
            continue;

        for (size_t field_index = 0; field_index < structure->field_count; field_index++)
        {
            VcSemanticField *event = &structure->fields[field_index];
            if (!event->is_event || event->is_static)
                continue;

            if (event->is_override)
            {
                size_t base_owner = 0;
                size_t base_index = 0;
                if (!find_base_event_for_override(model, class_index, event,
                        &base_owner, &base_index))
                {
                    set_diagnostic(diagnostic, structure->source, event->node->location,
                        "event '%s' is marked override but no matching base event exists",
                        event->node->as.field_declaration.name);
                    return false;
                }
                const VcSemanticField *base = &model->structs[base_owner].fields[base_index];
                if (!(base->is_virtual || base->is_abstract || base->is_override))
                {
                    set_diagnostic(diagnostic, structure->source, event->node->location,
                        "event '%s' cannot override non-virtual base event",
                        event->node->as.field_declaration.name);
                    return false;
                }
                if (base->is_sealed)
                {
                    set_diagnostic(diagnostic, structure->source, event->node->location,
                        "event '%s' cannot override a sealed base event",
                        event->node->as.field_declaration.name);
                    return false;
                }
                if (event->type != base->type)
                {
                    set_diagnostic(diagnostic, structure->source, event->node->location,
                        "override event '%s' must use type '%s'",
                        event->node->as.field_declaration.name,
                        context_type_display_name(&diagnostic_display_context, base->type));
                    return false;
                }
                event->has_virtual_root = true;
                if (base->has_virtual_root)
                {
                    event->virtual_root_struct_index = base->virtual_root_struct_index;
                    event->virtual_root_field_index = base->virtual_root_field_index;
                }
                else
                {
                    event->virtual_root_struct_index = base_owner;
                    event->virtual_root_field_index = base_index;
                }
            }
            else if (event->is_virtual || event->is_abstract)
            {
                event->has_virtual_root = true;
                event->virtual_root_struct_index = class_index;
                event->virtual_root_field_index = field_index;
            }
        }
    }

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract)
            continue;

        for (size_t abstract_owner = 0; abstract_owner < model->struct_count; abstract_owner++)
        {
            const VcSemanticStruct *abstract_structure = &model->structs[abstract_owner];
            if (!abstract_structure->is_class ||
                !class_is_same_or_derived(model, class_index, abstract_owner))
                continue;
            for (size_t abstract_field = 0; abstract_field < abstract_structure->field_count; abstract_field++)
            {
                const VcSemanticField *required = &abstract_structure->fields[abstract_field];
                if (!required->is_event || !required->is_abstract || !required->has_virtual_root)
                    continue;

                size_t implementation_owner = 0;
                size_t implementation_field = 0;
                if (!find_virtual_event_implementation_for_class(model, class_index,
                        required->virtual_root_struct_index,
                        required->virtual_root_field_index,
                        &implementation_owner, &implementation_field) ||
                    model->structs[implementation_owner].fields[implementation_field].is_abstract)
                {
                    set_diagnostic(diagnostic, structure->source, structure->node->location,
                        "non-abstract class '%s' does not implement abstract event '%s'",
                        structure->name,
                        required->node->as.field_declaration.name);
                    return false;
                }
            }
        }
    }
    return true;
}

static size_t find_interface_implementation_for_type(
    const VcSemanticModel *model,
    size_t type_index,
    size_t interface_method_index,
    bool *ambiguous_default)
{
    if (ambiguous_default != NULL)
        *ambiguous_default = false;
    if (type_index >= model->struct_count || interface_method_index >= model->method_count)
        return (size_t)-1;
    const VcSemanticMethod *required = &model->methods[interface_method_index];
    if (!required->is_interface_method)
        return (size_t)-1;

    size_t current = type_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        for (size_t i = 0; i < model->method_count; i++)
        {
            const VcSemanticMethod *candidate = &model->methods[i];
            if (!candidate->has_owner_struct || candidate->owner_struct_index != current ||
                candidate->is_static != required->is_static ||
                candidate->is_operator != required->is_operator ||
                candidate->is_interface_method)
                continue;
            if ((required->is_operator
                    ? candidate->operator_kind != required->operator_kind
                    : strcmp(candidate->node->as.method_declaration.name,
                        required->node->as.method_declaration.name) != 0) ||
                candidate->return_type != required->return_type ||
                candidate->returns_ref != required->returns_ref ||
                candidate->returns_ref_readonly != required->returns_ref_readonly ||
                !method_parameters_equal(candidate, required) ||
                !method_parameter_scopes_equal(candidate, required))
                continue;
            if ((candidate->node->as.method_declaration.modifiers & VC_AST_MOD_PUBLIC) == 0)
                continue;
            return i;
        }
        if (!model->structs[current].is_class || !model->structs[current].has_base_class)
            break;
        current = model->structs[current].base_class_index;
    }

    if (required->is_static)
        return (size_t)-1;

    size_t best = (size_t)-1;
    for (size_t i = 0; i < model->method_count; i++)
    {
        const VcSemanticMethod *candidate = &model->methods[i];
        if (!candidate->is_interface_method || candidate->is_static ||
            !candidate->has_owner_struct || candidate->owner_struct_index >= model->struct_count ||
            !model->structs[candidate->owner_struct_index].is_interface ||
            !type_implements_interface(model, type_index, candidate->owner_struct_index) ||
            !interface_is_same_or_derived(model, candidate->owner_struct_index,
                required->owner_struct_index) ||
            strcmp(candidate->node->as.method_declaration.name,
                required->node->as.method_declaration.name) != 0 ||
            candidate->return_type != required->return_type ||
            candidate->returns_ref != required->returns_ref ||
            candidate->returns_ref_readonly != required->returns_ref_readonly ||
            !method_parameters_equal(candidate, required) ||
            !method_parameter_scopes_equal(candidate, required))
            continue;

        if (best == (size_t)-1)
        {
            best = i;
            continue;
        }

        const size_t candidate_owner = candidate->owner_struct_index;
        const size_t best_owner = model->methods[best].owner_struct_index;
        if (candidate_owner == best_owner)
            continue;
        if (interface_is_same_or_derived(model, candidate_owner, best_owner))
        {
            best = i;
            continue;
        }
        if (interface_is_same_or_derived(model, best_owner, candidate_owner))
            continue;
        if (ambiguous_default != NULL)
            *ambiguous_default = true;
        return (size_t)-1;
    }

    if (best == (size_t)-1 || model->methods[best].node->as.method_declaration.body == NULL)
        return (size_t)-1;
    return best;
}

static bool interface_property_accessor_is_public(
    const VcSemanticProperty *property,
    uint32_t accessor_modifiers)
{
    if (property == NULL || property->node == NULL)
        return false;
    const uint32_t effective = accessor_modifiers != 0
        ? accessor_modifiers
        : property->node->as.property_declaration.modifiers;
    return (effective & VC_AST_MOD_PUBLIC) != 0 &&
        (effective & (VC_AST_MOD_PRIVATE | VC_AST_MOD_PROTECTED | VC_AST_MOD_INTERNAL)) == 0;
}

static bool find_interface_property_implementation_for_type(
    const VcSemanticModel *model,
    size_t type_index,
    size_t interface_index,
    size_t interface_property_index,
    size_t *owner_index,
    size_t *property_index)
{
    if (type_index >= model->struct_count || interface_index >= model->struct_count ||
        interface_property_index >= model->structs[interface_index].property_count)
        return false;

    const VcSemanticProperty *required =
        &model->structs[interface_index].properties[interface_property_index];
    size_t current = type_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->property_count; i++)
        {
            const VcSemanticProperty *candidate = &structure->properties[i];
            if (strcmp(candidate->node->as.property_declaration.name,
                    required->node->as.property_declaration.name) != 0 ||
                candidate->type != required->type || candidate->returns_ref != required->returns_ref ||
                candidate->returns_ref_readonly != required->returns_ref_readonly ||
                !candidate->has_getter || candidate->is_static != required->is_static)
                continue;
            if (!interface_property_accessor_is_public(candidate,
                    candidate->node->as.property_declaration.getter_modifiers))
                continue;
            if (required->has_setter &&
                (!candidate->has_setter || !interface_property_accessor_is_public(candidate,
                    candidate->node->as.property_declaration.setter_modifiers)))
                continue;
            *owner_index = current;
            *property_index = i;
            return true;
        }
        if (!structure->is_class || !structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool find_interface_event_implementation_for_type(
    const VcSemanticModel *model,
    size_t type_index,
    size_t interface_index,
    size_t interface_field_index,
    size_t *owner_index,
    size_t *field_index)
{
    if (type_index >= model->struct_count || interface_index >= model->struct_count ||
        interface_field_index >= model->structs[interface_index].field_count)
        return false;

    const VcSemanticField *required =
        &model->structs[interface_index].fields[interface_field_index];
    if (!required->is_event)
        return false;

    size_t current = type_index;
    for (size_t guard = 0; guard <= model->struct_count; guard++)
    {
        const VcSemanticStruct *structure = &model->structs[current];
        for (size_t i = 0; i < structure->field_count; i++)
        {
            const VcSemanticField *candidate = &structure->fields[i];
            if (!candidate->is_event || candidate->is_static != required->is_static ||
                strcmp(candidate->node->as.field_declaration.name,
                    required->node->as.field_declaration.name) != 0 ||
                candidate->type != required->type)
                continue;
            if ((candidate->node->as.field_declaration.modifiers & VC_AST_MOD_PUBLIC) == 0)
                continue;
            *owner_index = current;
            *field_index = i;
            return true;
        }
        if (!structure->is_class || !structure->has_base_class)
            break;
        current = structure->base_class_index;
    }
    return false;
}

static bool validate_interface_inheritance_contracts(
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t interface_index = 0; interface_index < model->struct_count; interface_index++)
    {
        const VcSemanticStruct *interface = &model->structs[interface_index];
        if (!interface->is_interface)
            continue;

        for (size_t left_index = 0; left_index < model->method_count; left_index++)
        {
            const VcSemanticMethod *left = &model->methods[left_index];
            if (!left->is_interface_method || !left->has_owner_struct ||
                !interface_is_same_or_derived(model, interface_index, left->owner_struct_index))
                continue;

            for (size_t right_index = left_index + 1; right_index < model->method_count; right_index++)
            {
                const VcSemanticMethod *right = &model->methods[right_index];
                if (!right->is_interface_method || !right->has_owner_struct ||
                    !interface_is_same_or_derived(model, interface_index, right->owner_struct_index) ||
                    left->is_operator != right->is_operator)
                    continue;

                const bool left_conversion = left->is_operator &&
                    is_conversion_operator_kind(left->operator_kind);
                const bool right_conversion = right->is_operator &&
                    is_conversion_operator_kind(right->operator_kind);
                if (left_conversion || right_conversion)
                {
                    if (!left_conversion || !right_conversion ||
                        !method_parameters_equal(left, right) ||
                        left->return_type != right->return_type)
                        continue;
                    if (left->operator_kind != right->operator_kind)
                    {
                        set_diagnostic(diagnostic, interface->source, interface->node->location,
                            "interface '%s' has conflicting implicit/explicit conversion contracts from '%s' to '%s'",
                            interface->name,
                            context_type_display_name(&diagnostic_display_context, left->parameter_types[0]),
                            context_type_display_name(&diagnostic_display_context, left->return_type));
                        return false;
                    }
                }
                else if ((left->is_operator
                        ? left->operator_kind != right->operator_kind
                        : strcmp(left->node->as.method_declaration.name,
                            right->node->as.method_declaration.name) != 0) ||
                    !method_parameters_equal(left, right))
                {
                    continue;
                }

                if (left->is_static != right->is_static)
                {
                    set_diagnostic(diagnostic, interface->source, interface->node->location,
                        "interface '%s' inherits conflicting static and instance method '%s' contracts",
                        interface->name, left->node->as.method_declaration.name);
                    return false;
                }
                if (!method_parameter_scopes_equal(left, right))
                {
                    set_diagnostic(diagnostic, interface->source, interface->node->location,
                        "interface '%s' inherits conflicting scoped parameter contracts for method '%s'",
                        interface->name, left->node->as.method_declaration.name);
                    return false;
                }
                if (!left_conversion && (left->return_type != right->return_type || left->returns_ref != right->returns_ref ||
                    left->returns_ref_readonly != right->returns_ref_readonly))
                {
                    if (left->is_operator)
                    {
                        set_diagnostic(diagnostic, interface->source, interface->node->location,
                            "interface '%s' inherits conflicting operator '%s' return types",
                            interface->name, vc_token_kind_name(left->operator_kind));
                    }
                    else
                    {
                        set_diagnostic(diagnostic, interface->source, interface->node->location,
                            "interface '%s' inherits conflicting method '%s' return types",
                            interface->name, left->node->as.method_declaration.name);
                    }
                    return false;
                }
                if (!left->is_static && left->node->as.method_declaration.body != NULL &&
                    right->node->as.method_declaration.body != NULL &&
                    left->owner_struct_index != right->owner_struct_index &&
                    !interface_is_same_or_derived(model, left->owner_struct_index, right->owner_struct_index) &&
                    !interface_is_same_or_derived(model, right->owner_struct_index, left->owner_struct_index))
                {
                    bool resolved_here = false;
                    for (size_t own_index = 0; own_index < model->method_count; own_index++)
                    {
                        const VcSemanticMethod *own = &model->methods[own_index];
                        if (!own->is_interface_method || own->is_static || !own->has_owner_struct ||
                            own->owner_struct_index != interface_index ||
                            strcmp(own->node->as.method_declaration.name,
                                left->node->as.method_declaration.name) != 0 ||
                            own->return_type != left->return_type ||
                            own->returns_ref != left->returns_ref ||
                            own->returns_ref_readonly != left->returns_ref_readonly ||
                            !method_parameters_equal(own, left) ||
                            !method_parameter_scopes_equal(own, left))
                            continue;
                        resolved_here = true;
                        break;
                    }
                    if (!resolved_here)
                    {
                        set_diagnostic(diagnostic, interface->source, interface->node->location,
                            "interface '%s' inherits ambiguous default method '%s' implementations",
                            interface->name, left->node->as.method_declaration.name);
                        return false;
                    }
                }
            }
        }

        for (size_t left_owner = 0; left_owner < model->struct_count; left_owner++)
        {
            const VcSemanticStruct *left_interface = &model->structs[left_owner];
            if (!left_interface->is_interface ||
                !interface_is_same_or_derived(model, interface_index, left_owner))
                continue;
            for (size_t left_property = 0; left_property < left_interface->property_count; left_property++)
            {
                const VcSemanticProperty *left = &left_interface->properties[left_property];
                for (size_t right_owner = left_owner; right_owner < model->struct_count; right_owner++)
                {
                    const VcSemanticStruct *right_interface = &model->structs[right_owner];
                    if (!right_interface->is_interface ||
                        !interface_is_same_or_derived(model, interface_index, right_owner))
                        continue;
                    const size_t first_property = right_owner == left_owner ? left_property + 1 : 0;
                    for (size_t right_property = first_property;
                        right_property < right_interface->property_count; right_property++)
                    {
                        const VcSemanticProperty *right = &right_interface->properties[right_property];
                        if (strcmp(left->node->as.property_declaration.name,
                                right->node->as.property_declaration.name) != 0)
                            continue;
                        if (left->is_static != right->is_static)
                        {
                            set_diagnostic(diagnostic, interface->source, interface->node->location,
                                "interface '%s' inherits conflicting static and instance property '%s' contracts",
                                interface->name, left->node->as.property_declaration.name);
                            return false;
                        }
                        if (left->type != right->type ||
                            left->returns_ref != right->returns_ref ||
                            left->returns_ref_readonly != right->returns_ref_readonly)
                        {
                            set_diagnostic(diagnostic, interface->source, interface->node->location,
                                "interface '%s' inherits conflicting property '%s' types",
                                interface->name, left->node->as.property_declaration.name);
                            return false;
                        }
                    }
                }
            }
        }

        for (size_t left_owner = 0; left_owner < model->struct_count; left_owner++)
        {
            const VcSemanticStruct *left_interface = &model->structs[left_owner];
            if (!left_interface->is_interface ||
                !interface_is_same_or_derived(model, interface_index, left_owner))
                continue;
            for (size_t left_field = 0; left_field < left_interface->field_count; left_field++)
            {
                const VcSemanticField *left = &left_interface->fields[left_field];
                if (!left->is_event)
                    continue;
                for (size_t right_owner = left_owner; right_owner < model->struct_count; right_owner++)
                {
                    const VcSemanticStruct *right_interface = &model->structs[right_owner];
                    if (!right_interface->is_interface ||
                        !interface_is_same_or_derived(model, interface_index, right_owner))
                        continue;
                    const size_t first_field = right_owner == left_owner ? left_field + 1 : 0;
                    for (size_t right_field = first_field; right_field < right_interface->field_count; right_field++)
                    {
                        const VcSemanticField *right = &right_interface->fields[right_field];
                        if (!right->is_event ||
                            strcmp(left->node->as.field_declaration.name,
                                right->node->as.field_declaration.name) != 0)
                            continue;
                        if (left->is_static != right->is_static)
                        {
                            set_diagnostic(diagnostic, interface->source, interface->node->location,
                                "interface '%s' inherits conflicting static and instance event '%s' contracts",
                                interface->name, left->node->as.field_declaration.name);
                            return false;
                        }
                        if (left->type != right->type)
                        {
                            set_diagnostic(diagnostic, interface->source, interface->node->location,
                                "interface '%s' inherits conflicting event '%s' types",
                                interface->name, left->node->as.field_declaration.name);
                            return false;
                        }
                    }
                }
            }
        }
    }
    return true;
}

static bool validate_interface_implementations(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext display_context = {0};
    display_context.model = model;
    for (size_t type_index = 0; type_index < model->struct_count; type_index++)
    {
        const VcSemanticStruct *structure = &model->structs[type_index];
        if (structure->is_interface || structure->is_enum || structure->is_delegate ||
            (structure->is_class && structure->is_abstract))
            continue;

        for (size_t interface_index = 0; interface_index < model->struct_count; interface_index++)
        {
            if (!model->structs[interface_index].is_interface ||
                !type_implements_interface(model, type_index, interface_index))
                continue;

            for (size_t method_index = 0; method_index < model->method_count; method_index++)
            {
                const VcSemanticMethod *required = &model->methods[method_index];
                if (!required->is_interface_method || !required->has_owner_struct ||
                    required->owner_struct_index != interface_index)
                    continue;

                bool ambiguous_default = false;
                if (find_interface_implementation_for_type(model, type_index, method_index,
                        &ambiguous_default) == (size_t)-1)
                {
                    if (ambiguous_default)
                    {
                        set_diagnostic(diagnostic, structure->source, structure->node->location,
                            "%s '%s' has ambiguous default interface implementations for '%s.%s'",
                            structure->is_class ? "class" : "struct", context_type_display_name(&display_context, vc_semantic_struct_type(type_index)),
                            context_type_display_name(&display_context, vc_semantic_struct_type(interface_index)),
                            required->node->as.method_declaration.original_generic_name != NULL
                                ? required->node->as.method_declaration.original_generic_name
                                : required->node->as.method_declaration.name);
                    }
                    else
                    {
                        if (required->is_operator)
                        {
                            set_diagnostic(diagnostic, structure->source, structure->node->location,
                                "%s '%s' does not implement interface operator '%s.%s'",
                                structure->is_class ? "class" : "struct", context_type_display_name(&display_context, vc_semantic_struct_type(type_index)),
                                context_type_display_name(&display_context, vc_semantic_struct_type(interface_index)),
                                vc_token_kind_name(required->operator_kind));
                vc_diagnostic_set_code(diagnostic, VC_DIAG_INTERFACE);
                        }
                        else
                        {
                            set_diagnostic(diagnostic, structure->source, structure->node->location,
                                "%s '%s' does not implement interface method '%s.%s'",
                                structure->is_class ? "class" : "struct",
                                context_type_display_name(&display_context, vc_semantic_struct_type(type_index)), context_type_display_name(&display_context, vc_semantic_struct_type(interface_index)),
                                required->node->as.method_declaration.original_generic_name != NULL
                                    ? required->node->as.method_declaration.original_generic_name
                                    : required->node->as.method_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_INTERFACE);
                        }
                    }
                    vc_diagnostic_add_source_context(diagnostic, VC_DIAGNOSTIC_NOTE,
                        required->source,
                        vc_source_span_at_location(required->source, required->node->location),
                        "Interface contract requires this member with matching signature and accessibility.");
                    return false;
                }
            }

            const VcSemanticStruct *required_interface = &model->structs[interface_index];
            for (size_t property_index = 0; property_index < required_interface->property_count; property_index++)
            {
                size_t implementation_owner = 0;
                size_t implementation_property = 0;
                if (!find_interface_property_implementation_for_type(model, type_index,
                        interface_index, property_index, &implementation_owner, &implementation_property))
                {
                    set_diagnostic(diagnostic, structure->source, structure->node->location,
                        "%s '%s' does not implement interface property '%s.%s'",
                        structure->is_class ? "class" : "struct",
                        context_type_display_name(&display_context, vc_semantic_struct_type(type_index)), context_type_display_name(&display_context, vc_semantic_struct_type(interface_index)),
                        required_interface->properties[property_index].node->as.property_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_INTERFACE);
                    related_declaration(diagnostic, required_interface->source,
                        required_interface->properties[property_index].node,
                        "Required interface property is declared here.");
                    return false;
                }
            }

            for (size_t field_index = 0; field_index < required_interface->field_count; field_index++)
            {
                const VcSemanticField *required_event = &required_interface->fields[field_index];
                if (!required_event->is_event)
                    continue;
                size_t implementation_owner = 0;
                size_t implementation_field = 0;
                if (!find_interface_event_implementation_for_type(model, type_index,
                        interface_index, field_index, &implementation_owner, &implementation_field))
                {
                    set_diagnostic(diagnostic, structure->source, structure->node->location,
                        "%s '%s' does not implement interface event '%s.%s'",
                        structure->is_class ? "class" : "struct",
                        context_type_display_name(&display_context, vc_semantic_struct_type(type_index)), context_type_display_name(&display_context, vc_semantic_struct_type(interface_index)),
                        required_event->node->as.field_declaration.name);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_INTERFACE);
                    related_declaration(diagnostic, required_interface->source, required_event->node,
                        "Required interface event is declared here.");
                    return false;
                }
            }
        }
    }
    return true;
}

static bool value_struct_layout_dependency(
    const VcSemanticModel *model,
    VcSemanticType type,
    size_t *struct_index)
{
    while (vc_semantic_type_is_nullable(type))
        type = vc_semantic_nullable_underlying_type(model, type);

    if (!vc_semantic_type_is_struct(type))
        return false;

    const size_t index = vc_semantic_struct_index(type);
    if (index >= model->struct_count)
        return false;
    const VcSemanticStruct *structure = &model->structs[index];
    if (structure->is_class || structure->is_interface || structure->is_enum || structure->is_delegate)
        return false;

    if (struct_index != NULL)
        *struct_index = index;
    return true;
}

static bool validate_value_struct_layout_visit(
    const VcSemanticModel *model,
    size_t struct_index,
    unsigned char *states,
    VcSemanticDiagnostic *diagnostic)
{
    if (struct_index >= model->struct_count)
        return false;
    if (states[struct_index] == 2)
        return true;
    if (states[struct_index] == 1)
        return true;

    const VcSemanticStruct *structure = &model->structs[struct_index];
    if (structure->is_class || structure->is_interface || structure->is_enum || structure->is_delegate)
    {
        states[struct_index] = 2;
        return true;
    }

    states[struct_index] = 1;

    for (size_t field_index = 0; field_index < structure->field_count; field_index++)
    {
        const VcSemanticField *field = &structure->fields[field_index];
        if (field->is_const || field->is_static)
            continue;

        size_t dependency = 0;
        if (!value_struct_layout_dependency(model, field->type, &dependency))
            continue;
        if (states[dependency] == 1)
        {
            set_diagnostic(diagnostic, structure->source, field->node->location,
                "value-struct layout cycle involving '%s' and '%s'",
                structure->name, model->structs[dependency].name);
            return false;
        }
        if (!validate_value_struct_layout_visit(model, dependency, states, diagnostic))
            return false;
    }

    for (size_t property_index = 0; property_index < structure->property_count; property_index++)
    {
        const VcSemanticProperty *property = &structure->properties[property_index];
        if (!property->is_auto || property->is_static)
            continue;

        size_t dependency = 0;
        if (!value_struct_layout_dependency(model, property->type, &dependency))
            continue;
        if (states[dependency] == 1)
        {
            set_diagnostic(diagnostic, structure->source, property->node->location,
                "value-struct layout cycle involving '%s' and '%s'",
                structure->name, model->structs[dependency].name);
            return false;
        }
        if (!validate_value_struct_layout_visit(model, dependency, states, diagnostic))
            return false;
    }

    states[struct_index] = 2;
    return true;
}

static bool validate_value_struct_layout(
    const VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    unsigned char *states = calloc(model->struct_count, sizeof(*states));
    if (states == NULL && model->struct_count != 0)
    {
        diagnostic->path = NULL;
        snprintf(diagnostic->message, sizeof(diagnostic->message),
            "out of memory while validating value-struct layout");
        return false;
    }

    for (size_t i = 0; i < model->struct_count; i++)
    {
        if (!validate_value_struct_layout_visit(model, i, states, diagnostic))
        {
            free(states);
            return false;
        }
    }

    free(states);
    return true;
}

static bool validate_inheritance_constructors(VcSemanticModel *model, VcSemanticDiagnostic *diagnostic)
{
    for (size_t struct_index = 0; struct_index < model->struct_count; struct_index++)
    {
        const VcSemanticStruct *structure = &model->structs[struct_index];
        const VcAstNodeList *members = &structure->node->as.type_declaration.members;
        for (size_t i = 0; i < members->count; i++)
        {
            const VcAstNode *member = members->items[i];
            if (member->kind != VC_AST_METHOD_DECLARATION ||
                !member->as.method_declaration.is_constructor ||
                (!member->as.method_declaration.has_base_constructor_initializer &&
                 !member->as.method_declaration.has_this_constructor_initializer))
                continue;

            if ((member->as.method_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
            {
                set_diagnostic(diagnostic, structure->source, structure->node->location,
                    "static constructor '%s' cannot have a constructor initializer",
                    structure->name);
                return false;
            }
            if (member->as.method_declaration.has_base_constructor_initializer &&
                (!structure->is_class || !structure->has_base_class))
            {
                set_diagnostic(diagnostic, structure->source, member->location,
                    "constructor '%s' cannot use a base constructor initializer because the type has no base class",
                    structure->name);
                return false;
            }
        }
    }
    return true;
}

static bool is_reference_type(const VcSemanticModel *model, VcSemanticType type)
{
    return type == VC_SEM_TYPE_STRING || type == VC_SEM_TYPE_OBJECT || type == VC_SEM_TYPE_TYPE ||
        vc_semantic_type_is_array(type) || semantic_type_is_class(model, type) ||
        semantic_type_is_interface(model, type);
}

static bool is_monitor_reference_type(const VcSemanticModel *model, VcSemanticType type)
{
    return type == VC_SEM_TYPE_OBJECT || vc_semantic_type_is_array(type) ||
        semantic_type_is_class(model, type) || semantic_type_is_interface(model, type);
}

static bool is_object_reference_type(const VcSemanticModel *model, VcSemanticType type)
{
    return type == VC_SEM_TYPE_STRING || type == VC_SEM_TYPE_OBJECT ||
        vc_semantic_type_is_array(type) || semantic_type_is_class(model, type) ||
        semantic_type_is_interface(model, type);
}

static bool is_conversion_operator_kind(VcTokenKind kind)
{
    return kind == VC_TOKEN_KW_IMPLICIT || kind == VC_TOKEN_KW_EXPLICIT;
}

static bool conversion_operator_is_public(const VcSemanticMethod *candidate)
{
    return candidate != NULL && candidate->node != NULL &&
        candidate->node->kind == VC_AST_METHOD_DECLARATION &&
        (candidate->node->as.method_declaration.modifiers & VC_AST_MOD_PUBLIC) != 0;
}

static bool conversion_owner_is_associated(
    const VcSemanticModel *model,
    const VcSemanticMethod *candidate,
    VcSemanticType source,
    VcSemanticType target)
{
    if (candidate == NULL || !candidate->has_owner_struct ||
        candidate->owner_struct_index >= model->struct_count)
        return false;

    const VcSemanticType associated_source = vc_semantic_type_is_nullable(source)
        ? vc_semantic_nullable_underlying_type(model, source)
        : source;
    const VcSemanticType associated_target = vc_semantic_type_is_nullable(target)
        ? vc_semantic_nullable_underlying_type(model, target)
        : target;
    const VcSemanticType owner_type = vc_semantic_struct_type(candidate->owner_struct_index);
    if (owner_type == associated_source || owner_type == associated_target)
        return true;

    const VcSemanticStruct *owner = &model->structs[candidate->owner_struct_index];
    if (!owner->is_class)
        return false;

    if (semantic_type_is_class(model, associated_source) &&
        class_is_same_or_derived(model,
            vc_semantic_struct_index(associated_source), candidate->owner_struct_index))
        return true;

    if (semantic_type_is_class(model, associated_target) &&
        class_is_same_or_derived(model,
            vc_semantic_struct_index(associated_target), candidate->owner_struct_index))
        return true;

    return false;
}

static unsigned user_conversion_edge_rank(
    const VcSemanticModel *model,
    VcSemanticType target,
    VcSemanticType source,
    bool explicit_context)
{
    if (target == source)
        return 0;
    if (vc_semantic_classify_standard_conversion(model, target, source, false) !=
        VC_SEM_CONVERSION_NONE)
        return 1;
    if (explicit_context &&
        vc_semantic_classify_standard_conversion(model, target, source, true) !=
            VC_SEM_CONVERSION_NONE)
        return 2;
    return 3;
}

static bool user_conversion_candidate_is_applicable(
    const VcSemanticModel *model,
    const VcSemanticMethod *candidate,
    VcSemanticType source,
    VcSemanticType target,
    bool implicit_only)
{
    if (candidate == NULL || !candidate->is_operator || candidate->is_interface_method ||
        !is_conversion_operator_kind(candidate->operator_kind) ||
        (implicit_only && candidate->operator_kind != VC_TOKEN_KW_IMPLICIT) ||
        candidate->parameter_count != 1 || !conversion_operator_is_public(candidate) ||
        !conversion_owner_is_associated(model, candidate, source, target))
        return false;

    const bool explicit_context = !implicit_only;
    return vc_semantic_classify_standard_conversion(
               model, candidate->parameter_types[0], source, explicit_context) !=
            VC_SEM_CONVERSION_NONE &&
        vc_semantic_classify_standard_conversion(
            model, target, candidate->return_type, explicit_context) !=
            VC_SEM_CONVERSION_NONE;
}

static bool user_conversion_source_type_better(
    const VcSemanticModel *model,
    VcSemanticType actual_source,
    VcSemanticType left,
    VcSemanticType right,
    bool explicit_context)
{
    if (left == right)
        return false;
    if (left == actual_source)
        return true;
    if (right == actual_source)
        return false;

    const bool left_to_right = vc_semantic_classify_standard_conversion(
        model, right, left, false) != VC_SEM_CONVERSION_NONE;
    const bool right_to_left = vc_semantic_classify_standard_conversion(
        model, left, right, false) != VC_SEM_CONVERSION_NONE;
    if (left_to_right != right_to_left)
        return left_to_right;

    return user_conversion_edge_rank(model, left, actual_source, explicit_context) <
        user_conversion_edge_rank(model, right, actual_source, explicit_context);
}

static bool user_conversion_target_type_better(
    const VcSemanticModel *model,
    VcSemanticType actual_target,
    VcSemanticType left,
    VcSemanticType right,
    bool explicit_context)
{
    if (left == right)
        return false;
    if (left == actual_target)
        return true;
    if (right == actual_target)
        return false;

    const bool right_to_left = vc_semantic_classify_standard_conversion(
        model, left, right, false) != VC_SEM_CONVERSION_NONE;
    const bool left_to_right = vc_semantic_classify_standard_conversion(
        model, right, left, false) != VC_SEM_CONVERSION_NONE;
    if (right_to_left != left_to_right)
        return right_to_left;

    return user_conversion_edge_rank(model, actual_target, left, explicit_context) <
        user_conversion_edge_rank(model, actual_target, right, explicit_context);
}

static bool user_conversion_candidate_better(
    const VcSemanticModel *model,
    const VcSemanticMethod *left,
    const VcSemanticMethod *right,
    VcSemanticType source,
    VcSemanticType target,
    bool implicit_only)
{
    const bool explicit_context = !implicit_only;
    const VcSemanticType left_source = left->parameter_types[0];
    const VcSemanticType right_source = right->parameter_types[0];
    const VcSemanticType left_target = left->return_type;
    const VcSemanticType right_target = right->return_type;

    const bool source_equal = left_source == right_source;
    const bool target_equal = left_target == right_target;
    const bool source_better = user_conversion_source_type_better(
        model, source, left_source, right_source, explicit_context);
    const bool source_worse = user_conversion_source_type_better(
        model, source, right_source, left_source, explicit_context);
    const bool target_better = user_conversion_target_type_better(
        model, target, left_target, right_target, explicit_context);
    const bool target_worse = user_conversion_target_type_better(
        model, target, right_target, left_target, explicit_context);

    return (source_equal || source_better) && !source_worse &&
        (target_equal || target_better) && !target_worse &&
        (source_better || target_better);
}

static size_t resolve_user_conversion_model_direct(
    const VcSemanticModel *model,
    VcSemanticType source,
    VcSemanticType target,
    bool implicit_only,
    bool *ambiguous)
{
    *ambiguous = false;
    size_t match = (size_t)-1;
    size_t undominated = 0;

    for (size_t i = 0; i < model->method_count; i++)
    {
        const VcSemanticMethod *candidate = &model->methods[i];
        if (!user_conversion_candidate_is_applicable(
                model, candidate, source, target, implicit_only))
            continue;

        bool dominated = false;
        for (size_t j = 0; j < model->method_count; j++)
        {
            if (j == i)
                continue;
            const VcSemanticMethod *other = &model->methods[j];
            if (!user_conversion_candidate_is_applicable(
                    model, other, source, target, implicit_only))
                continue;
            if (user_conversion_candidate_better(
                    model, other, candidate, source, target, implicit_only))
            {
                dominated = true;
                break;
            }
        }
        if (dominated)
            continue;

        match = i;
        undominated++;
        if (undominated > 1)
        {
            *ambiguous = true;
            return match;
        }
    }
    return match;
}

static size_t resolve_user_conversion_model(
    const VcSemanticModel *model,
    VcSemanticType source,
    VcSemanticType target,
    bool implicit_only,
    bool *ambiguous,
    bool *lifted_nullable)
{
    *ambiguous = false;
    if (lifted_nullable != NULL)
        *lifted_nullable = false;

    if (vc_semantic_type_is_nullable(source) && vc_semantic_type_is_nullable(target))
    {
        const VcSemanticType source_underlying =
            vc_semantic_nullable_underlying_type(model, source);
        const VcSemanticType target_underlying =
            vc_semantic_nullable_underlying_type(model, target);
        bool underlying_ambiguous = false;
        const size_t lifted = resolve_user_conversion_model_direct(
            model, source_underlying, target_underlying, implicit_only, &underlying_ambiguous);
        if (underlying_ambiguous)
        {
            *ambiguous = true;
            if (lifted_nullable != NULL)
                *lifted_nullable = true;
            return lifted;
        }
        if (lifted != (size_t)-1)
        {
            const VcSemanticMethod *conversion = &model->methods[lifted];
            if (!vc_semantic_type_is_nullable(conversion->parameter_types[0]) &&
                !vc_semantic_type_is_nullable(conversion->return_type))
            {
                if (lifted_nullable != NULL)
                    *lifted_nullable = true;
                return lifted;
            }
        }
    }

    return resolve_user_conversion_model_direct(
        model, source, target, implicit_only, ambiguous);
}

static bool has_implicit_numeric_conversion(VcSemanticType source, VcSemanticType target)
{
    switch (source)
    {
        case VC_SEM_TYPE_SBYTE:
            return target == VC_SEM_TYPE_SHORT || target == VC_SEM_TYPE_INT ||
                target == VC_SEM_TYPE_LONG || target == VC_SEM_TYPE_FLOAT ||
                target == VC_SEM_TYPE_DOUBLE || target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_BYTE:
            return target == VC_SEM_TYPE_SHORT || target == VC_SEM_TYPE_USHORT ||
                target == VC_SEM_TYPE_INT || target == VC_SEM_TYPE_UINT ||
                target == VC_SEM_TYPE_LONG || target == VC_SEM_TYPE_ULONG ||
                target == VC_SEM_TYPE_FLOAT || target == VC_SEM_TYPE_DOUBLE ||
                target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_SHORT:
            return target == VC_SEM_TYPE_INT || target == VC_SEM_TYPE_LONG ||
                target == VC_SEM_TYPE_FLOAT || target == VC_SEM_TYPE_DOUBLE ||
                target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_USHORT:
            return target == VC_SEM_TYPE_INT || target == VC_SEM_TYPE_UINT ||
                target == VC_SEM_TYPE_LONG || target == VC_SEM_TYPE_ULONG ||
                target == VC_SEM_TYPE_FLOAT || target == VC_SEM_TYPE_DOUBLE ||
                target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_INT:
            return target == VC_SEM_TYPE_LONG || target == VC_SEM_TYPE_FLOAT ||
                target == VC_SEM_TYPE_DOUBLE || target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_UINT:
            return target == VC_SEM_TYPE_LONG || target == VC_SEM_TYPE_ULONG ||
                target == VC_SEM_TYPE_FLOAT || target == VC_SEM_TYPE_DOUBLE ||
                target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
            return target == VC_SEM_TYPE_FLOAT || target == VC_SEM_TYPE_DOUBLE ||
                target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_CHAR:
            return target == VC_SEM_TYPE_USHORT || target == VC_SEM_TYPE_INT ||
                target == VC_SEM_TYPE_UINT || target == VC_SEM_TYPE_LONG ||
                target == VC_SEM_TYPE_ULONG || target == VC_SEM_TYPE_FLOAT ||
                target == VC_SEM_TYPE_DOUBLE || target == VC_SEM_TYPE_DECIMAL;
        case VC_SEM_TYPE_FLOAT:
            return target == VC_SEM_TYPE_DOUBLE;
        default:
            return false;
    }
}

VcSemanticStandardConversionKind vc_semantic_classify_standard_conversion(
    const VcSemanticModel *model,
    VcSemanticType target,
    VcSemanticType source,
    bool explicit_context)
{
    if (model == NULL)
        return VC_SEM_CONVERSION_NONE;
    if (target == source && target != VC_SEM_TYPE_UNKNOWN && target != VC_SEM_TYPE_ERROR)
        return VC_SEM_CONVERSION_IDENTITY;
    if (target == VC_SEM_TYPE_UNKNOWN || target == VC_SEM_TYPE_ERROR ||
        target == VC_SEM_TYPE_VOID || source == VC_SEM_TYPE_UNKNOWN ||
        source == VC_SEM_TYPE_ERROR || source == VC_SEM_TYPE_VOID)
        return VC_SEM_CONVERSION_NONE;

    if (vc_semantic_type_is_nullable(target))
    {
        const VcSemanticType underlying = vc_semantic_nullable_underlying_type(model, target);
        if (source == VC_SEM_TYPE_NULL)
            return VC_SEM_CONVERSION_NULL;
        if (!vc_semantic_type_is_nullable(source) &&
            vc_semantic_classify_standard_conversion(
                model, underlying, source, explicit_context) != VC_SEM_CONVERSION_NONE)
            return VC_SEM_CONVERSION_NULLABLE;
    }
    if (explicit_context && vc_semantic_type_is_nullable(source) &&
        !vc_semantic_type_is_nullable(target))
    {
        const VcSemanticType underlying = vc_semantic_nullable_underlying_type(model, source);
        if (vc_semantic_classify_standard_conversion(
                model, target, underlying, true) != VC_SEM_CONVERSION_NONE)
            return VC_SEM_CONVERSION_NULLABLE;
    }

    if (vc_semantic_type_is_pointer(target) && vc_semantic_type_is_pointer(source))
    {
        const VcSemanticType target_element = vc_semantic_pointer_element_type(model, target);
        const VcSemanticType source_element = vc_semantic_pointer_element_type(model, source);
        if (target_element == VC_SEM_TYPE_VOID ||
            (explicit_context && source_element == VC_SEM_TYPE_VOID))
            return VC_SEM_CONVERSION_POINTER;
    }

    if (source == VC_SEM_TYPE_NULL)
    {
        if (vc_semantic_type_is_function_pointer(target))
            return VC_SEM_CONVERSION_FUNCTION_POINTER;
        if (vc_semantic_type_is_pointer(target))
            return VC_SEM_CONVERSION_POINTER;
        if (is_reference_type(model, target))
            return VC_SEM_CONVERSION_NULL;
        return VC_SEM_CONVERSION_NONE;
    }

    if (has_implicit_numeric_conversion(source, target))
        return VC_SEM_CONVERSION_NUMERIC;
    if (explicit_context && is_numeric(source) && is_numeric(target))
        return VC_SEM_CONVERSION_NUMERIC;

    if (explicit_context &&
        ((semantic_type_is_enum(model, target) && is_integral(source)) ||
         (is_integral(target) && semantic_type_is_enum(model, source))))
        return VC_SEM_CONVERSION_ENUM;

    if (target == VC_SEM_TYPE_OBJECT && is_object_reference_type(model, source))
        return VC_SEM_CONVERSION_REFERENCE;

    if (semantic_type_is_class(model, target) && semantic_type_is_class(model, source))
    {
        const size_t target_index = vc_semantic_struct_index(target);
        const size_t source_index = vc_semantic_struct_index(source);
        if (class_is_same_or_derived(model, source_index, target_index))
            return VC_SEM_CONVERSION_REFERENCE;
    }

    if (semantic_type_is_interface(model, target) && vc_semantic_type_is_struct(source) &&
        !semantic_type_is_interface(model, source))
    {
        const size_t source_index = vc_semantic_struct_index(source);
        if (source_index < model->struct_count && !model->structs[source_index].is_enum &&
            !model->structs[source_index].is_delegate &&
            type_implements_interface(model, source_index, vc_semantic_struct_index(target)))
            return VC_SEM_CONVERSION_REFERENCE;
    }

    if (semantic_type_is_interface(model, target) && semantic_type_is_interface(model, source) &&
        interface_is_same_or_derived(model, vc_semantic_struct_index(source),
            vc_semantic_struct_index(target)))
        return VC_SEM_CONVERSION_REFERENCE;

    if (explicit_context)
    {
        const bool target_runtime_reference = target == VC_SEM_TYPE_OBJECT ||
            semantic_type_is_class(model, target) || semantic_type_is_interface(model, target);
        const bool source_runtime_reference = source == VC_SEM_TYPE_OBJECT ||
            semantic_type_is_class(model, source) || semantic_type_is_interface(model, source);
        if (target_runtime_reference && source_runtime_reference)
            return VC_SEM_CONVERSION_REFERENCE;
    }

    return VC_SEM_CONVERSION_NONE;
}

static bool is_standard_assignable(const VcSemanticModel *model, VcSemanticType target, VcSemanticType source)
{
    return vc_semantic_classify_standard_conversion(model, target, source, false) !=
        VC_SEM_CONVERSION_NONE;
}

static bool is_assignable(const VcSemanticModel *model, VcSemanticType target, VcSemanticType source)
{
    if (is_standard_assignable(model, target, source))
        return true;

    bool ambiguous = false;
    return resolve_user_conversion_model(model, source, target, true, &ambiguous, NULL) != (size_t)-1 && !ambiguous;
}

static bool generic_type_has_public_parameterless_constructor(
    const VcSemanticModel *model,
    VcSemanticType type)
{
    if (nullable_underlying_supported(model, type))
        return true;
    if (!semantic_type_is_class(model, type) || semantic_type_is_delegate(model, type))
        return false;

    const size_t struct_index = vc_semantic_struct_index(type);
    if (struct_index >= model->struct_count)
        return false;
    const VcSemanticStruct *structure = &model->structs[struct_index];
    if (structure->is_abstract || (structure->node->as.type_declaration.modifiers & VC_AST_MOD_STATIC) != 0)
        return false;

    bool has_declared_constructor = false;
    for (size_t i = 0; i < model->constructor_count; i++)
    {
        const VcSemanticConstructor *constructor = &model->constructors[i];
        if (constructor->struct_index != struct_index)
            continue;
        has_declared_constructor = true;
        if (constructor->parameter_count == 0 &&
            (constructor->node->as.method_declaration.modifiers & VC_AST_MOD_PUBLIC) != 0)
            return true;
    }
    return !has_declared_constructor;
}

static bool validate_instantiated_generic_constraints(
    VcSemanticModel *model,
    const VcAstNodeList *constraints,
    const char *namespace_name,
    const VcSource *diagnostic_source,
    VcSourceLocation diagnostic_location,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext diagnostic_display_context = {0};
    diagnostic_display_context.model = model;
    for (size_t i = 0; i < constraints->count; i++)
    {
        const VcAstNode *constraint = constraints->items[i];
        if (constraint == NULL || constraint->kind != VC_AST_GENERIC_CONSTRAINT ||
            constraint->as.generic_constraint.argument_type == NULL)
            continue;

        const char *parameter = constraint->as.generic_constraint.parameter;
        const VcSemanticType argument = resolve_type(model,
            constraint->as.generic_constraint.argument_type, namespace_name, false);
        if (argument == VC_SEM_TYPE_UNKNOWN || argument == VC_SEM_TYPE_ERROR ||
            argument == VC_SEM_TYPE_VOID)
        {
            set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                "generic type argument for '%s' could not be resolved", parameter);
            return false;
        }

        if (constraint->as.generic_constraint.requires_reference_type &&
            !is_reference_type(model, argument))
        {
            set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                "type argument '%s' must be a reference type for generic parameter '%s'",
                context_type_display_name(&diagnostic_display_context, argument), parameter);
            return false;
        }
        if (constraint->as.generic_constraint.requires_value_type &&
            !nullable_underlying_supported(model, argument))
        {
            set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                "type argument '%s' must be a non-nullable value type for generic parameter '%s'",
                context_type_display_name(&diagnostic_display_context, argument), parameter);
            return false;
        }
        if (constraint->as.generic_constraint.requires_unmanaged_type &&
            !vc_semantic_type_is_unmanaged(model, argument))
        {
            set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                "type argument '%s' must be an unmanaged type for generic parameter '%s'",
                context_type_display_name(&diagnostic_display_context, argument), parameter);
            return false;
        }

        bool saw_base_class_constraint = false;
        for (size_t c = 0; c < constraint->as.generic_constraint.type_constraints.count; c++)
        {
            const VcAstTypeRef *type_ref = constraint->as.generic_constraint.type_constraints.items[c];
            const VcSemanticType required = resolve_type(model, type_ref, namespace_name, false);
            if (required == VC_SEM_TYPE_UNKNOWN || required == VC_SEM_TYPE_ERROR ||
                required == VC_SEM_TYPE_VOID)
            {
                set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                    "generic constraint type '%s' for '%s' could not be resolved",
                    type_ref != NULL && type_ref->name != NULL ? type_ref->name : "<unknown>", parameter);
                return false;
            }
            if (!type_ref->generic_constraint_parameter)
            {
                const bool required_interface = semantic_type_is_interface(model, required);
                const bool required_class = semantic_type_is_class(model, required) &&
                    !semantic_type_is_delegate(model, required);
                if (!required_class && !required_interface)
                {
                    set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                        "constraint '%s' for generic parameter '%s' must be a class or interface type",
                        context_type_display_name(&diagnostic_display_context, required), parameter);
                    return false;
                }
                if (required_class)
                {
                    const size_t required_index = vc_semantic_struct_index(required);
                    if (required_index >= model->struct_count || model->structs[required_index].is_sealed)
                    {
                        set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                            "sealed class '%s' cannot be used as a generic constraint",
                            context_type_display_name(&diagnostic_display_context, required));
                        return false;
                    }
                    if (saw_base_class_constraint || c != 0 ||
                        constraint->as.generic_constraint.requires_reference_type)
                    {
                        set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                            "base class constraint '%s' for '%s' must appear first and cannot be combined with 'class'",
                            context_type_display_name(&diagnostic_display_context, required), parameter);
                        return false;
                    }
                    saw_base_class_constraint = true;
                }
            }
            for (size_t previous = 0; previous < c; previous++)
            {
                const VcSemanticType other = resolve_type(model,
                    constraint->as.generic_constraint.type_constraints.items[previous],
                    namespace_name, false);
                if (other == required)
                {
                    set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                        "generic parameter '%s' contains a duplicate type constraint '%s'",
                        parameter, context_type_display_name(&diagnostic_display_context, required));
                    return false;
                }
            }
            if (!is_standard_assignable(model, required, argument))
            {
                set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                    "type argument '%s' does not satisfy constraint '%s' for generic parameter '%s'",
                    context_type_display_name(&diagnostic_display_context, argument),
                    context_type_display_name(&diagnostic_display_context, required), parameter);
                vc_diagnostic_set_code(diagnostic, VC_DIAG_CONSTRAINT);
                vc_diagnostic_add_context(diagnostic, VC_DIAGNOSTIC_NOTE, NULL,
                    (VcSourceSpan){0}, "Generic constraints must hold for the supplied type argument before the generic body can be used.");
                return false;
            }
        }

        if (constraint->as.generic_constraint.requires_constructor &&
            !generic_type_has_public_parameterless_constructor(model, argument))
        {
            set_diagnostic(diagnostic, diagnostic_source, diagnostic_location,
                "type argument '%s' must have a public parameterless constructor for generic parameter '%s'",
                context_type_display_name(&diagnostic_display_context, argument), parameter);
            return false;
        }
    }
    return true;
}

static bool validate_instantiated_type_constraints(
    VcSemanticModel *model,
    VcSemanticDiagnostic *diagnostic)
{
    VcSemanticContext display_context = {0};
    display_context.model = model;
    for (size_t i = 0; i < model->struct_count; i++)
    {
        VcSemanticStruct *structure = &model->structs[i];
        if (structure->node != NULL && structure->node->kind == VC_AST_TYPE_DECLARATION &&
            structure->node->as.type_declaration.original_generic_name != NULL)
        {
            for (size_t argument_index = 0;
                argument_index < structure->node->as.type_declaration.generic_arguments.count;
                argument_index++)
            {
                const VcSemanticType argument = resolve_type(model,
                    structure->node->as.type_declaration.generic_arguments.items[argument_index],
                    structure->namespace_name, false);
                if (!semantic_type_is_ref_struct(model, argument))
                    continue;
                set_diagnostic(diagnostic, structure->source, structure->node->location,
                    "ref struct type argument '%s' is not supported by generic type '%s'",
                    context_type_display_name(&display_context, argument),
                    structure->node->as.type_declaration.original_generic_name);
                return false;
            }
        }
        if (!validate_instantiated_generic_constraints(model,
                &structure->node->as.type_declaration.generic_constraints,
                structure->namespace_name, structure->source, structure->node->location, diagnostic))
            return false;
    }
    return true;
}

static bool is_integral(VcSemanticType type)
{
    switch (type)
    {
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_CHAR:
            return true;
        default:
            return false;
    }
}

static bool is_numeric(VcSemanticType type)
{
    switch (type)
    {
        case VC_SEM_TYPE_BYTE:
        case VC_SEM_TYPE_SBYTE:
        case VC_SEM_TYPE_SHORT:
        case VC_SEM_TYPE_USHORT:
        case VC_SEM_TYPE_INT:
        case VC_SEM_TYPE_UINT:
        case VC_SEM_TYPE_LONG:
        case VC_SEM_TYPE_ULONG:
        case VC_SEM_TYPE_FLOAT:
        case VC_SEM_TYPE_DOUBLE:
        case VC_SEM_TYPE_DECIMAL:
        case VC_SEM_TYPE_CHAR:
            return true;
        default:
            return false;
    }
}

static bool is_primitive_text_formattable(VcSemanticType type)
{
    return type == VC_SEM_TYPE_BOOL || is_numeric(type);
}

static bool is_nullable_numeric_or_enum(const VcSemanticModel *model, VcSemanticType type)
{
    if (!vc_semantic_type_is_nullable(type))
        return false;
    const VcSemanticType underlying = vc_semantic_nullable_underlying_type(model, type);
    return underlying == VC_SEM_TYPE_BOOL || is_numeric(underlying) ||
        semantic_type_is_enum(model, underlying);
}

static VcSemanticType nullable_operand_underlying(
    const VcSemanticModel *model,
    VcSemanticType type)
{
    return vc_semantic_type_is_nullable(type)
        ? vc_semantic_nullable_underlying_type(model, type)
        : type;
}

static bool is_runtime_checked_reference_type(const VcSemanticModel *model, VcSemanticType type)
{
    return type == VC_SEM_TYPE_OBJECT || semantic_type_is_class(model, type) ||
        semantic_type_is_interface(model, type);
}

static bool explicit_cast_is_allowed(
    const VcSemanticModel *model,
    VcSemanticType target,
    VcSemanticType source)
{
    return vc_semantic_classify_standard_conversion(model, target, source, true) !=
        VC_SEM_CONVERSION_NONE;
}

static bool type_relation_is_allowed(
    const VcSemanticModel *model,
    VcTokenKind operator_kind,
    VcSemanticType target,
    VcSemanticType source)
{
    if (target == VC_SEM_TYPE_OBJECT)
        return source == VC_SEM_TYPE_NULL || is_object_reference_type(model, source);

    if (!semantic_type_is_class(model, target) && !semantic_type_is_interface(model, target))
        return false;

    if (source == VC_SEM_TYPE_NULL)
        return true;

    if (!is_runtime_checked_reference_type(model, source))
        return false;

    return operator_kind == VC_TOKEN_KW_IS || operator_kind == VC_TOKEN_KW_AS;
}

static bool declaration_pattern_relation_is_allowed(
    const VcSemanticModel *model,
    VcSemanticType target,
    VcSemanticType source)
{
    if (type_relation_is_allowed(model, VC_TOKEN_KW_IS, target, source))
        return true;
    if (source == target && source != VC_SEM_TYPE_NULL && source != VC_SEM_TYPE_VOID)
        return true;
    return false;
}

static VcSemanticType numeric_literal_type(VcAstNumericKind kind)
{
    switch (kind)
    {
        case VC_AST_NUM_INT: return VC_SEM_TYPE_INT;
        case VC_AST_NUM_UINT: return VC_SEM_TYPE_UINT;
        case VC_AST_NUM_LONG: return VC_SEM_TYPE_LONG;
        case VC_AST_NUM_ULONG: return VC_SEM_TYPE_ULONG;
        case VC_AST_NUM_FLOAT: return VC_SEM_TYPE_FLOAT;
        case VC_AST_NUM_DOUBLE: return VC_SEM_TYPE_DOUBLE;
        case VC_AST_NUM_DECIMAL: return VC_SEM_TYPE_DECIMAL;
    }
    return VC_SEM_TYPE_ERROR;
}

static bool push_local_node_ex_origin(
    VcSemanticContext *context,
    const char *name,
    VcSemanticType type,
    VcSourceLocation location,
    VcTokenKind modifier,
    bool assigned,
    const VcAstNode *declaration_node,
    const char *explicit_generic_parameter_origin)
{
    for (size_t i = context->local_count; i > 0; i--)
    {
        const VcLocal *local = &context->locals[i - 1];
        if (local->depth < context->depth)
            break;
        if (strcmp(local->name, name) == 0)
        {
            set_diagnostic(context->diagnostic, context->source, location,
                "a local or parameter named '%s' is already declared in this scope", name);
                vc_diagnostic_set_code(context->diagnostic, VC_DIAG_DUPLICATE);
            related_declaration(context->diagnostic, context->source,
                local->declaration_node, "Previous local or parameter declaration is here.");
            return false;
        }
    }

    if (context->local_count == context->local_capacity)
    {
        const size_t capacity = context->local_capacity == 0 ? 16 : context->local_capacity * 2;
        VcLocal *locals = realloc(context->locals, capacity * sizeof(*locals));
        if (locals == NULL)
        {
            set_diagnostic(context->diagnostic, context->source, location,
                "out of memory while creating local scope");
            return false;
        }
        context->locals = locals;
        context->local_capacity = capacity;
    }

    VcSemanticCaptureScopeKind capture_scope_kind = VC_SEM_CAPTURE_SCOPE_METHOD;
    size_t capture_scope_index = context->method_index;
    const VcAstNode *capture_scope_node = NULL;
    if (declaration_node != NULL && declaration_node->kind == VC_AST_FOREACH_STATEMENT)
    {
        capture_scope_kind = VC_SEM_CAPTURE_SCOPE_FOREACH;
        capture_scope_node = declaration_node;
    }
    else if (context->in_lambda)
    {
        capture_scope_kind = VC_SEM_CAPTURE_SCOPE_LAMBDA;
        capture_scope_index = context->lambda_index;
    }

    const char *generic_parameter_origin = explicit_generic_parameter_origin;
    if (generic_parameter_origin == NULL && declaration_node != NULL)
    {
        const VcSemanticBinding *declaration_binding =
            vc_semantic_binding(context->model, declaration_node);
        if (declaration_binding != NULL)
            generic_parameter_origin = declaration_binding->generic_parameter_origin;
        if (generic_parameter_origin == NULL)
        {
            switch (declaration_node->kind)
            {
                case VC_AST_PARAMETER:
                    generic_parameter_origin = declaration_node->as.parameter.type != NULL
                        ? declaration_node->as.parameter.type->generic_parameter_origin : NULL;
                    break;
                case VC_AST_LOCAL_DECLARATION:
                    generic_parameter_origin = declaration_node->as.local_declaration.type != NULL
                        ? declaration_node->as.local_declaration.type->generic_parameter_origin : NULL;
                    break;
                case VC_AST_FOREACH_STATEMENT:
                    generic_parameter_origin = declaration_node->as.foreach_statement.type != NULL
                        ? declaration_node->as.foreach_statement.type->generic_parameter_origin : NULL;
                    break;
                default:
                    break;
            }
        }
    }

    context->locals[context->local_count++] = (VcLocal){
        .name = name,
        .type = type,
        .generic_parameter_origin = generic_parameter_origin,
        .depth = context->depth,
        .modifier = modifier,
        .assigned = assigned,
        .ref_has_local_target = false,
        .ref_local_target_index = (size_t)-1,
        .ref_escape_safe = false,
        .ref_struct_escape_depth = 0,
        .ref_readonly = false,
        .scoped = false,
        .pointer_pin_escape_depth = 0,
        .declaration_node = declaration_node,
        .capture_scope_kind = capture_scope_kind,
        .capture_scope_index = capture_scope_index,
        .capture_scope_node = capture_scope_node
    };
    return true;
}

static bool push_local_node_ex(
    VcSemanticContext *context,
    const char *name,
    VcSemanticType type,
    VcSourceLocation location,
    VcTokenKind modifier,
    bool assigned,
    const VcAstNode *declaration_node)
{
    return push_local_node_ex_origin(context, name, type, location, modifier,
        assigned, declaration_node, NULL);
}

static bool push_local(VcSemanticContext *context, const char *name, VcSemanticType type, VcSourceLocation location)
{
    return push_local_node_ex(context, name, type, location, VC_TOKEN_EOF, true, NULL);
}

static VcLocal *find_local_entry(VcSemanticContext *context, const char *name)
{
    for (size_t i = context->local_count; i > 0; i--)
    {
        if (strcmp(context->locals[i - 1].name, name) == 0)
            return &context->locals[i - 1];
    }
    return NULL;
}

static const VcLocal *find_local_entry_const(const VcSemanticContext *context, const char *name)
{
    for (size_t i = context->local_count; i > 0; i--)
    {
        if (strcmp(context->locals[i - 1].name, name) == 0)
            return &context->locals[i - 1];
    }
    return NULL;
}

static bool find_local(const VcSemanticContext *context, const char *name, VcSemanticType *type)
{
    const VcLocal *local = find_local_entry_const(context, name);
    if (local == NULL)
        return false;
    *type = local->type;
    return true;
}


static size_t find_local_index(const VcSemanticContext *context, const char *name)
{
    for (size_t i = context->local_count; i > 0; i--)
    {
        if (strcmp(context->locals[i - 1].name, name) == 0)
            return i - 1;
    }
    return (size_t)-1;
}

static bool local_effectively_assigned_index(const VcSemanticContext *context, size_t local_index)
{
    size_t remaining = context != NULL ? context->local_count + 1 : 0;
    while (context != NULL && local_index < context->local_count && remaining-- > 0)
    {
        const VcLocal *local = &context->locals[local_index];
        if (local->modifier == VC_TOKEN_KW_REF && local->ref_has_local_target)
        {
            local_index = local->ref_local_target_index;
            continue;
        }
        return local->assigned;
    }
    return true;
}

static bool local_effectively_assigned(const VcSemanticContext *context, const VcLocal *local)
{
    if (context == NULL || local == NULL)
        return true;
    const size_t index = (size_t)(local - context->locals);
    if (index >= context->local_count)
        return local->assigned;
    return local_effectively_assigned_index(context, index);
}

static VcRefFlowState *snapshot_ref_flow(
    VcSemanticContext *context,
    size_t count,
    VcSourceLocation location)
{
    if (count == 0)
        return NULL;
    VcRefFlowState *values = calloc(count, sizeof(*values));
    if (values == NULL)
    {
        set_diagnostic(context->diagnostic, context->source, location,
            "out of memory while tracking ref-local flow");
        return NULL;
    }
    for (size_t i = 0; i < count; i++)
    {
        const VcLocal *local = &context->locals[i];
        values[i].is_ref_local = local_is_declared_ref_local(local);
        values[i].is_ref_struct_value = semantic_type_is_ref_struct(context->model, local->type) &&
            !values[i].is_ref_local;
        values[i].ref_struct_escape_depth = local->ref_struct_escape_depth;
        values[i].pointer_pin_escape_depth = local->pointer_pin_escape_depth;
        if (!values[i].is_ref_local)
            continue;
        values[i].has_local_target = local->ref_has_local_target;
        values[i].local_target_index = local->ref_local_target_index;
        values[i].effectively_assigned = local_effectively_assigned_index(context, i);
        values[i].escape_safe = local->ref_escape_safe;
    }
    return values;
}

static void restore_ref_flow(
    VcSemanticContext *context,
    const VcRefFlowState *values,
    size_t count)
{
    if (values == NULL)
        return;
    for (size_t i = 0; i < count; i++)
    {
        VcLocal *local = &context->locals[i];
        if (values[i].is_ref_struct_value)
            local->ref_struct_escape_depth = values[i].ref_struct_escape_depth;
        local->pointer_pin_escape_depth = values[i].pointer_pin_escape_depth;
        if (!values[i].is_ref_local)
            continue;
        local->ref_has_local_target = values[i].has_local_target;
        local->ref_local_target_index = values[i].local_target_index;
        local->ref_escape_safe = values[i].escape_safe;
        if (!values[i].has_local_target)
            local->assigned = values[i].effectively_assigned;
    }
}

static void merge_ref_flow(
    VcSemanticContext *context,
    const VcRefFlowState *left,
    const VcRefFlowState *right,
    size_t count)
{
    if (left == NULL || right == NULL)
        return;
    for (size_t i = 0; i < count; i++)
    {
        VcLocal *local = &context->locals[i];
        if (left[i].is_ref_struct_value && right[i].is_ref_struct_value)
            local->ref_struct_escape_depth = left[i].ref_struct_escape_depth > right[i].ref_struct_escape_depth
                ? left[i].ref_struct_escape_depth : right[i].ref_struct_escape_depth;
        local->pointer_pin_escape_depth = left[i].pointer_pin_escape_depth > right[i].pointer_pin_escape_depth
            ? left[i].pointer_pin_escape_depth : right[i].pointer_pin_escape_depth;
        if (!left[i].is_ref_local || !right[i].is_ref_local)
            continue;
        if (left[i].has_local_target == right[i].has_local_target &&
            (!left[i].has_local_target ||
             left[i].local_target_index == right[i].local_target_index))
        {
            local->ref_has_local_target = left[i].has_local_target;
            local->ref_local_target_index = left[i].local_target_index;
            if (!local->ref_has_local_target)
                local->assigned = left[i].effectively_assigned && right[i].effectively_assigned;
            local->ref_escape_safe = left[i].escape_safe && right[i].escape_safe;
            continue;
        }
        local->ref_has_local_target = false;
        local->ref_local_target_index = (size_t)-1;
        local->assigned = left[i].effectively_assigned && right[i].effectively_assigned;
        local->ref_escape_safe = left[i].escape_safe && right[i].escape_safe;
    }
}

static void mark_local_assigned_index(VcSemanticContext *context, size_t local_index)
{
    size_t remaining = context != NULL ? context->local_count + 1 : 0;
    while (context != NULL && local_index < context->local_count && remaining-- > 0)
    {
        VcLocal *local = &context->locals[local_index];
        local->assigned = true;
        if (local->modifier != VC_TOKEN_KW_REF || !local->ref_has_local_target)
            return;
        local_index = local->ref_local_target_index;
    }
}

static bool record_lambda_local_capture(VcSemanticContext *context, size_t local_index)
{
    if (!context->in_lambda || context->lambda_index >= context->model->lambda_count ||
        local_index >= context->lambda_outer_local_count)
        return true;
    const VcLocal *local = &context->locals[local_index];
    if (local->pointer_pin_escape_depth != 0)
    {
        set_diagnostic(context->diagnostic, context->source,
            local->declaration_node != NULL ? local->declaration_node->location :
                context->model->lambdas[context->lambda_index].node->location,
            "pointer local '%s' depends on a fixed pin and cannot be captured by a lambda",
            local->name);
        return false;
    }
    if (local->modifier == VC_TOKEN_KW_REF && local->declaration_node != NULL &&
        ((local->declaration_node->kind == VC_AST_LOCAL_DECLARATION &&
          local->declaration_node->as.local_declaration.is_ref) ||
         (local->declaration_node->kind == VC_AST_FOREACH_STATEMENT &&
          local->declaration_node->as.foreach_statement.is_ref)))
    {
        set_diagnostic(context->diagnostic, context->source,
            local->declaration_node->location,
            local->declaration_node->kind == VC_AST_FOREACH_STATEMENT
                ? "ref foreach iteration variable '%s' cannot be captured by a lambda"
                : "ref local '%s' cannot be captured by a lambda",
            local->name);
        return false;
    }
    if (semantic_type_is_ref_struct(context->model, local->type))
    {
        set_diagnostic(context->diagnostic, context->source,
            local->declaration_node != NULL ? local->declaration_node->location :
                context->model->lambdas[context->lambda_index].node->location,
            "ref struct local '%s' cannot be captured by a lambda", local->name);
        return false;
    }
    if (local->declaration_node != NULL &&
        local->declaration_node->kind == VC_AST_LOCAL_DECLARATION &&
        local->declaration_node->as.local_declaration.initializer != NULL &&
        local->declaration_node->as.local_declaration.initializer->kind == VC_AST_STACKALLOC_EXPRESSION)
    {
        set_diagnostic(context->diagnostic, context->source,
            local->declaration_node->location,
            "stackalloc local '%s' cannot be captured by a lambda", local->name);
        return false;
    }
    VcSemanticCapture capture = {0};
    capture.kind = VC_SEM_CAPTURE_LOCAL;
    capture.scope_kind = local->capture_scope_kind;
    capture.scope_index = local->capture_scope_index;
    capture.scope_node = local->capture_scope_node;
    capture.declaration_node = local->declaration_node;
    capture.name = local->name;
    capture.type = local->type;
    capture.modifier = local->modifier;
    if (!lambda_push_capture(&context->model->lambdas[context->lambda_index], capture))
    {
        set_diagnostic(context->diagnostic, context->source,
            context->model->lambdas[context->lambda_index].node->location,
            "out of memory while capturing lambda local");
        return false;
    }
    return true;
}

static bool record_lambda_this_capture(VcSemanticContext *context)
{
    if (!context->in_lambda || context->lambda_index >= context->model->lambda_count)
        return true;
    if (!context->has_this)
        return true;
    if (context->this_struct_index >= context->model->struct_count)
        return false;
    if (context->model->structs[context->this_struct_index].is_ref_struct)
    {
        set_diagnostic(context->diagnostic, context->source,
            context->model->lambdas[context->lambda_index].node->location,
            "ref struct 'this' cannot be captured by a lambda");
        return false;
    }
    VcSemanticCapture capture = {0};
    capture.kind = VC_SEM_CAPTURE_THIS;
    capture.scope_kind = VC_SEM_CAPTURE_SCOPE_METHOD;
    capture.scope_index = context->method_index;
    capture.name = "this";
    capture.type = vc_semantic_struct_type(context->this_struct_index);
    capture.modifier = VC_TOKEN_EOF;
    if (!lambda_push_capture(&context->model->lambdas[context->lambda_index], capture))
    {
        set_diagnostic(context->diagnostic, context->source,
            context->model->lambdas[context->lambda_index].node->location,
            "out of memory while capturing lambda this");
        return false;
    }
    return true;
}

static bool annotate(VcSemanticContext *context, const VcAstNode *node, VcSemanticType type)
{
    VcSemanticBinding binding = {0};
    binding.node = node;
    binding.type = type;
    if (push_binding(context->model, binding))
        return true;

    set_diagnostic(context->diagnostic, context->source, node->location,
        "out of memory while storing semantic information");
    return false;
}

static bool analyze_method(VcSemanticModel *model, size_t method_index, VcSemanticDiagnostic *diagnostic);
static bool analyze_constructor(VcSemanticModel *model, size_t constructor_index, VcSemanticDiagnostic *diagnostic);
static bool analyze_implicit_class_construction(
    VcSemanticModel *model,
    size_t struct_index,
    VcSemanticDiagnostic *diagnostic);
static bool analyze_reachable_instance_initializers(
    VcSemanticModel *model, size_t struct_index, VcSemanticDiagnostic *diagnostic);
static bool analyze_property_getter(VcSemanticModel *model, size_t struct_index, size_t property_index, VcSemanticDiagnostic *diagnostic);
static bool analyze_property_setter(VcSemanticModel *model, size_t struct_index, size_t property_index, VcSemanticDiagnostic *diagnostic);
static bool analyze_custom_event_accessor(VcSemanticModel *model, size_t struct_index,
    size_t field_index, bool remove_accessor, VcSemanticDiagnostic *diagnostic);

static bool mark_virtual_dispatch_reachable(
    VcSemanticModel *model,
    size_t root_index,
    VcSemanticDiagnostic *diagnostic)
{
    if (root_index >= model->method_count)
        return false;
    const VcSemanticMethod *root = &model->methods[root_index];
    if (!root->has_owner_struct)
        return false;

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract ||
            !class_is_same_or_derived(model, class_index, root->owner_struct_index))
            continue;

        const size_t implementation = find_virtual_implementation_for_class(model, class_index, root_index);
        if (implementation == (size_t)-1 || model->methods[implementation].is_abstract)
            continue;
        model->methods[implementation].reachable = true;
        if (!analyze_method(model, implementation, diagnostic))
            return false;
    }
    return true;
}

static bool mark_virtual_property_getter_dispatch_reachable(
    VcSemanticModel *model,
    size_t root_owner,
    size_t root_property,
    VcSemanticDiagnostic *diagnostic)
{
    if (root_owner >= model->struct_count ||
        root_property >= model->structs[root_owner].property_count)
        return false;

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract ||
            !class_is_same_or_derived(model, class_index, root_owner))
            continue;

        size_t owner_index = 0;
        size_t property_index = 0;
        if (!find_virtual_property_implementation_for_class(model, class_index,
                root_owner, root_property, &owner_index, &property_index))
            continue;
        VcSemanticProperty *property = &model->structs[owner_index].properties[property_index];
        if (property->is_abstract)
            continue;
        property->getter_reachable = true;
        if (!analyze_property_getter(model, owner_index, property_index, diagnostic))
            return false;
    }
    return true;
}

static bool mark_virtual_property_setter_dispatch_reachable(
    VcSemanticModel *model,
    size_t root_owner,
    size_t root_property,
    VcSemanticDiagnostic *diagnostic)
{
    if (root_owner >= model->struct_count ||
        root_property >= model->structs[root_owner].property_count)
        return false;

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract ||
            !class_is_same_or_derived(model, class_index, root_owner))
            continue;

        size_t owner_index = 0;
        size_t property_index = 0;
        if (!find_virtual_property_implementation_for_class(model, class_index,
                root_owner, root_property, &owner_index, &property_index))
            continue;
        VcSemanticProperty *property = &model->structs[owner_index].properties[property_index];
        if (property->is_abstract || !property->has_setter)
            continue;
        property->setter_reachable = true;
        if (!analyze_property_setter(model, owner_index, property_index, diagnostic))
            return false;
    }
    return true;
}

static bool mark_virtual_event_dispatch_reachable(
    VcSemanticModel *model,
    size_t root_owner,
    size_t root_field,
    bool remove_accessor,
    VcSemanticDiagnostic *diagnostic)
{
    if (root_owner >= model->struct_count ||
        root_field >= model->structs[root_owner].field_count)
        return false;

    for (size_t class_index = 0; class_index < model->struct_count; class_index++)
    {
        const VcSemanticStruct *structure = &model->structs[class_index];
        if (!structure->is_class || structure->is_abstract ||
            !class_is_same_or_derived(model, class_index, root_owner))
            continue;

        size_t owner_index = 0;
        size_t field_index = 0;
        if (!find_virtual_event_implementation_for_class(model, class_index,
                root_owner, root_field, &owner_index, &field_index))
            continue;
        VcSemanticField *event = &model->structs[owner_index].fields[field_index];
        if (event->is_abstract || !event->is_custom_event)
            continue;
        if (remove_accessor)
            event->event_remove_reachable = true;
        else
            event->event_add_reachable = true;
        if (!analyze_custom_event_accessor(model, owner_index, field_index,
                remove_accessor, diagnostic))
            return false;
    }
    return true;
}

static bool mark_interface_dispatch_reachable(
    VcSemanticModel *model,
    size_t interface_method_index,
    VcSemanticDiagnostic *diagnostic)
{
    if (interface_method_index >= model->method_count)
        return false;
    const VcSemanticMethod *required = &model->methods[interface_method_index];
    if (!required->is_interface_method || !required->has_owner_struct)
        return false;
    const size_t interface_index = required->owner_struct_index;

    for (size_t type_index = 0; type_index < model->struct_count; type_index++)
    {
        const VcSemanticStruct *structure = &model->structs[type_index];
        if (structure->is_interface || structure->is_enum || structure->is_delegate ||
            (structure->is_class && structure->is_abstract) ||
            !type_implements_interface(model, type_index, interface_index))
            continue;

        const size_t implementation = find_interface_implementation_for_type(
            model, type_index, interface_method_index, NULL);
        if (implementation == (size_t)-1)
            continue;
        model->methods[implementation].reachable = true;
        if (!analyze_method(model, implementation, diagnostic))
            return false;
    }
    return true;
}

static bool mark_interface_property_dispatch_reachable(
    VcSemanticModel *model,
    size_t interface_index,
    size_t interface_property_index,
    VcSemanticDiagnostic *diagnostic)
{
    if (interface_index >= model->struct_count ||
        !model->structs[interface_index].is_interface ||
        interface_property_index >= model->structs[interface_index].property_count)
        return false;

    for (size_t type_index = 0; type_index < model->struct_count; type_index++)
    {
        const VcSemanticStruct *structure = &model->structs[type_index];
        if (structure->is_interface || structure->is_enum || structure->is_delegate ||
            (structure->is_class && structure->is_abstract) ||
            !type_implements_interface(model, type_index, interface_index))
            continue;

        size_t owner_index = 0;
        size_t property_index = 0;
        if (!find_interface_property_implementation_for_type(model, type_index,
                interface_index, interface_property_index, &owner_index, &property_index))
            continue;
        VcSemanticProperty *property = &model->structs[owner_index].properties[property_index];
        property->getter_reachable = true;
        if (!analyze_property_getter(model, owner_index, property_index, diagnostic))
            return false;
    }
    return true;
}

static bool mark_interface_event_dispatch_reachable(
    VcSemanticModel *model,
    size_t interface_index,
    size_t interface_field_index,
    bool remove_accessor,
    VcSemanticDiagnostic *diagnostic)
{
    if (interface_index >= model->struct_count ||
        !model->structs[interface_index].is_interface ||
        interface_field_index >= model->structs[interface_index].field_count)
        return false;

    for (size_t type_index = 0; type_index < model->struct_count; type_index++)
    {
        const VcSemanticStruct *structure = &model->structs[type_index];
        if (structure->is_interface || structure->is_enum || structure->is_delegate ||
            (structure->is_class && structure->is_abstract) ||
            !type_implements_interface(model, type_index, interface_index))
            continue;

        size_t owner_index = 0;
        size_t field_index = 0;
        if (!find_interface_event_implementation_for_type(model, type_index,
                interface_index, interface_field_index, &owner_index, &field_index))
            continue;
        VcSemanticField *event = &model->structs[owner_index].fields[field_index];
        if (!event->is_custom_event || event->is_abstract)
            continue;
        if (remove_accessor)
            event->event_remove_reachable = true;
        else
            event->event_add_reachable = true;
        if (!analyze_custom_event_accessor(model, owner_index, field_index,
                remove_accessor, diagnostic))
            return false;
    }
    return true;
}

static VcSemanticType analyze_expression(VcSemanticContext *context, const VcAstNode *expression);
static VcSemanticType analyze_expression_with_target(VcSemanticContext *context, const VcAstNode *expression, VcSemanticType target_type);
